$pageTitle = "The Works of William Shakespeare (Cambridge Ed., Vol. 5) - The true Tragedie of Richard Duke of Yorke, and the good King Henry the Sixt. | Hesten's Learning";
?>
<div class="cdn-book-reader-content">
    <div class="lexile-version active" data-lexile="original" data-lexile-label="Original (1320L)">
        <div class="chapter">
<h2 class="smallprint" title="The true Tragedie of Richard Duke of Yorke, and the good King Henry the Sixt." id="ide">
The true Tragedie of Richard Duke <i>of Yorke, and the good King</i> Henry
the Sixt.</h2></div>

<div class="right toppada"><small><a href="#idtoc" class="pginternal">toc</a></small></div>

<div class="sd-schg">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> I.
<span class="dnavigatenf">eaa</span></h3>

Enter <i>Richard</i> Duke of <i>Yorke</i>, the Earle of <i>Warwicke</i>, <i>The Duke of Norffolke</i>, <i>Marquis Montague</i>, <i>Edward Earl of March</i>, <i>Crookeback Richard</i>, and the yong <i>Earle of Rutland</i>, with Drumme and Souldiers, with white Roses in their hats.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaa001" id="lnum-eaa001">♦</a>
 <span class="sd-cn">Warwike.</span>
  I wonder how the king escapt our hands.</div>

<div class="dverse1"><span class="sd-cn">Yorke.</span>
 Whilst we pursude the horsemen of the North,</div>
<div class="dverse">He slilie stole awaie and left his men:</div>
<div class="dverse">Whereat the great Lord of Northumland,</div>
<div class="dverse"><span class="lnum">5</span>
 Whose warlike eares could neuer brooke retrait,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaa006" id="lnum-eaa006">♦</a>
 Chargde our maine battels front, and therewith him</div>
<div class="dverse">Lord <i>Stafford</i> and Lord <i>Clifford</i> all abrest</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaa008" id="lnum-eaa008">♦</a>
 Brake in and were by the hands of common Souldiers (slain.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Lord <i>Staffords</i> father Duke of <i>Buckhingham</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaa010" id="lnum-eaa010">10</a>
 Is either slaine or wounded dangerouslie,</div>
<div class="dverse">I cleft his Beuer with a downe right blow:</div>
<div class="dverse">Father that this is true behold his bloud.</div>

<div class="dverse1"><span class="sd-cn">Mont.</span>
 And brother heeres the Earle of <i>Wiltshires</i></div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaa014" id="lnum-eaa014">♦</a>
 Bloud, whom I encountred as the battailes ioind.</div>

<div class="dverse1"><span class="lnum">15</span>
 <span class="sd-cn">Rich.</span>
  Speake thou for me and tell them what I did.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaa016" id="lnum-eaa016">♦</a>
 <span class="sd-cn">York.</span>
 What is your grace dead my L. of <i>Summerset</i>?</div>

<div class="dverse1"><span class="sd-cn">Norf.</span>
 Such hope haue all the line of <i>Iohn</i> of <i>Gawnt</i>.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Thus doe I hope to shape king <i>Henries</i> head.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 And so do <i>I</i> victorious prince of Yorke,</div>
<div class="dverse"><span class="lnum">20</span>
 Before I see thee seated in that throne</div>
<div class="dverse">
 Which now the house of <i>Lancaster</i> vsurpes,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaa022" id="lnum-eaa022">♦</a>
 I vow by heauens these eies shal neuer close.</div>
<div class="dverse">This is the pallace of that fearefull king,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaa024" id="lnum-eaa024">♦</a>
 And that the regall chaire? Possesse it Yorke:</div>
<div class="dverse"><span class="lnum">25</span>
 For this is thine and not king <i>Henries</i> heires.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Assist me then sweet <i>Warwike</i>, and I wil:</div>
<div class="dverse">For hither are we broken in by force.</div>

<div class="dverse1"><span class="sd-cn">Norf.</span>
 Weele all assist thee, and he that flies shall die.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Thanks gentle <i>Norffolke</i>. Staie by me my Lords,</div>
<div class="dverse"><span class="lnum">30</span>
 and souldiers staie you heere and lodge this night:</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 And when the king comes offer him no</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaa032" id="lnum-eaa032">♦</a>
 Violence, vnlesse he seek to put vs out by force.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaa033" id="lnum-eaa033">♦</a>
 <span class="sd-cn">Rich.</span>
  Armde as we be, lets staie within this house?</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 The bloudie parlement shall this be calde,</div>
<div class="dverse"><span class="lnum">35</span>
 Vnlesse <i>Plantagenet</i> Duke of Yorke be king</div>
<div class="dverse">And bashfull <i>Henrie</i> be deposde, whose cowardise</div>
<div class="dverse">Hath made vs by-words to our enemies.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Then leaue me not my Lords: for now I meane</div>
<div class="dverse">To take possession of my right.</div>

<div class="dverse1"><span class="lnum">40</span>
 <span class="sd-cn">War.</span>
  Neither the king, nor him that loues him best,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaa041" id="lnum-eaa041">♦</a>
 The proudest burd that holds vp <i>Lancaster</i>.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaa042" id="lnum-eaa042">♦</a>
 Dares stirre a wing if <i>Warwike</i> shake his bels.</div>
<div class="dverse">Ile plant <i>Plantagenet</i>: and root him out who dares?</div>
<div class="dverse">Resolue thee <i>Richard</i>: Claime the English crowne.</div>

<div class="sd-entry">Enter king <i>Henrie</i> the sixt, with the Duke of <i>Excester</i>, The Earle of <i>Northumberland</i>, the Earle of <i>Westmerland</i>
and <i>Clifford</i>, the Earle of <i>Cumberland</i> with red Roses in their hats.</div>

<div class="dverse1"><span class="lnum">45</span>
 <span class="sd-cn">King.</span>
  Looke Lordings where the sturdy rebel sits,</div>
<div class="dverse">Euen in the chaire of state: belike he meanes</div>
<div class="dverse">Backt by the power of <i>Warwike</i> that false peere,</div>
<div class="dverse">To aspire vnto the crowne, and raigne as king.</div>
<div class="dverse">Earle of <i>Northumberland</i>, he slew thy father.</div>
<div class="dverse"><span class="lnum">50</span>
 And thine <i>Clifford</i>: and you both haue vow’d reuenge,</div>
<div class="dverse">On him, his sonnes, his fauorites, and his friends.</div>

<div class="dverse1"><span class="sd-cn">Northu.</span>
 And if I be not, heauens be reuengd on me.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 The hope thereof, makes <i>Clifford</i> mourn in steel.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaa054" id="lnum-eaa054">♦</a>
 <span class="sd-cn">West.</span>
  What? shall we suffer this, lets pull him downe.</div>
<div class="dverse"><span class="lnum">55</span>
 My hart for anger breakes, I cannot speake.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Be patient gentle Earle of <i>Westmerland</i>.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 Patience is for pultrouns such as he</div>
<div class="dverse">He durst not sit there had your father liu’d?</div>
<div class="dverse">My gratious Lord: here in the Parlement,</div>
<div class="dverse"><span class="lnum" id="lnum-eaa060">60</span>
 Let vs assaile the familie of Yorke.</div>

<div class="dverse1"><span class="sd-cn">North.</span>
 Well hast thou spoken cosen, be it so.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 O know you not the Cittie fauours them,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaa063" id="lnum-eaa063">♦</a>
 And they haue troopes of soldiers at their becke?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaa064" id="lnum-eaa064">♦</a>
 <span class="sd-cn">Exet.</span>
  But when the D. is slaine, theile quicklie flie.</div>

<div class="dverse1"><span class="lnum">65</span>
 <span class="sd-cn">King.</span>
 Far be it from the thoughtes of <i>Henries</i> hart,</div>
<div class="dverse">To make a shambles of the parlement house.</div>
<div class="dverse">Cosen of <i>Exeter</i>, words, frownes, and threats,</div>
<div class="dverse">Shall be the warres that Henrie meanes to vse.</div>
<div class="dverse">Thou factious duke of Yorke, descend my throne,</div>
<div class="dverse"><span class="lnum">70</span>
 I am thy soueraigne.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Thou art deceiu’d: I am thine.</div>

<div class="dverse1"><span class="sd-cn">Exet.</span>
 For shame come downe he made thee D. of (<i>York</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaa073" id="lnum-eaa073">♦</a>
 <span class="sd-cn">York.</span>
  Twas mine inheritance as the kingdome is.</div>

<div class="dverse1"><span class="sd-cn">Exet.</span>
 Thy father was a traytor to the crowne.</div>

<div class="dverse1"><span class="lnum">75</span>
 <span class="sd-cn">War.</span>
 <i>Exeter</i> thou art a traitor to the crowne.</div>
<div class="dverse">In following this vsurping <i>Henry</i>.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 Whom should he follow but his naturall king.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaa078" id="lnum-eaa078">♦</a>
 <span class="sd-cn">War.</span>
 True <i>Clif.</i> and that is <i>Richard</i> Duke of Yorke.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaa079" id="lnum-eaa079">♦</a>
 <span class="sd-cn">King.</span>
  And shall I stande while thou sittest in my</div>
<div class="dverse"><span class="lnum">80</span>
 throne?</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Content thy selfe it must and shall be so.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaa082" id="lnum-eaa082">♦</a>
 <span class="sd-cn">War.</span>
 Be Duke of <i>Lancaster</i>, let him be king.</div>

<div class="dverse1"><span class="sd-cn">West.</span>
 Why? he is both king &amp; Duke of <i>Lancaster</i>,</div>
<div class="dverse">And that the Earle of <i>Westmerland</i> shall mainetaine.</div>

<div class="dverse1"><span class="lnum">85</span>
 <span class="sd-cn">War.</span>
 And <i>Warwike</i> shall disproue it. You forget</div>
<div class="dverse">That we are those that chaste you from the field</div>
<div class="dverse">And slew your father, and with colours spred,</div>
<div class="dverse">Marcht through the Cittie to the pallas gates.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaa089" id="lnum-eaa089">♦</a>
 <span class="sd-cn">Nor.</span>
 No <i>Warwike</i> I remember it to my griefe,</div>
<div class="dverse"><span class="lnum">90</span>
 And by his soule thou and thy house shall rew it.</div>

<div class="dverse1"><span class="sd-cn">West.</span>
 <i>Plantagenet</i> of thee and of thy sonnes,</div>
<div class="dverse">Thy kinsmen and thy friendes, Ile haue more liues,</div>
<div class="dverse">Then drops of bloud were in my fathers vaines.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 Vrge it no more, least in reuenge thereof,</div>
<div class="dverse">I send thee <i>Warwike</i> such a messenger,</div>
<div class="dverse"><span class="lnum">95</span>
 As shall reueng his death before I stirre.</div>

<div class="dverse1" id="lnum-eaa096"><span class="sd-cn">War.</span>
 Poore <i>Clifford</i>, how I skorn thy worthles threats</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Wil ye we shew our title to the crowne,</div>
<div class="dverse">Or else our swords shall plead it in the field?</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 What title haste thou traitor to the Crowne?</div>
<div class="dverse"><span class="lnum">100</span>
 Thy father was as thou art Duke of <i>Yorke</i>,</div>
<div class="dverse">Thy grandfather <i>Roger Mortimer</i> earle of <i>March</i>,</div>
<div class="dverse">I am the sonne of Henrie the Fift who tamde the <i>French</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaa103" id="lnum-eaa103">♦</a>
 And made the Dolphin stoope, and seazd vpon their</div>
<div class="dverse">Townes and prouinces.</div>

<div class="dverse1"><span class="lnum">105</span>
 <span class="sd-cn">War.</span>
 Talke not of <i>France</i> since thou hast lost it all.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 The Lord protector lost it and not I,</div>
<div class="dverse">When I was crownd I was but nine months old.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaa108" id="lnum-eaa108">♦</a>
 <span class="sd-cn">Rich.</span>
  You are olde enough now and yet me thinkes you lose,</div>
<div class="dverse">Father teare the Crowne from the Vsurpers head.</div>

<div class="dverse1"><span class="lnum">110</span>
 <span class="sd-cn">Edw.</span>
  Do so sweet father, set it on your head.</div>

<div class="dverse1"><span class="sd-cn">Mont.</span>
 Good brother as thou lou’st &amp; honorst armes,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaa112" id="lnum-eaa112">♦</a>
 Lets fight it out and not stand cauilling thus.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Sound drums and trumpets &amp; the king will fly.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Peace sonnes:</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaa115" id="lnum-eaa115">115</a>
 <span class="sd-cn">Northum.</span>
  Peace thou and giue king Henry leauē to speake.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaa116" id="lnum-eaa116">♦</a>
 <span class="sd-cn">King.</span>
 Ah <i>Plantagenet</i>, why seekest thou to depose (me?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaa117" id="lnum-eaa117">♦</a>
 Are we not both both <i>Plantagenets</i> by birth,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaa118" id="lnum-eaa118">♦</a>
 And from two brothers lineallie discent?</div>
<div class="dverse">Suppose by right and equitie thou be king,</div>
<div class="dverse"><span class="lnum">120</span>
 Thinkst thou that I will leaue my kinglie seate</div>
<div class="dverse">Wherein my father and my grandsire sat?</div>
<div class="dverse">No, first shall warre vnpeople this my realme,</div>
<div class="dverse">I and our colours often borne in <i>France</i>,</div>
<div class="dverse">And now in <i>England</i> to our harts great sorrow</div>
<div class="dverse"><span class="lnum">125</span>
 Shall be my winding sheete, why faint you Lords?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaa126" id="lnum-eaa126">♦</a>
 My titles better farre than his.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Proue it <i>Henrie</i> and thou shalt be king?</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Why <i>Henrie</i> the fourth by conquest got the Crowne.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaa129" id="lnum-eaa129">♦</a>
 <span class="sd-cn">York.</span>
  T‛was by rebellion gainst his soueraigne.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 I know not what to saie my titles weake,</div>
<div class="dverse">Tell me maie not a king adopt an heire?</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 What then?</div>

<div class="dverse1" id="lnum-eaa133"><span class="sd-cn">King.</span>
 Then am I lawfull king  For <i>Richard</i></div>
<div class="dverse">The second in the view of manie Lords</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaa135" id="lnum-eaa135">135</a>
 Resignde the Crowne to <i>Henrie</i> the fourth,</div>
<div class="dverse">Whose heire my Father was, and I am his.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 I tell thee he rose against him being his</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaa138" id="lnum-eaa138">♦</a>
 Soueraigne, &amp; made him to resigne the crown perforce.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Suppose my Lord he did it vnconstrainde,</div>
<div class="dverse"><span class="lnum">140</span>
 Thinke you that were preiudiciall to the Crowne?</div>

<div class="dverse1"><span class="sd-cn">Exet.</span>
 No, for he could not resigne the Crowne,</div>
<div class="dverse">But that the next heire must succeed and raigne.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Art thou against vs, Duke of <i>Exceter</i>?</div>

<div class="dverse1"><span class="sd-cn">Exet.</span>
 His is the right, and therefore pardon me.</div>

<div class="dverse1"><span class="lnum">145</span>
 <span class="sd-cn">King.</span>
  All will reuolt from me and turne to him.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaa146" id="lnum-eaa146">♦</a>
 <span class="sd-cn">Northum.</span>
 <i>Plantagenet</i> for all the claime thou laist,</div>
<div class="dverse">Thinke not king <i>Henry</i> shall be thus deposde?</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Deposde he shall be in despight of thee.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaa149" id="lnum-eaa149">♦</a>
 <span class="sd-cn">North.</span>
 Tush <i>Warwike</i>, Thou art deceiued? tis not thy</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaa150" id="lnum-eaa150">150</a>
 Southerne powers of <i>Essex</i>, <i>Suffolk</i>, <i>Norffolke</i>, and of</div>

<div class="dverse"><i>Kent</i>. that makes thee thus presumptuous and proud,</div>
<div class="dverse">Can set the Duke vp in despight of me.</div>

<div class="dverse1"><span class="sd-cn">Cliff.</span>
 King <i>Henrie</i> be thy title right or wrong,</div>
<div class="dverse">Lord <i>Clifford</i> vowes to fight in thy defence.</div>
<div class="dverse"><span class="lnum">155</span>
 Maie that ground gape and swallow me aliue,</div>
<div class="dverse">Where I do kneele to him that slew my father.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 O <i>Clifford</i>, how thy words reuiue my soule.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 <i>Henry</i> of <i>Lancaster</i> resigne thy crowne.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaa159" id="lnum-eaa159">♦</a>
 What mutter you? or what conspire you Lords?</div>

<div class="dverse1"><span class="lnum">160</span>
 <span class="sd-cn">War.</span>
 Doe right vnto this princelie Duke of <i>Yorke</i>,</div>
<div class="dverse">Or I will fill the house with armed men,</div>

<div class="sd-entry">Enter Souldiers.</div>

<div class="dverse">And ouer the chaire of state where now he sits,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaa163" id="lnum-eaa163">♦</a>
 Wright vp his title with thy vsurping bloud.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 O <i>Warwike</i>, heare me speake.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaa165" id="lnum-eaa165">165</a>
 Let me but raigne in quiet whilst I liue.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Confirme the crowne to me and to mine heires</div>
<div class="dverse">And thou shalt raigne in quiet whilst thou liu’st.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Conuey the souldiers hence, and then I will.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Captaine conduct them into <i>Tuthill</i> fieldes.</div>

<div class="dverse1"><span class="lnum">170</span>
 <span class="sd-cn">Clif.</span>
  What wrong is this vnto the Prince your son?</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 What good is this for <i>England</i> and himselfe?</div>

<div class="dverse1"><span class="sd-cn">Northum.</span>
 Base, fearefull, and despairing <i>Henry</i>.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 How hast thou wronged both thy selfe and vs?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaa174" id="lnum-eaa174">♦</a>
 <span class="sd-cn">West.</span>
 I cannot staie to heare these Articles. <span class="sd-verseend"><i>Exit.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaa175" id="lnum-eaa175">175</a>
 <span class="sd-cn">Clif.</span>
  Nor I, Come cosen lets go tell the Queene.</div>

<div class="dverse1"><span class="sd-cn">Northum.</span>
 Be thou a praie vnto the house of <i>Yorke</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaa177" id="lnum-eaa177">♦</a>
 And die in bands for this vnkingly deed. <span class="sd-verseend"><i>Exit.</i></span></div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 In dreadfull warre maist thou be ouercome,</div>
<div class="dverse">Or liue in peace abandon’d and despisde. <span class="sd-verseend"><i>Exit.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaa180" id="lnum-eaa180">180</a>
 <span class="sd-cn">Exet.</span>
  They seeke reuenge, and therefore will not yeeld my Lord.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Ah <i>Exeter</i>?</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Why should you sigh my Lord?</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Not for my selfe Lord <i>Warwike</i>, but my sonne,</div>
<div class="dverse">Whom I vnnaturallie shall disinherit.</div>
<div class="dverse"><span class="lnum">185</span>
 But be it as it maie: I heere intaile the Crowne</div>
<div class="dverse">To thee and to thine heires, conditionallie,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaa187" id="lnum-eaa187">♦</a>
 That here thou take thine oath, to cease these ciuill</div>
<div class="dverse">Broiles, and whilst I liue to honour me as thy king and Soueraigne.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 That oath I willinglie take and will performe.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaa190" id="lnum-eaa190">190</a>
 <span class="sd-cn">War.</span>
 Long liue king <i>Henry</i>. <i>Plantagenet</i> embrace him?</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 And long liue thou and all thy forward sonnes.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Now <i>Yorke</i> and <i>Lancaster</i> are reconcilde.</div>

<div class="dverse1"><span class="sd-cn">Exet.</span>
 Accurst be he that seekes to make them foes, <span class="sd-verseend">Sound trumpets.</span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaa194" id="lnum-eaa194">♦</a>
 <span class="sd-cn">York.</span>
 My Lord Ile take my leaue, for Ile to <i>Wakefield</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaa195" id="lnum-eaa195">195</a>
 To my castell. <span class="sd-verseend"><i>Exit Yorke</i> and his sonnes.</span></div>

<div class="dverse1"><span class="sd-cn">War.</span>
 And Ile keepe <i>London</i> with my souldiers. <span class="sd-verseend"><i>Exit.</i></span></div>

<div class="dverse1"><span class="sd-cn">Norf.</span>
 And <i>I</i>le to <i>Norffolke</i> with my followers. <span class="sd-verseend"><i>Exit.</i></span></div>

<div class="dverse1"><span class="sd-cn">Mont.</span>
 And I to the sea from whence I came. <span class="sd-verseend"><i>Exit.</i></span></div>

<div class="sd-entry">Enter the <i>Queene</i> and the <i>Prince</i>.</div>

<div class="dverse1"><span class="sd-cn">Exet.</span>
 My Lord here comes the Queen, Ile steale away.</div>

<div class="dverse1"><span class="lnum">200</span>
 <span class="sd-cn">King.</span>
 And so will <i>I</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaa201" id="lnum-eaa201">♦</a>
 <span class="sd-cn">Queene.</span>
  Naie staie, or else I follow thee.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Be patient gentle <i>Queene</i>, and then Ile staie.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaa203" id="lnum-eaa203">♦</a>
 <span class="sd-cn">Quee.</span>
  What patience can there? ah timerous man,</div>
<div class="dverse">Thou hast vndoone thy selfe, thy sonne, and me,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaa205" id="lnum-eaa205">205</a>
 And giuen our rights vnto the house of <i>Yorke</i>.</div>
<div class="dverse">Art thou a king and wilt be forst to yeeld?</div>
<div class="dverse">Had I beene there, the souldiers should haue tost</div>
<div class="dverse">Me on their launces points, before I would haue</div>
<div class="dverse">Granted to their wils. The Duke is made</div>
<div class="dverse"><span class="lnum">210</span>
 Protector of the land: Sterne <i>Fawconbridge</i></div>
<div class="dverse">Commands the narrow seas. And thinkst thou then</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaa212" id="lnum-eaa212">♦</a>
 To sseepe secure? I heere diuorce me <i>Henry</i></div>
<div class="dverse">From thy bed, vntill that Act of Parlement</div>
<div class="dverse">Be recalde, wherein thou yeeldest to the house of <i>Yorke</i>.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaa215" id="lnum-eaa215">215</a>
 The Northen Lords that haue forsworne thy colours,</div>
<div class="dverse">Will follow mine if once they see them spred,</div>
<div class="dverse">And spread they shall vnto thy deepe disgrace.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaa218" id="lnum-eaa218">♦</a>
 Come sonne, lets awaie and leaue him heere alone.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Staie gentle <i>Margaret</i>, and here me speake.</div>

<div class="dverse1"><span class="lnum">220</span>
 <span class="sd-cn">Queene.</span>
  Thou hast spoke too much alreadie, therefore be still.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Gentle sonne <i>Edwarde</i>, wilt thou staie with me?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaa222" id="lnum-eaa222">♦</a>
 <span class="sd-cn">Quee.</span>
 I, to be murdred by his enemies. <span class="sd-verseend"><i>Exit.</i></span></div>

<div class="dverse1"><span class="sd-cn">Prin.</span>
 When I returne with victorie from the field,</div>
<div class="dverse">Ile see your Grace, till then Ile follow her.
 <span class="sd-verseend"><i>Exit.</i></span></div>

<div class="dverse1"><span class="lnum">225</span>
 <span class="sd-cn">King.</span>
 Poore <i>Queene</i>, her loue to me and to the prince Her sonne,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaa226" id="lnum-eaa226">♦</a>
 Makes hir in furie thus forget hir selfe.</div>
<div class="dverse">Reuenged maie shee be on that accursed Duke.</div>
<div class="dverse">Come cosen of <i>Exeter</i>, staie thou here,</div>
<div class="dverse">For <i>Clifford</i> and those Northern Lords be gone</div>
<div class="dverse"><span class="lnum">230</span>
 I feare towards <i>Wakefield</i>, to disturbe the Duke.</div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> II.
<span class="dnavigatenf">eab</span></h3>

Enter <i>Edward</i>, and <i>Richard</i>, and <i>Montague</i>.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Brother, and cosen Montague, giue mee leaue to speake.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Nay, I can better plaie the Orator.</div>

<div class="dverse1"><span class="sd-cn">Mont.</span>
 But I haue reasons strong and forceable.</div>

<div class="sd-entry">Enter the Duke of <i>Yorke</i>.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Howe nowe sonnes what at a iarre amongst your selues?</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-eab005" id="lnum-eab005">5</a>
 <span class="sd-cn">Rich.</span>
 No father, but a sweete contention, about that which concernes your selfe and vs, The crowne of England father.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eab008" id="lnum-eab008">♦</a>
 <span class="sd-cn">York.</span>
 The crowne boy, why <i>Henries</i> yet aliue,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eab009" id="lnum-eab009">♦</a>
 And I haue sworne that he shall raigne in quiet till</div>
<div class="dverse"><span class="lnum">10</span>
 His death.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-eab011" id="lnum-eab011">♦</a>
 <span class="sd-cn">Edw.</span>
 But I would breake an hundred othes to raigne one yeare.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 And if it please your grace to giue me leaue,</div>
<div class="dverse">Ile shew your grace the waie to saue your oath,</div>
<div class="dverse"><span class="lnum">15</span>
 And dispossesse king <i>Henrie</i> from the crowne.</div>

<div class="dverse1"><span class="sd-cn">Yorke</span>
 I prethe <i>Dicke</i> let me heare thy deuise.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eab017" id="lnum-eab017">♦</a>
 <span class="sd-cn">Rich.</span>
  Then thus my Lord. An oath is of no moment</div>
<div class="dverse">Being not sworne before a lawfull magistrate.</div>
<div class="dverse"><i>Henry</i> is none but doth vsurpe your right.</div>
<div class="dverse"><span class="lnum">20</span>
 And yet your grace stands bound to him by oath.</div>
<div class="dverse">Then noble father resolue your selfe,</div>
<div class="dverse">And once more claime the crowne.</div>

<div class="dverse1"><span class="sd-cn">Yorke</span>
 <i>I</i>, saist thou so boie? why then it shall be so.</div>
<div class="dverse"><i>I</i> am resolude to win the crowne, or die.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eab025" id="lnum-eab025">25</a>
 Edward, rhou shalt to <i>Edmund Brooke</i> Lord <i>Cobham</i>,</div>
<div class="dverse">With whom the <i>Kentishmen</i> will willinglie rise:</div>
<div class="dverse">Thou cosen <i>Montague</i>, shalt to <i>Norffolke</i> straight,</div>
<div class="dverse">And bid the Duke to muster vppe his souldiers,</div>
<div class="dverse">And come to me to <i>Wakefield</i> presentlie.</div>
<div class="dverse"><span class="lnum">30</span>
 And <i>Richard</i> thou to <i>London</i> strait shalt post,</div>
<div class="dverse">And bid <i>Richard Neuill</i> Earle of <i>Warwike</i></div>
<div class="dverse">To leaue the cittie, and with his men of warre,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eab033" id="lnum-eab033">♦</a>
 To meet me at Saint <i>Albons</i> ten daies hence.</div>
<div class="dverse">My selfe heere in <i>Sandall</i> castell will prouide</div>
<div class="dverse"><span class="lnum">35</span>
 Both men and monie to furder our attempts.</div>
<div class="dverse">Now, what newes?</div>

<div class="sd-entry">Enter a Messenger.</div>

<div class="dverse1"><span class="sd-cn">Mes.</span>
 My Lord, the <i>Queene</i> with thirtie thousand men,</div>
<div class="dverse">Accompanied with the Earles of <i>Cumberland</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eab039" id="lnum-eab039">♦</a>
 <i>Nurthumberland</i> and <i>Westmerland</i>, and others of the</div>
<div class="dverse"><span class="lnum">40</span>
 House of <i>Lancaster</i>, are marching towards <i>Wakefield</i>,</div>
<div class="dverse">To besiedge you in your castell heere.</div>

<div class="sd-entry">Enter sir <i>Iohn</i> and sir <i>Hugh Mortimer</i>.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-eab042" id="lnum-eab042">♦</a>
 <span class="sd-cn">Yorke</span>
 A Gods name, let them come.  Cosen <i>Montague</i>
 post you hence: and boies staie you with me.</div>

<div class="dverse"><a class="lnum pginternal" href="#lnote-eab044" id="lnum-eab044">♦</a>
 Sir <i>Iohn</i> and sir <i>Hugh Mortemers</i> mine vncles,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eab045" id="lnum-eab045">45</a>
 Your welcome to <i>Sandall</i> in an happie houre,</div>
<div class="dverse">The armie of the Queene meanes to besiedge vs.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-eab047" id="lnum-eab047">♦</a>
 Sir <i>Iohn</i>.
 Shee shall not neede my Lorde, weele meete her in the field.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eab048" id="lnum-eab048">♦</a>
 <span class="sd-cn">York</span>
  What with fiue thousand souldiers vncle?</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 I father, with fiue hundred for a need,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eab050" id="lnum-eab050">50</a>
 A womans generall, what should you feare?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eab051" id="lnum-eab051">♦</a>
 <span class="sd-cn">York.</span>
  Indeed, manie braue battels haue I woon</div>
<div class="dverse">In <i>Normandie</i>, when as the enimie</div>
<div class="dverse">Hath bin ten to one, and why should I now doubt</div>
<div class="dverse">Of the like successe? I am resolu’d. Come lets goe.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eab055" id="lnum-eab055">55</a>
 <span class="sd-cn">Edw.</span>
 Lets martch awaie, I heare their drums. <span class="sd-verseend"><i>Exit.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> III.
<span class="dnavigatenf">eac</span></h3>

Alarmes, and then enter the yong Earle of <i>Rutland</i>
and his Tutor.</div>

<div class="dverse1"><span class="sd-cn">Tutor.</span>
 Oh flie my Lord, lets leaue the Castell,</div>
<div class="dverse">And flie to <i>Wakefield</i> straight.</div>

<div class="sd-entry">Enter <i>Clifford</i>.</div>

<div class="dverse1"><span class="sd-cn">Rut.</span>
 O Tutor, looke where bloudie <i>Clifford</i> comes.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eac004" id="lnum-eac004">♦</a>
 <span class="sd-cn">Clif.</span>
  Chaplin awaie, thy Priesthood saues thy life,</div>
<div class="dverse"><span class="lnum">5</span>
 As for the brat of that accursed Duke</div>
<div class="dverse">Whose father slew my father, he shall die.</div>

<div class="dverse1"><span class="sd-cn">Tutor</span>
 Oh <i>Clifford</i> spare this tender Lord, least</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac008" id="lnum-eac008">♦</a>
 Heauen reuenge it on thy head: Oh saue his life.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 Soldiers awaie and drag him hence perforce:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac010" id="lnum-eac010">10</a>
 Awaie with the villaine. <span class="sd-verseend"><i>Exit</i> the Chaplein.</span></div>
<div class="dverse">How now, what dead alreadie? or is it feare that</div>
<div class="dverse">Makes him close his eies? Ile open them.</div>

<div class="dverse1"><span class="sd-cn">Rut.</span>
 So lookes the pent vp Lion on the lambe,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac014" id="lnum-eac014">♦</a>
 And so he walkes insulting ouer his praie,</div>
<div class="dverse"><span class="lnum">15</span>
 And so he turnes againe to rend his limmes in sunder,</div>
<div class="dverse">Oh <i>Clifford</i>, kill me with thy sword, and</div>
<div class="dverse">Not with such a cruell threatning looke,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac018" id="lnum-eac018">♦</a>
 I am too meane a subiect for thy wrath,</div>
<div class="dverse">Be thou reuengde on men, and let me liue.</div>

<div class="dverse1"><span class="lnum">20</span>
 <span class="sd-cn">Clif.</span>
  In vaine thou speakest poore boy: my fathers</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac021" id="lnum-eac021">♦</a>
 Bloud hath stopt the passage where thy words shoulde enter.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eac022" id="lnum-eac022">♦</a>
 <span class="sd-cn">Rut.</span>
  Then let my fathers blood ope it againe? he is a</div>
<div class="dverse">Man, and <i>Clifford</i> cope with him.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 Had I thy brethren here, their liues and thine</div>
<div class="dverse"><span class="lnum">25</span>
 Were not reuenge sufficient for me.</div>
<div class="dverse">Or should <i>I</i> dig vp thy forefathers graues,</div>
<div class="dverse">And hang their rotten coffins vp in chaines,</div>
<div class="dverse">It could not slake mine ire, nor ease my hart.</div>
<div class="dverse">The sight of anie of the house of <i>Yorke</i>,</div>
<div class="dverse"><span class="lnum">30</span>
 Is as a furie to torment my soule.</div>
<div class="dverse">Therefore till <i>I</i> root out that curssed line</div>
<div class="dverse">And leaue not one on earth, <i>I</i>le liue in hell therefore.</div>

<div class="dverse1"><span class="sd-cn">Rut.</span>
 Oh let me praie, before <i>I</i> take my death.</div>
<div class="dverse">To thee <i>I</i> praie: Sweet <i>Clifford</i> pittie me.</div>

<div class="dverse1"><span class="lnum">35</span>
 <span class="sd-cn">Clif.</span>  <i>I</i>, such pitie as my rapiers point affords.</div>

<div class="dverse1"><span class="sd-cn">Rut.</span>
 <i>I</i> neuer did thee hurt, wherefore wilt thou kill mee?</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 Thy father hath.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eac038" id="lnum-eac038">♦</a>
 <span class="sd-cn">Rut.</span>
 But twas ere <i>I</i> was borne:</div>
<div class="dverse">Thou hast one sonne, for his sake pittie me,</div>
<div class="dverse"><span class="lnum">40</span>
 Least in reuenge thereof, sith God is iust,</div>
<div class="dverse">He be as miserablie slaine as <i>I</i>.</div>
<div class="dverse">Oh, let me liue in prison all my daies,</div>
<div class="dverse">And when <i>I</i> giue occasion for offence,</div>
<div class="dverse">Then let me die, for now thou hast no cause.</div>

<div class="dverse1"><span class="lnum">45</span>
 <span class="sd-cn">Clif.</span>
  No cause?  Thy Father slew my father, therefore Die.</div>
<div class="dverse"><i>Plantagenet</i> I come <i>Plantagenet</i>,</div>
<div class="dverse">And this thy sonnes bloud cleauing to my blade,</div>
<div class="dverse">Shall rust vpon my weapon, till thy bloud</div>
<div class="dverse">Congeald with his, doe make me wipe off both. <span class="sd-verseend"><i>Exit.</i></span></div>

<div class="sd-entry">Alarmes, Enter the Duke of <i>Yorke solus</i>.</div>

<div class="dverse1"><span class="lnum">50</span>
 <span class="sd-cn">Yorke</span>
 Ah <i>Yorke</i>, post to thy castell, saue thy life,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac051" id="lnum-eac051">♦</a>
 The goale is lost thou house of <i>Lancaster</i>,</div>
<div class="dverse">Thrise happie chance is it for thee and thine,</div>
<div class="dverse">That heauen abridgde my daies and cals me hence,</div>
<div class="dverse">But God knowes what chance hath betide my sonnes:</div>
<div class="dverse"><span class="lnum">55</span>
 But this I know they haue demeand themselues,</div>
<div class="dverse">Like men borne to renowne by life or death:</div>
<div class="dverse"><i>T</i>hree times this daie came <i>Richard</i> to my sight,</div>
<div class="dverse">And cried courage Father: Victorie or death.</div>
<div class="dverse">And twise so oft came <i>Edward</i> to my view,</div>
<div class="dverse"><span class="lnum">60</span>
 With purple Faulchen painted to the hilts,</div>
<div class="dverse">In bloud of those whom he had slaughtered.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac062" id="lnum-eac062">♦</a>
 Oh harke, <i>I</i> heare the drums? No waie to flie:</div>
<div class="dverse">No waie to saue my life? And heere <i>I</i> staie:</div>
<div class="dverse">And heere my life must end.</div>

<div class="sd-entry">Enter the <i>Queene</i>, <i>Clifford</i>, <i>Northumberland</i>, and souldiers.</div>

<div class="dverse">Come bloudie <i>Clifford</i>, rough <i>Northumberland</i>,</div>
<div class="dverse">I dare your quenchlesse furie to more bloud:</div>
<div class="dverse">This is the But, and this abides your shot.</div>

<div class="dverse1"><span class="sd-cn">Northum.</span>
 Yeeld to our mercies proud <i>Plantagenet</i>.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 I, to such mercie as his ruthfull arme</div>
<div class="dverse"><span class="lnum">70</span>
 With downe right paiment lent vnto my father,</div>
<div class="dverse">Now <i>Phaeton</i> hath tumbled from his carre,</div>
<div class="dverse">And made an euening at the noone tide pricke.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 My ashes like the <i>Phœnix</i> maie bring forth</div>
<div class="dverse">A bird that will reuenge it on you all,</div>
<div class="dverse"><span class="lnum">75</span>
 And in that hope I cast mine eies to heauen,</div>
<div class="dverse">Skorning what ere you can afflict me with:</div>
<div class="dverse">Why staie you Lords? what, multitudes and feare?</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 So cowards fight when they can flie no longer:</div>
<div class="dverse">So Doues doe pecke the Rauens piersing tallents:</div>
<div class="dverse"><span class="lnum">80</span>
 So desperate theeues all hopelesse of their liues,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac081" id="lnum-eac081">♦</a>
 Breath out inuectives gainst the officers.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Oh <i>Clifford</i>, yet bethinke thee once againe,</div>
<div class="dverse">And in thy minde orerun my former time:</div>
<div class="dverse">And bite thy toung that slaunderst him with cowardise,</div>
<div class="dverse"><span class="lnum">85</span>
 Whose verie looke hath made thee quake ere this.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 I will not bandie with thee word for word,</div>
<div class="dverse">But buckle with thee blowes twise two for one.</div>

<div class="dverse1"><span class="sd-cn">Queene.</span>
 Hold valiant <i>Clifford</i> for a thousand causes,</div>
<div class="dverse">I would prolong the traitors life a while.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac090" id="lnum-eac090">90</a>
 Wrath makes him death, speake thou <i>Northumberland</i>.</div>

<div class="dverse1"><span class="sd-cn">Nor.</span>
 Hold <i>Clifford</i>, doe not honour him so much,</div>
<div class="dverse">To pricke thy finger though to wound his hart:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac093" id="lnum-eac093">♦</a>
 What valure were it when a curre doth grin,</div>
<div class="dverse">For one to thrust his hand betweene his teeth,</div>
<div class="dverse"><span class="lnum">95</span>
 When he might spurne him with his foote awaie?</div>
<div class="dverse">Tis warres prise to take all aduantages,</div>
<div class="dverse">And ten to one, is no impeach in warres. <span class="sd-verseend">Fight and take him.</span></div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 I, I, so striues the Woodcocke with the gin.</div>

<div class="dverse1"><span class="sd-cn">North.</span>
 So doth the cunnie struggle with the net.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eac100" id="lnum-eac100">100</a>
 <span class="sd-cn">York.</span>
  So triumphs theeues vpon their conquered</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac101" id="lnum-eac101">♦</a>
 Bootie: So true men yeeld by robbers ouermatcht.</div>

<div class="dverse1"><span class="sd-cn">North.</span>
 What will your grace haue done with him?</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 Braue warriors, <i>Clifford</i> &amp; <i>Northumberland</i></div>
<div class="dverse">Come make him stand vpon this molehill here,</div>
<div class="dverse"><span class="lnum">105</span>
 That aimde at mountaines with outstretched arme,</div>
<div class="dverse">And parted but the shaddow with his hand.</div>
<div class="dverse">Was it you that reuelde in our Parlement,</div>
<div class="dverse">And made a prechment of your high descent?</div>
<div class="dverse">Where are your messe of sonnes to backe you now?</div>
<div class="dverse"><span class="lnum">110</span>
 The wanton <i>Edward</i>, and the lustie <i>George</i>?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac111" id="lnum-eac111">♦</a>
 Or where is that valiant <i>Crookbackt</i> prodegie?</div>
<div class="dverse">Dickey your boy, that with his grumbling voice,</div>
<div class="dverse">Was wont to cheare his Dad in mutinies?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac114" id="lnum-eac114">♦</a>
 Or amongst the rest, where is your darling <i>Rutland</i>?</div>
<div class="dverse"><span class="lnum">115</span>
 Looke <i>Yorke</i>? I dipt this napkin in the bloud,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac116" id="lnum-eac116">♦</a>
 That valiant <i>Clifford</i> with his rapiers point,</div>
<div class="dverse">Made issue from the bosome of thy boy.</div>
<div class="dverse">And if thine eies can water for his death,</div>
<div class="dverse">I giue thee this to drie thy cheeks withall.</div>
<div class="dverse"><span class="lnum">120</span>
 Alas poore <i>Yorke</i>? But that I hate thee much,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac121" id="lnum-eac121">♦</a>
 <i>I</i> should lament thy miserable state?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac122" id="lnum-eac122">♦</a>
 I prethee greeue to make me merrie <i>Yorke</i>?</div>
<div class="dverse">Stamp, raue and fret, that I maie sing and dance.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac124" id="lnum-eac124">♦</a>
 What? hath thy fierie hart so parcht thine entrailes,</div>
<div class="dverse"><span class="lnum">125</span>
 That not a teare can fall for <i>Rutlands</i> death?</div>
<div class="dverse">Thou wouldst be feede I see to make me sport.</div>
<div class="dverse"><i>Yorke</i> cannot speake, vnlesse he weare a crowne.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac128" id="lnum-eac128">♦</a>
 A crowne for <i>Yorke</i>? and Lords bow low to him.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac129" id="lnum-eac129">♦</a>
 So: hold you his hands, whilst <i>I</i> doe set it on.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac130" id="lnum-eac130">130</a>
 I, now lookes he like a king?</div>
<div class="dverse">This is he that tooke king <i>Henries</i> chaire,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac132" id="lnum-eac132">♦</a>
 And this is he was his adopted aire.</div>
<div class="dverse">But how is it that great <i>Plantagenet</i>,</div>
<div class="dverse">Is crownd so soone, and broke his holie oath,</div>
<div class="dverse"><span class="lnum">135</span>
 As I bethinke me you should not be king,</div>
<div class="dverse">Till our <i>Henry</i> had shooke hands with death,</div>
<div class="dverse">And will you impale your head with <i>Henries</i> glorie,</div>
<div class="dverse">And rob his temples of the Diadem</div>
<div class="dverse">Now in his life against your holie oath?</div>
<div class="dverse"><span class="lnum">140</span>
 Oh, tis a fault too too vnpardonable.</div>
<div class="dverse">Off with the crowne, and with the crowne his head,</div>
<div class="dverse">And whilst we breath, take time to doe him dead.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eac143" id="lnum-eac143">♦</a>
 <span class="sd-cn">Clif.</span>
  Thats my office for my fathers death.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 Yet stay: &amp; lets here the Orisons he makes.</div>

<div class="dverse1"><span class="lnum">145</span>
 <span class="sd-cn">York.</span>
 She wolfe of <i>France</i>, but worse than Wolues of <i>France</i>:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac146" id="lnum-eac146">♦</a>
 Whose tongue more poison’d than the Adders tooth:</div>
<div class="dverse">How ill beseeming is it in thy sexe,</div>
<div class="dverse">To triumph like an <i>Amazonian</i> trull</div>
<div class="dverse">Vpon his woes, whom Fortune captiuates?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac150" id="lnum-eac150">150</a>
 But that thy face is visard like, vnchanging,</div>
<div class="dverse">Made impudent by use of euill deeds:</div>
<div class="dverse"><i>I</i> would assaie, proud Queene, to make thee blush:</div>
<div class="dverse">To tell thee of whence thou art, from whom deriu’de,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac154" id="lnum-eac154">♦</a>
 Twere shame enough to shame thee, wert thou not shamelesse.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac155" id="lnum-eac155">155</a>
 Thy father beares the type of king of <i>Naples</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac156" id="lnum-eac156">♦</a>
 Of both the <i>Sissiles</i> and <i>Ierusalem</i>,</div>
<div class="dverse">Yet not so wealthie as an English Yeoman.</div>
<div class="dverse">Hath that poore Monarch taught thee to insult?</div>
<div class="dverse">It needes not, or it bootes thee not proud Queene,</div>
<div class="dverse"><span class="lnum">160</span>
 Vnlesse the Adage must be verifide:</div>
<div class="dverse">That beggers mounted, run their horse to death.</div>
<div class="dverse">Tis beautie, that oft makes women proud,</div>
<div class="dverse">But God he wots thy share thereof is small.</div>
<div class="dverse">Tis gouernment, that makes them most admirde,</div>
<div class="dverse"><span class="lnum">165</span>
 The contrarie doth make thee wondred at.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac166" id="lnum-eac166">♦</a>
 Tis vertue that makes them seeme deuine,</div>
<div class="dverse">The want thereof makes thee abhominable.</div>
<div class="dverse">Thou art as opposite to euerie good,</div>
<div class="dverse">As the <i>Antipodes</i> are vnto vs,</div>
<div class="dverse"><span class="lnum">170</span>
 Or as the south to the Septentrion.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac171" id="lnum-eac171">♦</a>
 Oh Tygers hart wrapt in a womans hide?</div>
<div class="dverse">How couldst thou draine the life bloud of the childe,</div>
<div class="dverse">To bid the father wipe his eies withall,</div>
<div class="dverse">And yet be seene to beare a womans face?</div>
<div class="dverse"><span class="lnum">175</span>
 Women are milde, pittifull, and flexible,</div>
<div class="dverse">Thou indurate, sterne, rough, remorcelesse.</div>
<div class="dverse">Bids thou me rage? why now thou hast thy will.</div>
<div class="dverse">Wouldst haue me weepe? why so thou hast thy wish,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac179" id="lnum-eac179">♦</a>
 For raging windes blowes vp a storme of teares,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac180" id="lnum-eac180">180</a>
 And when the rage alaies the raine begins.</div>
<div class="dverse">These teares are my sweet <i>Rutlands</i> obsequies,</div>
<div class="dverse">And euerie drop begs vengeance as it fals,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac183" id="lnum-eac183">♦</a>
 On thee fell <i>Clifford</i>, and the false French woman.</div>

<div class="dverse1"><span class="sd-cn">North.</span>
 Beshrew me but his passions moue me so,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac185" id="lnum-eac185">185</a>
 As hardlie can I checke mine eies from teares.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 That face of his the hungrie Cannibals</div>
<div class="dverse">Could not haue tucht, would not haue staind with bloud</div>
<div class="dverse">But you are more inhumaine, more inexorable,</div>
<div class="dverse">O ten times more then Tygers of <i>Arcadia</i>.</div>
<div class="dverse"><span class="lnum">190</span>
 See ruthlesse <i>Queene</i> a haplesse fathers teares.</div>
<div class="dverse">This cloth thou dipts in bloud of my sweet boy,</div>
<div class="dverse">And loe with teares I wash the bloud awaie.</div>
<div class="dverse">Keepe thou the napkin and go boast of that,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac194" id="lnum-eac194">♦</a>
 And if thou tell the heauie storie well,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac195" id="lnum-eac195">195</a>
 Vpon my soule the hearers will sheed teares,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac196" id="lnum-eac196">♦</a>
 I, euen my foes will sheed fast falling teares,</div>
<div class="dverse">And saie, alas, it was a pitteous deed.</div>
<div class="dverse">Here, take the crowne, and with the crowne my curse,</div>
<div class="dverse">And in thy need such comfort come to thee,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac200" id="lnum-eac200">200</a>
 As now <i>I</i> reape at thy two cruell hands.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac201" id="lnum-eac201">♦</a>
 Hard-harted <i>Clifford</i>, take me from the world,</div>
<div class="dverse">My soule to heauen, my bloud vpon your heads.</div>

<div class="dverse1"><span class="sd-cn">North.</span>
 Had he bin slaughterman of all my kin,</div>
<div class="dverse"><i>I</i> could not chuse but weepe with him to see,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eac205" id="lnum-eac205">205</a>
 How inlie anger gripes his hart.</div>

<div class="dverse1"><span class="sd-cn">Quee.</span>
 What weeping ripe, my Lorde <i>Northumberland</i>?</div>
<div class="dverse">Thinke but vpon the wrong he did vs all,</div>
<div class="dverse">And that will quicklie drie your melting tears.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eac209" id="lnum-eac209">♦</a>
 <span class="sd-cn">Clif.</span>
 <i>T</i>hears for my oath, thears for my fathers death.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eac210" id="lnum-eac210">210</a>
 <span class="sd-cn">Queene.</span>
  And thears to right our gentle harted kind.</div>

<div class="dverse1"><span class="sd-cn">York.</span>
 Open thy gates of mercie gratious God,</div>
<div class="dverse">My soule flies foorth to meet with thee.</div>

<div class="dverse1"><span class="sd-cn">Queene.</span>
 Off with his head and set it on <i>Yorke</i> Gates,</div>
<div class="dverse">So <i>Yorke</i> maie ouerlooke the towne of <i>Yorke</i>. <span class="sd-verseend"><i>Exeunt omnes.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> IV.
<span class="dnavigatenf">ead</span></h3>

Enter <i>Edward</i> and <i>Richard</i>, with drum and Souldiers.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 After this dangerous fight and haplesse warre,</div>
<div class="dverse">How doth my noble brother <i>Richard</i> fare?</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 I cannot ioy vntil I be resolu’de,</div>
<div class="dverse">Where our right valiant father is become.</div>
<div class="dverse"><span class="lnum">5</span>
 How often did I see him beare himselfe,</div>
<div class="dverse">As doth a lion midst a heard of neat,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ead007" id="lnum-ead007">♦</a>
 So fled his enemies our valiant father,</div>
<div class="dverse">Me thinkes tis pride enough to be his sonne. <span class="sd-verseend">Three sunnes appeare in the aire.</span></div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Loe how the morning opes her golden gates,</div>
<div class="dverse"><span class="lnum">10</span>
 And takes her farewell of the glorious sun,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ead011" id="lnum-ead011">♦</a>
 Dasell mine eies or doe I see three suns?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ead012" id="lnum-ead012">♦</a>
 <span class="sd-cn">Rich.</span>
  Three glorious suns, not seperated by a racking</div>
<div class="dverse">Cloud, but seuered in a pale cleere shining skie.</div>
<div class="dverse">See, see, they ioine, embrace, and seeme to kisse,</div>
<div class="dverse"><span class="lnum">15</span>
 As if they vowde some league inuiolate:</div>
<div class="dverse">Now are they but one lampe, one light, one sun,</div>
<div class="dverse">In this the heauens doth figure some euent.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 <i>I</i> thinke it cites vs brother to the field,</div>
<div class="dverse">That we the sonnes of braue <i>Plantagenet</i>,</div>
<div class="dverse"><span class="lnum">20</span>
 Alreadie each one shining by his meed,</div>
<div class="dverse">May ioine in one and ouerpeere the world,</div>
<div class="dverse">As this the earth, and therefore hence forward,</div>
<div class="dverse">Ile beare vpon my Target, three faire shining suns.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ead024" id="lnum-ead024">♦</a>
 But what art thou? that lookest so heauilie?</div>

<div class="dverse1"><span class="lnum">25</span>
 <span class="sd-cn">Mes.</span>
  Oh one that was a wofull looker on,</div>
<div class="dverse">When as the noble Duke of <i>Yorke</i> was slaine.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 O speake no more, for I can heare no more.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Tell on thy tale, for <i>I</i> will heare it all.</div>

<div class="dverse1"><span class="sd-cn">Mes.</span>
 When as the noble Duke was put to flight,</div>
<div class="dverse"><span class="lnum">30</span>
 And then pursu’de by <i>Clifford</i> and the <i>Queene</i>,</div>
<div class="dverse">And manie souldiers moe, who all at once</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ead032" id="lnum-ead032">♦</a>
 Let driue at him and forst the Duke to yeeld:</div>
<div class="dverse">And then they set him on a molehill there,</div>
<div class="dverse">And crownd the gratious Duke in high despite,</div>
<div class="dverse"><span class="lnum">35</span>
 Who then with teares began to waile his fall.</div>
<div class="dverse">The ruthlesse <i>Queene</i> perceiuing he did weepe,</div>
<div class="dverse">Gaue him a handkercher to wipe his eies,</div>
<div class="dverse">Dipt in the bloud of sweet young <i>Rutland</i></div>
<div class="dverse">By rough <i>Clifford</i> slaine: who weeping tooke it vp.</div>
<div class="dverse"><span class="lnum">40</span>
 <i>T</i>hen through his brest they thrust their bloudy swordes,</div>
<div class="dverse">Who like a lambe fell at the butchers feete.</div>
<div class="dverse">Then on the gates of <i>Yorke</i> they set his head,</div>
<div class="dverse">And there it doth remaine the piteous spectacle</div>
<div class="dverse">That ere mine eies beheld.</div>

<div class="dverse1"><span class="lnum">45</span>
 <span class="sd-cn">Edw.</span>
 Sweet Duke of <i>Yorke</i> our prop to leane vpon,</div>
<div class="dverse">Now thou art gone there is no hope for vs:</div>
<div class="dverse">Now my soules pallace is become a prison.</div>
<div class="dverse">Oh would she breake from compasse of my breast,</div>
<div class="dverse">For neuer shall I haue more ioie.</div>

<div class="dverse1"><span class="lnum">50</span>
 <span class="sd-cn">Rich.</span>
  I cannot weepe, for all my breasts moisture</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ead051" id="lnum-ead051">♦</a>
 Scarse serues to quench my furnace burning hart:</div>
<div class="dverse">I cannot ioie till this white rose be dide,</div>
<div class="dverse">Euen in the hart bloud of the house of <i>Lancaster</i>.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ead054" id="lnum-ead054">♦</a>
 <i>Richard</i>, I bare thy name, and <i>I</i>le reuenge thy death,</div>
<div class="dverse"><span class="lnum">55</span>
 Or die my selfe in seeking of reuenge.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 His name that valiant Duke hath left with thee,</div>
<div class="dverse">His chaire and Dukedome that remaines for me.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Nay, if thou be that princely Eagles bird,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ead059" id="lnum-ead059">♦</a>
 Shew thy descent by gazing gainst the sunne.</div>
<div class="dverse"><span class="lnum">60</span>
 For chaire, and dukedome, Throne and kingdome saie:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ead061" id="lnum-ead061">♦</a>
 For either that is thine, or else thou wert not his?</div>

<div class="sd-entry">Enter the Earle of <i>Warwike</i>, <i>Montague</i>, with drum, ancient, and souldiers.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 How now faire Lords: what fare? what newes abroad?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ead063" id="lnum-ead063">♦</a>
 <span class="sd-cn">Rich.</span>
 Ah <i>Warwike</i>? should we report the balefull</div>
<div class="dverse">Newes, and at each words deliuerance stab poinyardes</div>
<div class="dverse"><span class="lnum">65</span>
 In our flesh till all were told, the words would adde</div>
<div class="dverse">More anguish then the wounds.</div>
<div class="dverse">Ah valiant Lord the Duke of <i>Yorke</i> is slaine.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Ah <i>Warwike Warwike</i>, that <i>Plantagenet</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ead069" id="lnum-ead069">♦</a>
 Which held thee deere: I, euen as his soules redemption,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ead070" id="lnum-ead070">70</a>
 Is by the sterne <i>L. Clifford</i>, done to death.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ead071" id="lnum-ead071">♦</a>
 <span class="sd-cn">War.</span>
  Ten daies a go I drownd those newes in teares.</div>
<div class="dverse">And now to adde more measure to your woes,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ead073" id="lnum-ead073">♦</a>
 I come to tell you things since then befalne.</div>
<div class="dverse">After the bloudie fraie at <i>Wakefield</i> fought,</div>
<div class="dverse"><span class="lnum">75</span>
 Where your braue father breath’d his latest gaspe,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ead076" id="lnum-ead076">♦</a>
 Tidings as swiflie as the post could runne,</div>
<div class="dverse">Was brought me of your losse, and his departure.</div>
<div class="dverse">I then in London keeper of the <i>King</i>,</div>
<div class="dverse">Mustred my souldiers, gathered flockes of friends,</div>
<div class="dverse"><span class="lnum">80</span>
 And verie well appointed as I thought,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ead081" id="lnum-ead081">♦</a>
 Marcht to saint <i>Albons</i> to entercept the <i>Queene</i>,</div>
<div class="dverse">Bearing the <i>King</i> in my behalfe along,</div>
<div class="dverse">For by my scoutes I was aduertised,</div>
<div class="dverse">That she was comming, with a full intent</div>
<div class="dverse"><i>T</i>o dash your late decree in parliament,</div>
<div class="dverse">Touching king <i>Henries</i> heires and your succession.</div>
<div class="dverse">Short tale to make, we at Saint <i>Albons</i> met,</div>
<div class="dverse">Our battles ioinde, and both sides fiercelie fought:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ead089" id="lnum-ead089">♦</a>
 But whether twas the coldnesse of the king,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ead090" id="lnum-ead090">90</a>
 He lookt full gentlie on his warlike <i>Queene</i>,</div>
<div class="dverse">That robde my souldiers of their heated spleene.</div>
<div class="dverse">Or whether twas report of his successe,</div>
<div class="dverse">Or more then common feare of <i>Cliffords</i> rigor,</div>
<div class="dverse">Who thunders to his captaines bloud and death,</div>
<div class="dverse"><span class="lnum">95</span>
 I cannot tell. But to conclude with truth,</div>
<div class="dverse">Their weapons like to lightnings went and came.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ead097" id="lnum-ead097">♦</a>
 Our souldiers like the night Owles lasie flight,</div>
<div class="dverse">Or like an idle thresher with a flaile,</div>
<div class="dverse">Fel gentlie downe as if they smote their friends.</div>
<div class="dverse"><span class="lnum">100</span>
 I cheerd them vp with iustice of the cause,</div>
<div class="dverse">With promise of hie paie and great rewardes,</div>
<div class="dverse">But all in vaine, they had no harts to fight,</div>
<div class="dverse">Nor we in them no hope to win the daie,</div>
<div class="dverse">So that We fled. The king vnto the <i>Queene</i>,</div>
<div class="dverse"><span class="lnum">105</span>
 Lord <i>George</i> your brother, <i>Norffolke</i>, and my selfe,</div>
<div class="dverse">In hast, post hast, are come to ioine with you,</div>
<div class="dverse">For in the marches here we heard you were,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ead108" id="lnum-ead108">♦</a>
 Making another head to fight againe.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Thankes gentle <i>Warwike</i>.</div>
<div class="dverse"><span class="lnum">110</span>
 How farre hence is the Duke with his power?</div>
<div class="dverse">And when came <i>George</i> from <i>Burgundie</i> to <i>England</i>?</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Some fiue miles off the Duke is with his power,</div>
<div class="dverse">But as for your brother he was latelie sent</div>
<div class="dverse">From your kind Aunt, Duches of <i>Burgundie</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ead115" id="lnum-ead115">115</a>
 With aide of souldiers gainst this needfull warre.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Twas ods belike, when valiant <i>Warwike</i> fled.</div>
<div class="dverse">Oft haue I heard thy praises in pursute,</div>
<div class="dverse">But nere till now thy scandall of retire.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Nor now my scandall <i>Richard</i> dost thou heare,</div>
<div class="dverse"><span class="lnum">120</span>
 For thou shalt know that this right hand of mine,</div>
<div class="dverse">Can plucke the Diadem from faint <i>Henries</i> head,</div>
<div class="dverse">And wring the awefull scepter from his fist:</div>
<div class="dverse">Were he as famous and as bold in warre,</div>
<div class="dverse">As he is famde for mildnesse, peace and praier.</div>

<div class="dverse1"><span class="lnum">125</span>
 <span class="sd-cn">Rich.</span>
 I know it well Lord <i>Warwike</i> blame me not,</div>
<div class="dverse">Twas loue I bare thy glories made me speake.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ead127" id="lnum-ead127">♦</a>
 But in this troublous time, whats to be done?</div>
<div class="dverse">Shall we go throw away our coates of steele,</div>
<div class="dverse">And clad our bodies in blacke mourning gownes,</div>
<div class="dverse"><span class="lnum">130</span>
 Numbring our <i>Auemaries</i> with our beades?</div>
<div class="dverse">Or shall we on the helmets of our foes,</div>
<div class="dverse">Tell our deuotion with reuengefull armes?</div>
<div class="dverse"><i>I</i>f for the last, saie <i>I</i>, and to it Lords.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Why therefore <i>Warwike</i> came to find you out,</div>
<div class="dverse"><span class="lnum">135</span>
 And therefore comes my brother <i>Montague</i>.</div>
<div class="dverse">Attend me Lords, the proud insulting Queene,</div>
<div class="dverse">With <i>Clifford</i>, and the haught <i>Northumberland</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ead138" id="lnum-ead138">♦</a>
 And of their feather manie mo proud birdes,</div>
<div class="dverse">Haue wrought the easie melting king like waxe.</div>
<div class="dverse"><span class="lnum">140</span>
 He sware consent to your succession,</div>
<div class="dverse">His oath inrolled in the Parliament.</div>
<div class="dverse">But now to London all the crew are gone,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ead143" id="lnum-ead143">♦</a>
 To frustrate his oath or what besides</div>
<div class="dverse">May make against the house of <i>Lancaster</i>.</div>
<div class="dverse"><span class="lnum">145</span>
 Their power <i>I</i> gesse them fifty thousand strong.</div>
<div class="dverse">Now if the helpe of <i>Norffolke</i> and my selfe,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ead147" id="lnum-ead147">♦</a>
 Can but amount to 48. thousand,</div>
<div class="dverse">With all the friendes that thou braue earle of <i>March</i>,</div>
<div class="dverse">Among the louing Welshmen canst procure,</div>
<div class="dverse"><span class="lnum">150</span>
 Why via, To London will we march amaine,</div>
<div class="dverse">And once againe bestride our foming steedes,</div>
<div class="dverse">And once againe crie charge vpon the foe,</div>
<div class="dverse">But neuer once againe turne backe and flie.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 I, now me thinkes I heare great <i>Warwike</i> speake:</div>
<div class="dverse"><span class="lnum">155</span>
 Nere maie he liue to see a sunshine daie,</div>
<div class="dverse"><i>T</i>hat cries retire, when <i>Warwike</i> bids him stay.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Lord <i>Warwike</i>, on thy shoulder will I leane,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ead158" id="lnum-ead158">♦</a>
 And when thou faints, must <i>Edward</i> fall:</div>
<div class="dverse">Which perill heauen forefend.</div>

<div class="dverse1"><span class="lnum">160</span>
 <span class="sd-cn">War.</span>
 No longer Earle of <i>March</i>, but Duke of <i>Yorke</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ead161" id="lnum-ead161">♦</a>
 The next degree, is Englands royall king:</div>
<div class="dverse">And king of England shalt thou be proclaimde,</div>
<div class="dverse">In euery burrough as we passe along:</div>
<div class="dverse">And he that casts not vp his cap for ioie,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ead165" id="lnum-ead165">165</a>
 Shall for the offence make forfeit of his head.</div>
<div class="dverse">King <i>Edward</i>, valiant <i>Richard</i>, <i>Montague</i>,</div>
<div class="dverse">Stay we no longer dreaming of renowne,</div>
<div class="dverse">But forward to effect these resolutions.</div>

<div class="sd-entry">Enter a Messenger.</div>

<div class="dverse1"><span class="sd-cn">Mes.</span>
 The Duke of <i>Norffolke</i> sends you word by me,</div>
<div class="dverse"><span class="lnum">170</span>
 The <i>Queene</i> is comming with a puissant power,</div>
<div class="dverse">And craues your companie for speedie councell.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ead172" id="lnum-ead172">♦</a>
 <span class="sd-cn">War.</span>
 Why then it sorts braue Lordes. Lets march away.
  <span class="sd-verseend"><i>Exeunt Omnes.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> V.
<span class="dnavigatenf">eae</span></h3>

Enter the <i>King</i> and <i>Queene</i>, Prince <i>Edward</i>, and the Northerne Earles, with drum and Souldiers.</div>

<div class="dverse1"><span class="sd-cn">Quee.</span>
 Welcome my Lord to this braue town of <i>York</i>.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eae002" id="lnum-eae002">♦</a>
 Yonders the head of that ambitious enemie,</div>
<div class="dverse">That sought to be impaled with your crowne.</div>
<div class="dverse">Doth not the obiect please your eie my Lord?</div>

<div class="dverse1"><span class="lnum">5</span>
 <span class="sd-cn">King.</span>
  Euen as the rockes please them that feare their wracke.</div>
<div class="dverse">Withhold reuenge deare God, tis not my fault,</div>
<div class="dverse">Nor wittinglie haue I infringde my vow.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 My gratious Lord, this too much lenitie,</div>
<div class="dverse">And harmefull pittie must be laid aside,</div>
<div class="dverse"><span class="lnum">10</span>
 To whom do Lyons cast their gentle lookes?</div>
<div class="dverse">Not to the beast that would vsurpe his den.</div>
<div class="dverse">Whose hand is that the sauage Beare doth licke?</div>
<div class="dverse">Not his that spoiles his young before his face.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eae014" id="lnum-eae014">♦</a>
 Whose scapes the lurking serpentes mortall sting?</div>
<div class="dverse"><span class="lnum">15</span>
 Not he that sets his foot vpon her backe.</div>
<div class="dverse">The smallest worme will turne being troden on,</div>
<div class="dverse">And Doues will pecke, in rescue of their broode.</div>
<div class="dverse">Ambitious <i>Yorke</i> did leuell at thy Crowne,</div>
<div class="dverse">Thou smiling, while he knit his angrie browes.</div>
<div class="dverse"><span class="lnum">20</span>
 He but a Duke, would haue his sonne a king,</div>
<div class="dverse">And raise his issue like a louing sire.</div>
<div class="dverse">Thou being a king blest with a goodlie sonne,</div>
<div class="dverse">Didst giue consent to disinherit him,</div>
<div class="dverse">Which argude thee a most vnnaturall father.</div>
<div class="dverse"><span class="lnum">25</span>
 Vnreasonable creatures feed their yong,</div>
<div class="dverse">And though mans face be fearefull to their eies,</div>
<div class="dverse">Yet in protection of their tender ones,</div>
<div class="dverse">Who hath not seene them euen with those same wings</div>
<div class="dverse">Which they haue sometime vsde in fearefull flight,</div>
<div class="dverse"><span class="lnum">30</span>
 Make warre with him, that climes vnto their nest,</div>
<div class="dverse">Offring their owne liues in their yongs defence?</div>
<div class="dverse">For shame my Lord, make them your president,</div>
<div class="dverse">Were it not pittie that this goodlie boy,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eae034" id="lnum-eae034">♦</a>
 should lose his birth right through his fathers fault?</div>
<div class="dverse"><span class="lnum">35</span>
 And long hereafter saie vnto his child,</div>
<div class="dverse">What my great grandfather and grandsire got,</div>
<div class="dverse">My carelesse father fondlie gaue awaie?</div>
<div class="dverse">Looke on the boy and let his manlie face,</div>
<div class="dverse">Which promiseth successefull fortune to vs all,</div>
<div class="dverse"><span class="lnum">40</span>
 Steele thy melting thoughtes,</div>
<div class="dverse">To keepe thine owne, and leaue thine owne with him.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Full wel hath <i>Clifford</i> plaid the Orator,</div>
<div class="dverse">Inferring arguments of mighty force.</div>
<div class="dverse">But tell me, didst thou neuer yet heare tell,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eae045" id="lnum-eae045">45</a>
 That things euill got had euer bad successe,</div>
<div class="dverse">And happie euer was it for that sonne,</div>
<div class="dverse">Whose father for his hoording went to hell?</div>
<div class="dverse">I leaue my sonne my vertuous deedes behind,</div>
<div class="dverse">And would my father had left me no more,</div>
<div class="dverse"><span class="lnum">50</span>
 For all the rest is held at such a rate,</div>
<div class="dverse">As askes a thousand times more care to keepe,</div>
<div class="dverse">Then maie the present profit counteruaile.</div>
<div class="dverse">Ah cosen <i>Yorke</i>, would thy best friendes did know,</div>
<div class="dverse">How it doth greeue me that thy head stands there.</div>

<div class="dverse1"><span class="lnum">55</span>
 <span class="sd-cn">Quee.</span>
  My Lord, this harmefull pittie makes your followers faint.</div>
<div class="dverse">You promisde knighthood to your princelie sonne.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eae057" id="lnum-eae057">♦</a>
 Vnsheath your sword and straight doe dub him knight.</div>
<div class="dverse">Kneele downe <i>Edward</i>.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 <i>Edward Plantagenet</i>, arise a knight,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eae060" id="lnum-eae060">60</a>
 And learne this lesson boy, draw thy sword in right</div>

<div class="dverse1"><span class="sd-cn">Prince.</span>
 My gratious father by your kingly leaue,</div>
<div class="dverse">Ile draw it as apparant to the crowne,</div>
<div class="dverse">And in that quarrel vse it to the death.</div>

<div class="dverse1"><span class="sd-cn">Northum.</span>
 Why that is spoken like a toward prince.</div>

<div class="sd-entry">Enter a Messenger.</div>

<div class="dverse1"><span class="lnum">65</span>
 <span class="sd-cn">Mes.</span>
  Royall commaunders be in readinesse,</div>
<div class="dverse">For with a band of fiftie thousand men,</div>
<div class="dverse">Comes <i>Warwike</i> backing of the Duke of <i>Yorke</i>.</div>
<div class="dverse">And in the townes whereas they passe along,</div>
<div class="dverse">Proclaimes him king, and manie flies to him,</div>
<div class="dverse"><span class="lnum">70</span>
 Prepare your battels, for they be at hand.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 I would your highnesse would depart the field,</div>
<div class="dverse">The <i>Queene</i> hath best successe when you are absent.</div>

<div class="dverse1"><span class="sd-cn">Quee.</span>
 Do good my Lord, and leaue vs to our fortunes.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eae074" id="lnum-eae074">♦</a>
 <span class="sd-cn">King.</span>
  Why thats my fortune, therefore Ile stay still.</div>

<div class="dverse1"><span class="lnum">75</span>
 <span class="sd-cn">Clif.</span>
  Be it with resolution then to fight.</div>

<div class="dverse1" id="lnum-eae076"><span class="sd-cn">Prince.</span>
 Good father cheere these noble Lords,</div>
<div class="dverse">Vnsheath your sword, sweet father crie Saint <i>George</i>.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 Pitch we our battell heere, for hence wee will not moue.</div>

<div class="sd-entry">Enter the house of <i>Yorke</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eae079" id="lnum-eae079">♦</a>
 <span class="sd-cn">Edward.</span>
 Now periurde <i>Henrie</i> wilt thou yeelde thy crowne,</div>
<div class="dverse"><span class="lnum">80</span>
 And kneele for mercie at thy soueraignes feete?</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 Go rate thy minions proud insulting boy,</div>
<div class="dverse">Becomes it thee to be thus malepert,</div>
<div class="dverse">Before thy king and lawfull soueraigne?</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 <i>I</i> am his king, and he should bend his knee,</div>
<div class="dverse"><span class="lnum">85</span>
 I was adopted heire by his consent.</div>

<div class="dverse1"><span class="sd-cn">George.</span>
 Since when he hath broke his oath.</div>
<div class="dverse">For as we heare you that are king</div>
<div class="dverse">Though he doe weare the Crowne,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eae089" id="lnum-eae089">♦</a>
 Haue causde him by new act of Parlement</div>
<div class="dverse"><span class="lnum">90</span>
 To blot our brother out, and put his owne son in.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-eae091" id="lnum-eae091">♦</a>
 <span class="sd-cn">Clif.</span>
 And reason <i>George</i>. Who should succeede the father but the son?</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-eae092" id="lnum-eae092">♦</a>
 <span class="sd-cn">Rich.</span>
 Are you their butcher?</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-eae093" id="lnum-eae093">♦</a>
 <span class="sd-cn">Clif.</span>
 <i>I Crookbacke</i>, here I stand to answere thee, or any of your sort.</div>

<div class="dprose1"><span class="sd-cn">Rich.</span>
 Twas you that kild yong <i>Rutland</i>, was it not?</div>

<div class="dprose1"><span class="lnum">95</span>
 <span class="sd-cn">Clif.</span>
 Yes, and old <i>Yorke</i> too, and yet not satisfide.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-eae096" id="lnum-eae096">♦</a>
 <span class="sd-cn">Rich.</span>
 For Gods sake Lords giue synald to the fight.</div>

<div class="dprose1"><span class="sd-cn">War.</span>
 What saiest thou <i>Henry</i>? wilt thou yeelde thy crowne?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eae098" id="lnum-eae098">♦</a>
 <span class="sd-cn">Queen.</span>
 What, long tongde <i>War.</i> dare you speake?</div>
<div class="dverse">When you and <i>I</i> met at saint <i>Albones</i> last,</div>
<div class="dverse"><span class="lnum">100</span>
 Your legs did better seruice than your hands.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eae101" id="lnum-eae101">♦</a>
 <span class="sd-cn">War.</span>
  I, then twas my turne to flee, but now tis thine.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eae102" id="lnum-eae102">♦</a>
 <span class="sd-cn">Clif.</span>
  You said so much before, and yet you fled.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eae103" id="lnum-eae103">♦</a>
 <span class="sd-cn">War.</span>
 Twas not your valour <i>Clifford</i>, that droue mee thence.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eae104" id="lnum-eae104">♦</a>
 <span class="sd-cn">Northum.</span>
 No, nor your manhood <i>Warwike</i>, that could make you staie.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eae105" id="lnum-eae105">105</a>
 <span class="sd-cn">Rich.</span>
 <i>Northumberland</i>, <i>Northumberland</i>, wee holde</div>
<div class="dverse">Thee reuerentlie. Breake off the parlie, for scarse</div>
<div class="dverse">I can refraine the execution of my big swolne</div>
<div class="dverse">Hart, against that <i>Clifford</i> there, that</div>
<div class="dverse">Cruell child-killer.</div>

<div class="dverse1"><span class="lnum">110</span>
 <span class="sd-cn">Clif.</span>
  Why I kild thy father, calst thou him a child?</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 I like a villaine, and a trecherous coward,</div>
<div class="dverse">As thou didst kill our tender brother <i>Rutland</i>.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eae113" id="lnum-eae113">♦</a>
 But ere sunne set Ile make thee curse the deed.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eae114" id="lnum-eae114">♦</a>
 <span class="sd-cn">King.</span>
  Haue doone with wordes great Lordes, and</div>
<div class="dverse">Heare me speake.</div>

<div class="dverse1"><span class="lnum">115</span>
 <span class="sd-cn">Queen.</span>
  Defie them then, or else hold close thy lips.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 I prethe giue no limits to my tongue,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eae117" id="lnum-eae117">♦</a>
 I am a king and priuiledge to speake.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 My Lord the wound that bred this meeting here</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eae119" id="lnum-eae119">♦</a>
 Cannot be cru’d with words, therefore be still.</div>

<div class="dverse1"><span class="lnum">120</span>
 <span class="sd-cn">Rich.</span>
  Then executioner vnsheath thy sword,</div>
<div class="dverse">By him that made vs all I am resolu’de,</div>
<div class="dverse">That <i>Cliffords</i> manhood hangs vpon his tongue.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 What saist thou <i>Henry</i>, shall <i>I</i> haue my right or no?</div>
<div class="dverse">A thousand men haue broke their fast to daie,</div>
<div class="dverse"><span class="lnum">125</span>
 That nere shall dine, vnlesse thou yeeld the crowne.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 If thou denie their blouds be on thy head,</div>
<div class="dverse">For <i>Yorke</i> in iustice puts his armour on.</div>

<div class="dverse1"><span class="sd-cn">Prin.</span>
 If all be right that <i>Warwike</i> saies is right,</div>
<div class="dverse">There is no wrong but all things must be right.</div>

<div class="dverse1"><span class="lnum">130</span>
 <span class="sd-cn">Rich.</span>
  Whosoeuer got thee, there thy mother stands,</div>
<div class="dverse">For well I wot thou hast thy mothers tongue.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 But thou art neither like thy sire nor dam.</div>
<div class="dverse">But like a foule mishapen stygmaticke</div>
<div class="dverse">Markt by the destinies to be auoided,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eae135" id="lnum-eae135">135</a>
 As venome Todes, or Lizards fainting lookes.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Iron of <i>Naples</i>, hid with English gilt,</div>
<div class="dverse">Thy father beares the title of a king,</div>
<div class="dverse">As if a channell should be calde the Sea;</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eae139" id="lnum-eae139">♦</a>
 Shames thou not, knowing from whence thou art de-</div>
<div class="dverse"><span class="lnum">140</span>
 Riu’de, to parlie thus with Englands lawfull heires?</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 A wispe of straw were worth a thousand crowns,</div>
<div class="dverse"><i>T</i>o make that shamelesse callet know her selfe,</div>
<div class="dverse">Thy husbands father reueld in the hart of <i>France</i>,</div>
<div class="dverse">And tam’de the French, and made the Dolphin stoope:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eae145" id="lnum-eae145">145</a>
 And had he macht according to his state,</div>
<div class="dverse">He might haue kept that glorie till this daie.</div>
<div class="dverse">But when he tooke a begger to his bed,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eae148" id="lnum-eae148">♦</a>
 And gracst thy poore sire with his bridall daie,</div>
<div class="dverse">Then that sun-shine bred a showre for him</div>
<div class="dverse"><span class="lnum">150</span>
 Which washt his fathers fortunes out of France,</div>
<div class="dverse">And heapt seditions on his crowne at home.</div>
<div class="dverse">For what hath mou’d these tumults but thy pride?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eae153" id="lnum-eae153">♦</a>
 Hadst thou beene meeke, our title yet had slept?</div>
<div class="dverse">And we in pittie of the gentle king,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eae155" id="lnum-eae155">155</a>
 Had slipt our claime vntill an other age.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eae156" id="lnum-eae156">♦</a>
 <span class="sd-cn">George.</span>
  But when we saw our summer brought the gaine,</div>
<div class="dverse">And that the haruest brought vs no increase,</div>
<div class="dverse">We set the axe to thy vsurping root,</div>
<div class="dverse">And though the edge haue something hit our selues,</div>
<div class="dverse"><span class="lnum">160</span>
 Yet know thou we will neuer cease to strike,</div>
<div class="dverse">Till we haue hewne thee downe,</div>
<div class="dverse">Or bath’d thy growing with our heated blouds.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 And in this resolution, I defie thee,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eae164" id="lnum-eae164">♦</a>
 Not willing anie longer conference,</div>
<div class="dverse"><span class="lnum">165</span>
 Since thou deniest the gentle king to speake.</div>
<div class="dverse">Sound trumpets, let our bloudie colours waue,</div>
<div class="dverse">And either victorie or else a graue.</div>

<div class="dverse1"><span class="sd-cn">Quee.</span>
 Staie <i>Edward</i> staie.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eae169" id="lnum-eae169">♦</a>
 <span class="sd-cn">Edw.</span>
  Hence wrangling woman, Ile no longer staie,</div>
<div class="dverse"><span class="lnum">170</span>
 Thy words will cost ten thousand liues to daie.
 <span class="sd-verseend"><i>Exeunt Omnes.</i> Alarmes.</span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> VI
<span class="dnavigatenf">eaf</span></h3>

Enter <i>Warwike</i>.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Sore spent with toile as runners with the race,</div>
<div class="dverse"><i>I</i> laie me downe a little while to breath,</div>
<div class="dverse"><i>F</i>or strokes receiude, and manie blowes repaide,</div>
<div class="dverse">Hath robd my strong knit sinnews of their strength,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaf005" id="lnum-eaf005">5</a>
 And force perforce needes must <i>I</i> rest my selfe.</div>

<div class="sd-entry">Enter <i>Edward</i>.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Smile gentle heauens or strike vngentle death,</div>
<div class="dverse">That we maie die vnlesse we gaine the daie:</div>
<div class="dverse">What fatall starre malignant frownes from heauen</div>
<div class="dverse">Vpon the harmelesse line of <i>Yorkes</i> true house?</div>

<div class="sd-entry">Enter <i>George</i>.</div>

<div class="dverse1"><span class="lnum">10</span>
 <span class="sd-cn">George.</span>
  Come brother, come, lets to the field againe,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaf011" id="lnum-eaf011">♦</a>
 For yet theres hope inough to win the daie:</div>
<div class="dverse">Then let vs backe to cheere our fainting Troupes,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaf013" id="lnum-eaf013">♦</a>
 Lest they retire now we haue left the field.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaf014" id="lnum-eaf014">♦</a>
 <span class="sd-cn">War.</span>
  How now my lords: what hap, what hope of good?</div>

<div class="sd-entry">Enter <i>Richard</i> running.</div>

<div class="dverse1"><span class="lnum">15</span>
 <span class="sd-cn">Rich.</span>
 Ah <i>Warwike</i>, why haste thou withdrawne thy selfe?</div>
<div class="dverse">Thy noble father in the thickest thronges,</div>
<div class="dverse">Cride still for <i>Warwike</i> his thrise valiant son,</div>
<div class="dverse">Vntill with thousand swords he was beset,</div>
<div class="dverse">And manie wounds made in his aged brest,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaf020" id="lnum-eaf020">20</a>
 And as he tottring sate vpon his steede,</div>
<div class="dverse">He waft his hand to me and cride aloud:</div>
<div class="dverse"><i>Richard</i>, commend me to my valiant sonne,</div>
<div class="dverse">And still he cride <i>Warwike</i> revenge my death,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaf024" id="lnum-eaf024">♦</a>
 And with those words he tumbled off his horse,</div>
<div class="dverse"><span class="lnum">25</span>
 And so the noble Salsbury gave vp the ghost.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Then let the earth be drunken with his bloud,</div>
<div class="dverse"><i>I</i>le kill my horse because I will not flie:</div>
<div class="dverse">And here to God of heauen I make a vow,</div>
<div class="dverse">Neuer to passe from forth this bloudy field</div>
<div class="dverse"><span class="lnum">30</span>
 Till I am full reuenged for his death.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Lord <i>Warwike</i>, I doe bend my knees with thine,</div>
<div class="dverse">And in that vow now ioine my soule to thee,</div>
<div class="dverse">Thou setter vp and puller downe of kings,</div>
<div class="dverse">vouchsafe a gentle victorie to vs,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaf035" id="lnum-eaf035">35</a>
 Or let vs die before we loose the daie:</div>

<div class="dverse1"><span class="sd-cn">George.</span>
 Then let vs haste to cheere the souldiers harts,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaf037" id="lnum-eaf037">♦</a>
 And call them pillers that will stand to vs,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaf038" id="lnum-eaf038">♦</a>
 And hiely promise to remunerate</div>
<div class="dverse">Their trustie seruice, in these dangerous warres.</div>

<div class="dverse1"><span class="lnum">40</span>
 <span class="sd-cn">Rich.</span>
  Come, come awaie, and stand not to debate,</div>
<div class="dverse">For yet is hope of fortune good enough.</div>
<div class="dverse">Brothers, giue me your hands, and let vs part</div>
<div class="dverse">And take our leaues vntill we meet againe,</div>
<div class="dverse">Where ere it be in heauen or in earth.</div>
<div class="dverse"><span class="lnum">45</span>
 Now I that neuer wept, now melt in wo,</div>
<div class="dverse">To see these dire mishaps continue so.</div>
<div class="dverse"><i>Warwike</i> farewel.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Awaie awaie, once more sweet Lords farewell. <span class="sd-verseend"><i>Exeunt Omnes.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> VII.
<span class="dnavigatenf">eag</span></h3>

Alarmes, and then enter <i>Richard</i> at one dore and <i>Clifford</i>
at the other.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 A <i>Clifford</i> a <i>Clifford</i>.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 A <i>Richard</i> a <i>Richard</i>.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Now <i>Clifford</i>, for <i>Yorke</i> &amp; young <i>Rutlands</i> death,</div>
<div class="dverse">This thirsty sword that longs to drinke thy bloud,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eag005" id="lnum-eag005">5</a>
 Shall lop thy limmes, and slise thy cursed hart,</div>
<div class="dverse">For to reuenge the murders thou hast made.</div>

<div class="dverse1"><span class="sd-cn">Clif.</span>
 Now <i>Richard</i>, I am with thee here alone,</div>
<div class="dverse">This is the hand that stabd thy father <i>Yorke</i>,</div>
<div class="dverse">And this the hand that slew thy brother <i>Rutland</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eag010" id="lnum-eag010">10</a>
 And heres the heart that triumphs in their deathes,</div>
<div class="dverse">And cheeres these hands that slew thy sire and brother,</div>
<div class="dverse">To execute the like vpon thy selfe,</div>
<div class="dverse">And so haue at thee.</div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> VIII.
<span class="dnavigatenf">eah</span></h3>

Alarmes. They fight, and then enters <i>Warwike</i>
and rescues <i>Richard</i>, &amp; then <i>exeunt omnes</i>. <br>Alarme still, and then enter <i>Henry solus</i>.</div>

<div class="dverse1"><span class="sd-cn">Hen.</span>
 Oh gratious God of heauen looke downe on vs,</div>
<div class="dverse">And set some endes to these incessant griefes,</div>
<div class="dverse">How like a mastlesse ship vpon the seas,</div>
<div class="dverse">This woful battaile doth continue still,</div>
<div class="dverse"><span class="lnum">5</span>
 Now leaning this way, now to that side driue,</div>
<div class="dverse">And none doth know to whom the daie will fall.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eah007" id="lnum-eah007">♦</a>
 O would my death might staie these ciuill iars!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eah008" id="lnum-eah008">♦</a>
 Would I had neuer raind, nor nere bin king,</div>
<div class="dverse"><i>Margret</i> and <i>Clifford</i>, chide me from the fielde,</div>
<div class="dverse"><span class="lnum">10</span>
 Swearing they had best successe when <i>I</i> was thence.</div>
<div class="dverse">Would God that <i>I</i> were dead so all were well,</div>
<div class="dverse">Or would my crowne suffice, I were content</div>
<div class="dverse">To yeeld it them and liue a priuate life.</div>

<div class="sd-entry">Enter a souldier with a dead man in his armes.</div>

<div class="dverse1"><span class="sd-cn">Sould</span>
 Il blowes the wind that profits no bodie,</div>
<div class="dverse"><span class="lnum">15</span>
 <i>T</i>his man that I have slaine in fight to daie,</div>
<div class="dverse">Maie be possessed of some store of crownes,</div>
<div class="dverse">And I will search to find them if I can,</div>
<div class="dverse">But stay. Me thinkes it is my fathers face,</div>
<div class="dverse">Oh I tis he whom I haue slaine in fight,</div>
<div class="dverse"><span class="lnum">20</span>
 From London was I prest out by the king,</div>
<div class="dverse">My father he came on the part of <i>Yorke</i>,</div>
<div class="dverse">And in this conflict I haue slaine my father:</div>
<div class="dverse">Oh pardon God, I knew not what I did,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eah024" id="lnum-eah024">♦</a>
 And pardon father, for I knew thee not.</div>

<div class="sd-entry">Enter an other souldier with a dead man.</div>

<div class="dverse1"><span class="lnum">25</span>
 <span class="sd-cn">2. Soul.</span>
  Lie there thou that foughtst with me so stoutly,</div>
<div class="dverse">Now let me see what store of gold thou haste,</div>
<div class="dverse">But staie, me thinkes this is no famous face:</div>
<div class="dverse">Oh no it is my sonne that <i>I</i> haue slaine in fight,</div>
<div class="dverse">O monstrous times begetting such euents,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eah030" id="lnum-eah030">30</a>
 How cruel bloudy, and ironious,</div>
<div class="dverse">This deadlie quarrell dailie doth beget,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eah032" id="lnum-eah032">♦</a>
 Poore boy thy father gaue thee lif too late,</div>
<div class="dverse">And hath bereau’de thee of thy life too sone.</div>

<div class="dverse1"><span class="sd-cn">King</span>
 Wo aboue wo, griefe more then common griefe,</div>
<div class="dverse"><span class="lnum">35</span>
 Whilst Lyons warre and battaile for their dens,</div>
<div class="dverse">Poore lambs do feele the rigor of their wraths:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eah037" id="lnum-eah037">♦</a>
 The red rose and the white are on his face,</div>
<div class="dverse">The fatall colours of our striuing houses,</div>
<div class="dverse">Wither one rose, and let the other flourish,</div>
<div class="dverse"><span class="lnum">40</span>
 For if you striue, ten thousand liues must perish.</div>

<div class="dverse1"><span class="sd-cn">1. Sould.</span>
 How will my mother for my fathers death,</div>
<div class="dverse">Take on with me and nere be satisfide?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eah043" id="lnum-eah043">♦</a>
 <span class="sd-cn">2. Sol.</span>
  How will my wife for slaughter of my son,</div>
<div class="dverse">Take on with me and nere be satisfide?</div>

<div class="dverse1"><span class="lnum">45</span>
 <span class="sd-cn">King.</span>
  How will the people now misdeeme their king,</div>
<div class="dverse">Oh would my death their mindes could satisfie.</div>

<div class="dverse1"><span class="sd-cn">1. Sould.</span>
 Was euer son so rude his fathers bloud to spil?</div>

<div class="dverse1"><span class="sd-cn">2. Soul.</span>
 Was euer father so vnnaturall his son to kill?</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 Was euer king thus greeud and vexed still?</div>

<div class="dverse1"><span class="lnum">50</span>
 <span class="sd-cn">1. Sould.</span>
  Ile beare thee hence from this accursed place,</div>
<div class="dverse">For wo is me to see my fathers face. <span class="sd-verseend"><i>Exit</i> with his father.</span></div>

<div class="dverse1"><span class="sd-cn">2. Soul.</span>
 Ile beare thee hence &amp; let them fight that wil,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eah053" id="lnum-eah053">♦</a>
 For <i>I</i> haue murdered where I should not kill.
  <span class="sd-verseend"><i>Exit</i> with his sonne.</span></div>

<div class="dverse1"><span class="sd-cn">K Hen.</span>
 Weepe wretched man, Ile lay thee teare for tear,</div>
<div class="dverse"><span class="lnum">55</span>
 Here sits a king as woe begone as thee.</div>

<div class="sd-entry">Alarmes and enter the <i>Queene</i>.</div>

<div class="dverse1"><span class="sd-cn">Queene.</span>
 Awaie my Lord to <i>Barwicke</i> presentlie,</div>
<div class="dverse">The daie is lost, our friends are murdered,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eah058" id="lnum-eah058">♦</a>
 No hope is left for vs, therefore awaie.</div>

<div class="sd-entry">Enter prince <i>Edward</i>.</div>

<div class="dverse1"><span class="sd-cn">Prince.</span>
 Oh father flie, our men haue left the field,</div>
<div class="dverse"><span class="lnum">60</span>
 Take horse sweet father, let us saue our selues.</div>

<div class="sd-entry">Enter <i>Exeter</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eah061" id="lnum-eah061">♦</a>
 <span class="sd-cn">Exet.</span>
  Awaie my Lord for vengeance comes along with him:</div>
<div class="dverse">Nay stand not to expostulate make hast,</div>
<div class="dverse">Or else come after, Ile awaie before.</div>

<div class="dverse1"><span class="sd-cn">K Hen.</span>
 Naie staie good <i>Exeter</i>, for Ile along with thee.</div>

<div class="sd-entry">Enter <i>Clifford</i> wounded with an arrow in his necke.</div>

<div class="dverse1"><span class="lnum">65</span>
 <span class="sd-cn">Clif.</span>
  Heere burnes my candell out,</div>
<div class="dverse">That whilst it lasted gaue king <i>Henry</i> light.</div>
<div class="dverse">Ah <i>Lancaster</i>, I feare thine ouerthrow,</div>
<div class="dverse">More then my bodies parting from my soule.</div>
<div class="dverse">My loue and feare glude manie friendes to thee,</div>
<div class="dverse"><span class="lnum">70</span>
 And now <i>I</i> die, that tough commixture melts.</div>
<div class="dverse">Impairing <i>Henry</i> strengthened misproud <i>Yorke</i>,</div>
<div class="dverse">The common people swarme like summer flies,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eah073" id="lnum-eah073">♦</a>
 And whither flies the Gnats but to the sun?</div>
<div class="dverse">And who shines now but <i>Henries</i> enemie?</div>
<div class="dverse"><span class="lnum">75</span>
 Oh <i>Phœbus</i> hadst thou neuer giuen consent,</div>
<div class="dverse">That <i>Phæton</i> should checke thy fierie steedes,</div>
<div class="dverse">Thy burning carre had neuer scorcht the earth.</div>
<div class="dverse">And <i>Henry</i> hadst thou liu’d as kings should doe,</div>
<div class="dverse">And as thy father and his father did,</div>
<div class="dverse"><span class="lnum">80</span>
 Giuing no foot vnto the house of <i>Yorke</i>,</div>
<div class="dverse">I and ten thousand in this wofull land,</div>
<div class="dverse">Had left no mourning Widdowes for our deathes,</div>
<div class="dverse">And thou this daie hadst kept thy throne in peace.</div>
<div class="dverse">For what doth cherish weedes but gentle aire?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eah085" id="lnum-eah085">85</a>
 And what makes robbers bold but lenitie?</div>
<div class="dverse">Bootlesse are plaintes, and curelesse are my woundes,</div>
<div class="dverse">No waie to flie, no strength to hold our flight,</div>
<div class="dverse">The foe is mercilesse and will not pittie me,</div>
<div class="dverse">And at their hands <i>I</i> haue deserude no pittie.</div>
<div class="dverse"><span class="lnum">90</span>
 The aire is got into my bleeding wounds,</div>
<div class="dverse">And much effuse of bloud doth make me faint,</div>
<div class="dverse">Come <i>Yorke</i>, and <i>Richard</i>, <i>Warwike</i> and the rest,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eah093" id="lnum-eah093">♦</a>
 <i>I</i> stabde your fathers, now come split my brest.</div>

<div class="sd-entry">Enter <i>Edward</i>, <i>Richard</i>, and <i>Warwike</i>, and Souldiers.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eah094" id="lnum-eah094">♦</a>
 <span class="sd-cn">Edw.</span>
  Thus farre our fortunes keepes an vpward</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eah095" id="lnum-eah095">95</a>
 Course, and we are grast with wreathes of victorie.</div>
<div class="dverse">Some troopes pursue the bloudie minded Queene,</div>
<div class="dverse"><i>T</i>hat now towards <i>Barwike</i> doth poste amaine,</div>
<div class="dverse">But thinke you that <i>Clifford</i> is fled awaie with them?</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 No, tis impossible he should escape,</div>
<div class="dverse"><span class="lnum">100</span>
 <i>F</i>or though before his face I speake the words,</div>
<div class="dverse">Your brother Richard markt him for the graue.</div>
<div class="dverse">And where so ere he be I warrant him dead. <span class="sd-verseend"><i>Clifford</i> grones and then dies.</span></div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Harke, what soule is this that takes his heauy leaue?</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 A deadlie grone, like life and deaths departure.</div>

<div class="dverse1"><span class="lnum">105</span>
 <span class="sd-cn">Edw.</span>
  See who it is, and now the battailes ended,</div>
<div class="dverse">Friend or foe, let him be friendlie vsed.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Reuerse that doome of mercie, for tis <i>Clifford</i>,</div>
<div class="dverse">Who kild our tender brother <i>Rutland</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eah109" id="lnum-eah109">♦</a>
 And stabd our princelie father Duke of <i>Yorke</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eah110" id="lnum-eah110">110</a>
 <span class="sd-cn">War.</span>
 From off the gates of <i>Yorke</i> fetch down the</div>
<div class="dverse">Head, Your fathers head which <i>Clifford</i> placed there.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eah112" id="lnum-eah112">♦</a>
 Insteed of that, let his supplie the roome.</div>
<div class="dverse">Measure for measure must be answered.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Bring forth that fatall scrichowle to our house,</div>
<div class="dverse"><span class="lnum">115</span>
 That nothing sung to vs but bloud and death,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eah116" id="lnum-eah116">♦</a>
 Now his euill boding tongue no more shall speake.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 I thinke his vnderstanding is bereft.</div>
<div class="dverse">Say <i>Clifford</i>, doost thou know who speakes to thee?</div>
<div class="dverse">Darke cloudie death oreshades his beames of life,</div>
<div class="dverse"><span class="lnum">120</span>
 And he nor sees nor heares vs what we saie.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Oh would he did, and so perhaps he doth,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eah122" id="lnum-eah122">♦</a>
 And tis his policie that in the time of death,</div>
<div class="dverse">He might auoid such bitter stormes as he</div>
<div class="dverse">In his houre of death did give vnto our father.</div>

<div class="dverse1"><span class="lnum">125</span>
 <span class="sd-cn">George.</span>
 <i>Richard</i> if thou thinkest so, vex him with eager words.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 <i>Clifford</i>, aske mercie and obtaine no grace.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 <i>Clifford</i>, repent in bootlesse penitence.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 <i>Clifford</i> deuise excuses for thy fault.</div>

<div class="dverse1"><span class="sd-cn">George.</span>
 Whilst we deuise fell tortures for thy fault.</div>

<div class="dverse1"><span class="lnum">130</span>
 <span class="sd-cn">Rich.</span>
 Thou pittiedst <i>Yorke</i>, and I am sonne to <i>Yorke</i>.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Thou pittiedst <i>Rutland</i>, and I will pittie thee.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eah132" id="lnum-eah132">♦</a>
 <span class="sd-cn">George.</span>
 Wheres captaine <i>Margaret</i> to fence you now?</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 They mocke thee <i>Clifford</i>, sweare as thou wast wont.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eah134" id="lnum-eah134">♦</a>
 <span class="sd-cn">Rich.</span>
 What not an oth? Nay, then <i>I</i> know hees dead.</div>
<div class="dverse"><span class="lnum">135</span>
 Tis hard, when <i>Clifford</i> cannot foord his friend an oath.</div>
<div class="dverse">By this I know hees dead, and by my soule,</div>
<div class="dverse">Would this right hand buy but an howres life,</div>
<div class="dverse">That I in all contempt might raile at him.</div>
<div class="dverse">Ide cut it off and with the issuing bloud,</div>
<div class="dverse"><span class="lnum">140</span>
 Stifle the villaine whose instanched thirst,</div>
<div class="dverse"><i>Yorke</i> and young <i>Rutland</i> could not satisfie.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 <i>I</i>, but he is dead, off with the traitors head,</div>
<div class="dverse">And reare it in the place your fathers stands.</div>
<div class="dverse">And now to London with triumphant march,</div>
<div class="dverse"><span class="lnum">145</span>
 There to be crowned <i>Englands</i> lawfull king.</div>
<div class="dverse">From thence shall <i>Warwike</i> crosse the seas to <i>France</i>,</div>
<div class="dverse">And aske the ladie <i>Bona</i> for thy <i>Queene</i>,</div>
<div class="dverse">So shalt thou sinew both these landes togither,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eah149" id="lnum-eah149">♦</a>
 And hauing <i>France</i> thy friend thou needst not dread,</div>
<div class="dverse"><span class="lnum">150</span>
 The scattered foe that hopes to rise againe.</div>
<div class="dverse">And though they cannot greatly sting to hurt,</div>
<div class="dverse">Yet looke to haue them busie to offend thine eares.</div>
<div class="dverse">First He see the coronation done,</div>
<div class="dverse">And afterward He crosse the seas to <i>France</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eah155" id="lnum-eah155">155</a>
 To effect this marriage if it please my Lord</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Euen as thou wilt good <i>Warwike</i> let it be.</div>
<div class="dverse">But first before we goe, <i>George</i> kneele downe.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eah158" id="lnum-eah158">♦</a>
 We here create thee Duke of <i>Clarence</i>, and girt thee with the sword.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eah159" id="lnum-eah159">♦</a>
 Our younger brother <i>Richard</i> Duke of <i>Glocester</i>.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eah160" id="lnum-eah160">160</a>
 <i>Warwike</i> as my selfe shal do &amp; vndo as him pleaseth best.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Let me be Duke of <i>Clarence</i>, <i>George</i> of <i>Gloster</i>,</div>
<div class="dverse">For <i>Glosters</i> Dukedome is too ominous.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eah163" id="lnum-eah163">♦</a>
 <span class="sd-cn">War.</span>
  Tush thats a childish obseruation.</div>
<div class="dverse"><i>Richard</i> be Duke of <i>Gloster</i>.  Now to London.</div>
<div class="dverse"><span class="lnum">165</span>
 To see these honors in possession. <span class="sd-verseend"><i>Exeunt Omnes.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> IX.
<span class="dnavigatenf">eai</span></h3>

Enter two keepers with bow and arrowes.</div>

<div class="dverse1"><span class="sd-cn">Keeper.</span>
 Come, lets take our stands vpon this hill,</div>
<div class="dverse">And by and by the deere will come this waie.</div>
<div class="dverse">But staie, heere comes a man, lets listen him a while.</div>

<div class="sd-entry">Enter king <i>Henrie</i> disguisde.</div>

<div class="dverse1"><span class="sd-cn">Hen.</span>
 From <i>Scotland</i> am I stolne euen of pure loue,</div>
<div class="dverse"><span class="lnum">5</span>
 And thus disguisde to greet my natiue land.</div>
<div class="dverse">No, <i>Henrie</i> no, <i>I</i>t is no land of thine,</div>
<div class="dverse">No bending knee will call thee <i>Cæsar</i> now,</div>
<div class="dverse">No humble suters sues to thee for right,</div>
<div class="dverse">For how canst thou helpe them and not thy selfe?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eai010" id="lnum-eai010">10</a>
 <span class="sd-cn">Keeper.</span>
  I marrie sir, here is a deere, his skin is a</div>
<div class="dverse">Keepers fee. Sirra stand close, for as I thinke,</div>
<div class="dverse">This is the king, king <i>Edward</i> hath deposde.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eai013" id="lnum-eai013">♦</a>
 <span class="sd-cn">Hen.</span>
 My <i>Queene</i> and sonne poore soules are gone to</div>
<div class="dverse"><i>France</i>, and as I heare the great commanding <i>Warwike</i>,</div>
<div class="dverse"><span class="lnum">15</span>
 To intreat a marriage with the ladie <i>Bona</i>,</div>
<div class="dverse">If this be true, poore <i>Queene</i> and sonne,</div>
<div class="dverse">Your labour is but spent in vaine,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eai018" id="lnum-eai018">♦</a>
 For <i>Lewis</i> is a prince soone wun with words,</div>
<div class="dverse">And <i>Warwike</i> is a subtill Orator.</div>
<div class="dverse">He laughes and saies, his Edward is instalde,</div>
<div class="dverse">She weepes, and saies her <i>Henry</i> is deposde,</div>
<div class="dverse">He on his right hand asking a wife for <i>Edward</i>,</div>
<div class="dverse">She on his left side crauing aid for <i>Henry</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eai024" id="lnum-eai024">♦</a>
 <span class="sd-cn">Keeper.</span>
  What art thou that talkes of kings and queens?</div>

<div class="dverse1"><span class="lnum">25</span>
 <span class="sd-cn">Hen.</span>
  More then I seeme, for lesse I should not be.</div>
<div class="dverse">A man at least, and more I cannot be,</div>
<div class="dverse">And men maie talke of kings, and why not I?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eai028" id="lnum-eai028">♦</a>
 <span class="sd-cn">Keeper.</span>
  I but thou talkest as if thou wert a king thy selfe.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eai029" id="lnum-eai029">♦</a>
 <span class="sd-cn">Hen.</span>
  Why so I am in mind though not in shew.</div>

<div class="dverse1"><span class="lnum">30</span>
 <span class="sd-cn">Keeper.</span>
  And if thou be a king where is thy crowne?</div>

<div class="dverse1"><span class="sd-cn">Hen.</span>
 My crowne is in my hart, not on my head.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eai032" id="lnum-eai032">♦</a>
 My crowne is calde content, a crown that</div>
<div class="dverse">Kings doe seldome times enioy.</div>

<div class="dverse1"><span class="sd-cn">Keeper.</span>
 And if thou be a king crownd with content,</div>
<div class="dverse"><span class="lnum">35</span>
 Your crowne content and you, must be content</div>
<div class="dverse">To go with vs vnto the officer, for as we thinke</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eai037" id="lnum-eai037">♦</a>
 You are our quondam king, <i>K. Edward</i> hath deposde,</div>
<div class="dverse">And therefore we charge you in Gods name &amp; the kings</div>
<div class="dverse">To go along with vs vnto the officers.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eai040" id="lnum-eai040">40</a>
 <span class="sd-cn">Hen.</span>
  Gods name be fulfild, your kings name be</div>
<div class="dverse">Obaide, and be you kings, command and Ile obay. <span class="sd-verseend"><i>Exeunt Omnes.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> X.
<span class="dnavigatenf">eaj</span></h3>

Enter king <i>Edward</i>, <i>Clarence</i>, and <i>Gloster</i>, <i>Montague</i>, <i>Hastings</i>, and the Lady <i>Gray</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaj001" id="lnum-eaj001">♦</a>
 <span class="sd-cn">K Edw.</span>
 Brothers of <i>Clarence</i>, and of <i>Glocester</i>,</div>
<div class="dverse">This ladies husband heere sir <i>Richard Gray</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaj003" id="lnum-eaj003">♦</a>
 At the battaile of saint Albones did lose his life,</div>
<div class="dverse">His lands then were seazed on by the conqueror.</div>
<div class="dverse"><span class="lnum">5</span>
 Her sute is now to repossesse those lands,</div>
<div class="dverse">And sith in quarrell of the house of <i>Yorke</i>,</div>
<div class="dverse">The noble gentleman did lose his life,</div>
<div class="dverse">In honor we cannot denie her sute.</div>

<div class="dverse1"><span class="sd-cn">Glo.</span>
 Your highnesse shall doe well to grant it then.</div>

<div class="dverse1"><span class="lnum">10</span>
 <span class="sd-cn">K Edw</span>
 I, so <i>I</i> will, but yet Ile make a pause.</div>

<div class="dverse1"><span class="sd-cn">Glo.</span>
 I, is the winde in that doore?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaj012" id="lnum-eaj012">♦</a>
 <span class="sd-cn">Clarence,</span>
  I see the Lady hath some thing to grant,</div>
<div class="dverse">Before the king will grant her humble sute.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaj014" id="lnum-eaj014">♦</a>
 <span class="sd-cn">Cla.</span>
  He knowes the game, how well he keepes the wind.</div>

<div class="dverse1"><span class="lnum">15</span>
 <span class="sd-cn">K. Ed.</span>
  Widow come some other time to know our mind.</div>

<div class="dverse1"><span class="sd-cn">La.</span>
 May it please your grace <i>I</i> cannot brooke delaies,</div>
<div class="dverse">I beseech your highnesse to dispatch me now.</div>

<div class="dverse1"><span class="sd-cn">K Ed.</span>
 Lords giue vs leaue, wee meane to trie this widowes wit.</div>

<div class="dverse1"><span class="sd-cn">Cla.</span>
 I, good leaue haue you.</div>

<div class="dverse1"><span class="lnum">20</span>
 <span class="sd-cn">Glo.</span>
  For you will haue leaue till youth take leaue,</div>
<div class="dverse">And leaue you to your crouch.</div>

<div class="dverse1"><span class="sd-cn">K Ed.</span>
 Come hither widdow, howe many children haste thou?</div>

<div class="dverse1"><span class="sd-cn">Cla.</span>
 I thinke he meanes to begge a child on her.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaj024" id="lnum-eaj024">♦</a>
 <span class="sd-cn">Glo.</span>
  Nay whip me then, heele rather giue hir two.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaj025" id="lnum-eaj025">25</a>
 <span class="sd-cn">La.</span>
  Three my most gratious Lord.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaj026" id="lnum-eaj026">♦</a>
 <span class="sd-cn">Glo.</span>
  You shall haue foure and you wil be rulde by him.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaj027" id="lnum-eaj027">♦</a>
 <span class="sd-cn">K Ed.</span>
  Were it not pittie they shoulde loose their fathers lands?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaj028" id="lnum-eaj028">♦</a>
 <span class="sd-cn">La.</span>
  Be pittifull then dread L. and grant it them.</div>

<div class="dverse1"><span class="sd-cn">K Edw.</span>
 Ile tell thee how these lands are to be got.</div>

<div class="dverse1"><span class="lnum">30</span>
 <span class="sd-cn">La.</span>
  So shall you bind me to your highnesse seruice.</div>

<div class="dverse1"><span class="sd-cn">K Ed.</span>
 What seruice wilt thou doe me if I grant it them?</div>

<div class="dverse1"><span class="sd-cn">La.</span>
 Euen what your highnesse shall command.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaj033" id="lnum-eaj033">♦</a>
 <span class="sd-cn">Glo.</span>
  Naie then widow Ile warrant you all your</div>
<div class="dverse">Husbands lands, if you grant to do what he</div>
<div class="dverse"><span class="lnum">35</span>
 Commands. Fight close or in good faith</div>
<div class="dverse">You catch a clap.</div>

<div class="dverse1"><span class="sd-cn">Cla.</span>
 Naie I feare her not vnlesse she fall.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaj038" id="lnum-eaj038">♦</a>
 <span class="sd-cn">Glo.</span>
  Marie godsforbot man, for heele take vantage then.</div>

<div class="dverse1"><span class="sd-cn">La.</span>
 Why stops my Lord, shall I not know my taske?</div>

<div class="dverse1"><span class="lnum">40</span>
 <span class="sd-cn">K Ed.</span>
  An easie taske, tis but to loue a king.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaj041" id="lnum-eaj041">♦</a>
 <span class="sd-cn">La.</span>
  Thats soone performde, because I am a subiect.</div>

<div class="dverse1"><span class="sd-cn">K Ed.</span>
 Why then thy husbandes landes <i>I</i> freelie giue thee.</div>

<div class="dverse1"><span class="sd-cn">La.</span>
 I take my leaue with manie thousand thankes.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaj044" id="lnum-eaj044">♦</a>
 <span class="sd-cn">Cla.</span>
  The match is made, shee seales it with a cursie.</div>

<div class="dverse1"><span class="sd-cn">K Ed.</span>
 Staie widdow staie, what loue dost thou thinke</div>
<div class="dverse">I sue so much to get?</div>

<div class="dverse1"><span class="sd-cn">La.</span>
 My humble seruice, such as subiects owes and the lawes commands.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaj048" id="lnum-eaj048">♦</a>
 <span class="sd-cn">K Ed.</span>
  No by my troth, I meant no such loue,</div>
<div class="dverse">But to tell thee the troth, I aime to lie with thee.</div>

<div class="dverse1"><span class="lnum">50</span>
 <span class="sd-cn">La.</span>
  To tell you plaine my Lord, I had rather lie in prison,</div>

<div class="dverse1"><span class="sd-cn">K Edw.</span>
 Why then thou canst not get thy husbandes lands.</div>

<div class="dverse1"><span class="sd-cn">La.</span>
 Then mine honestie shall be my dower,</div>
<div class="dverse">For by that losse I will not purchase them.</div>

<div class="dverse1"><span class="sd-cn">K Ed.</span>
 Herein thou wrongst thy children mightilie.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaj055" id="lnum-eaj055">55</a>
 <span class="sd-cn">La.</span>
  Heerein your highnesse wrongs both them and</div>
<div class="dverse">Me, but mightie Lord this merrie inclination</div>
<div class="dverse">Agrees not with the sadnesse of my sute.</div>
<div class="dverse">Please it your highnes to dismisse me either with <i>I</i> or no.</div>

<div class="dverse1"><span class="sd-cn">K Ed.</span>
 <i>I</i>, if thou saie <i>I</i> to my request,</div>
<div class="dverse"><span class="lnum">60</span>
 No, if thou saie no to my demand.</div>

<div class="dverse1"><span class="sd-cn">La.</span>
 Then no my Lord, my sute is at an end.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaj062" id="lnum-eaj062">♦</a>
 <span class="sd-cn">Glo.</span>
  The widdow likes him not, shee bends the brow.</div>

<div class="dverse1"><span class="sd-cn">Cla.</span>
 Why he is the bluntest woer in christendome.</div>

<div class="dverse1"><span class="sd-cn">K Ed.</span>
 Her lookes are all repleat with maiestie,</div>
<div class="dverse"><span class="lnum">65</span>
 One waie or other she is for a king,</div>
<div class="dverse">And she shall be my loue or else my <i>Queene</i>.</div>
<div class="dverse">Saie that king <i>Edward</i> tooke thee for his <i>Queene</i>.</div>

<div class="dverse1"><span class="sd-cn">La.</span>
 Tis better said then done, my gratious Lord,</div>
<div class="dverse"><i>I</i> am a subiect fit to iest withall,</div>
<div class="dverse"><span class="lnum">70</span>
 But far vnfit to be a Soueraigne.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaj071" id="lnum-eaj071">♦</a>
 <span class="sd-cn">K Edw.</span>
 Sweet widdow, by my state I sweare, <i>I</i> speake</div>
<div class="dverse">No more then what my hart intends,</div>
<div class="dverse">And that is to enioie thee for my loue.</div>

<div class="dverse1"><span class="sd-cn">La.</span>
 And that is more then I will yeeld vnto,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaj075" id="lnum-eaj075">75</a>
 <i>I</i> know <i>I</i> am too bad to be your <i>Queene</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaj076" id="lnum-eaj076">♦</a>
 And yet too good to be your Concubine.</div>

<div class="dverse1"><span class="sd-cn">K Edw.</span>
 You cauill widdow, I did meane my <i>Queene</i>.</div>

<div class="dverse1"><span class="sd-cn">La.</span>
 Your grace would be loath my sonnes should call you father.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaj079" id="lnum-eaj079">♦</a>
 <span class="sd-cn">K Edw.</span>
  No more then when my daughters call thee</div>
<div class="dverse"><span class="lnum">80</span>
 Mother. Thou art a widow and thou hast some children,</div>
<div class="dverse">And by Gods mother <i>I</i> being but a bacheler</div>
<div class="dverse">Haue other some. Why tis a happy thing</div>
<div class="dverse">To be the father of manie children.</div>
<div class="dverse">Argue no more, for thou shall be my Queene.</div>

<div class="dverse1"><span class="lnum">85</span>
 <span class="sd-cn">Glo.</span>
  The ghostlie father now hath done his shrift.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaj086" id="lnum-eaj086">♦</a>
 <span class="sd-cn">Cla.</span>
  When he was made a shriuer twas for shift.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaj087" id="lnum-eaj087">♦</a>
 <span class="sd-cn">K. Edw.</span>
  Brothers, you muse what talke the widdow</div>
<div class="dverse">And <i>I</i> haue had, you would thinke it strange</div>
<div class="dverse">If <i>I</i> should marrie her.</div>

<div class="dverse1"><span class="lnum">90</span>
 <span class="sd-cn">Cla.</span>
  Marrie her my Lord, to whom?</div>

<div class="dverse1"><span class="sd-cn">K Edw.</span>
 Why <i>Clarence</i> to my selfe.</div>

<div class="dverse1"><span class="sd-cn">Glo.</span>
 That would be ten daies wonder at the least.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaj093" id="lnum-eaj093">♦</a>
 <span class="sd-cn">Cla.</span>
  Why thats a daie longer then a wonder lastes.</div>

<div class="dverse1"><span class="sd-cn">Glo.</span>
 And so much more are the wonders in extreames</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaj095" id="lnum-eaj095">95</a>
 <span class="sd-cn">K Edw.</span>
 Well ieast on brothers, <i>I</i> can tell you, hir</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaj096" id="lnum-eaj096">♦</a>
 Sute is granted for her husbands lands.</div>

<div class="sd-entry">Enter a Messenger.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaj097" id="lnum-eaj097">♦</a>
 <span class="sd-cn">Mes.</span>
 And it please your grace, <i>Henry</i> your foe is</div>
<div class="dverse">Taken, and brought as prisoner to your pallace gates.</div>

<div class="dverse1"><span class="sd-cn">K Edw.</span>
 Awaie with him, and send him to the Tower,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaj100" id="lnum-eaj100">100</a>
 And let vs go question with the man about</div>
<div class="dverse">His apprehension. Lords along, and vse this</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaj102" id="lnum-eaj102">♦</a>
 Ladie honorablie. <span class="sd-verseend"><i>Exeunt Omnes.</i></span></div>

<div class="sd-entry"><i>Manet Gloster</i> and speakes.</div>

<div class="dverse1"><span class="sd-cn">Glost.</span>
 I, <i>Edward</i> will vse women honourablie,</div>
<div class="dverse">Would he were wasted marrow, bones and all,</div>
<div class="dverse"><span class="lnum">105</span>
 That from his loines no issue might succeed</div>
<div class="dverse">To hinder me from the golden time <i>I</i> looke for,</div>
<div class="dverse">For <i>I</i> am not yet lookt on in the world.</div>
<div class="dverse">First is there <i>Edward</i>, <i>Clarence</i>, and <i>Henry</i></div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaj109" id="lnum-eaj109">♦</a>
 And his sonne, and all they lookt for issue</div>
<div class="dverse"><span class="lnum">110</span>
 Of their loines ere <i>I</i> can plant my selfe,</div>
<div class="dverse">A cold premeditation for my purpose,</div>
<div class="dverse">What other pleasure is there in the world beside?</div>
<div class="dverse"><i>I</i> will go clad my bodie in gaie ornaments,</div>
<div class="dverse">And lull my selfe within a ladies lap,</div>
<div class="dverse"><span class="lnum">115</span>
 And witch sweet Ladies with my words and lookes.</div>
<div class="dverse">Oh monstrous man, to harbour such a thought!</div>
<div class="dverse">Why loue did scorne me in my mothers wombe.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaj118" id="lnum-eaj118">♦</a>
 And for <i>I</i> should not deale in hir affaires,</div>
<div class="dverse">Shee did corrupt fraile nature in the flesh,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaj120" id="lnum-eaj120">120</a>
 And plaste an enuious mountaine on my backe,</div>
<div class="dverse">Where sits deformity to mocke my bodie,</div>
<div class="dverse">To drie mine arme vp like a withered shrimpe.</div>
<div class="dverse">To make my legges of an vnequall size,</div>
<div class="dverse">And am <i>I</i> then a man to be belou’d?</div>
<div class="dverse"><span class="lnum">125</span>
 Easier for me to compasse twentie crownes.</div>
<div class="dverse">Tut <i>I</i> can smile, and murder when <i>I</i> smile,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaj127" id="lnum-eaj127">♦</a>
 <i>I</i> crie content, to that that greeues me most.</div>
<div class="dverse"><i>I</i> can adde colours to the Camelion,</div>
<div class="dverse">And for a need change shapes with <i>Protheus</i>,</div>
<div class="dverse"><span class="lnum">130</span>
 And set the aspiring <i>Catalin</i> to schoole.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaj131" id="lnum-eaj131">♦</a>
 Can <i>I</i> doe this, and cannot get the crowne?</div>
<div class="dverse">Tush were it ten times higher, <i>I</i>le pull it downe. <span class="sd-verseend"><i>Exit.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> XI.
<span class="dnavigatenf">eak</span></h3>

Enter king <i>Lewis</i> and the ladie <i>Bona</i>, and <i>Queene Margaret</i>, <i>Prince Edward</i>, and <i>Oxford</i> and others.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eak001" id="lnum-eak001">♦</a>
 <span class="sd-cn">Lewis.</span>
 Welcome <i>Queene</i> Margaret to the Court of <i>France</i>,</div>
<div class="dverse"><i>I</i>t fits not <i>Lewis</i> to sit while thou dost stand,</div>
<div class="dverse">Sit by my side, and here <i>I</i> vow to thee,</div>
<div class="dverse">Thou shalt haue aide to repossesse thy right,</div>
<div class="dverse"><span class="lnum">5</span>
 And beat proud Edward from his vsurped seat.</div>
<div class="dverse">And place king <i>Henry</i> in his former rule.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 <i>I</i> humblie thanke your royall maiestie.</div>
<div class="dverse">And pray the God of heauen to blesse thy state,</div>
<div class="dverse">Great king of <i>France</i>, that thus regards our wrongs.</div>

<div class="sd-entry">Enter <i>Warwike</i>.</div>

<div class="dverse1"><span class="lnum">10</span>
 <span class="sd-cn">Lew.</span>
  How now, who is this?</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 Our Earle of <i>Warwike</i> Edwardes chiefest friend.</div>

<div class="dverse1"><span class="sd-cn">Lew.</span>
 Welcome braue <i>Warwike</i>, what brings thee to France?</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 From worthy Edward king of <i>England</i>,</div>
<div class="dverse">My Lord and Soueraigne and thy vowed friend,</div>
<div class="dverse"><span class="lnum">15</span>
 <i>I</i> come in kindnes and vnfained loue,</div>
<div class="dverse">First to do greetings to thy royall person,</div>
<div class="dverse">And then to craue a league of amitie,</div>
<div class="dverse">And lastlie to confirme that amitie</div>
<div class="dverse">With nuptiall knot if thou vouchsafe to grant</div>
<div class="dverse"><span class="lnum">20</span>
 That vertuous ladie <i>Bona</i> thy faire sister,</div>
<div class="dverse">To Englands king in lawfull marriage.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 And if this go forward all our hope is done.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 And gratious Madam, in our kings behalfe,</div>
<div class="dverse">I am commanded with your loue and fauour,</div>
<div class="dverse"><span class="lnum">25</span>
 Humblie to kisse your hand and with my tongue,</div>
<div class="dverse">To tell the passions of my soueraines hart,</div>
<div class="dverse">Where fame late entring at his heedfull eares,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eak028" id="lnum-eak028">♦</a>
 Hath plast thy glorious image and thy vertues.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 King <i>Lewes</i> and Lady <i>Bona</i> heare me speake,</div>
<div class="dverse"><span class="lnum">30</span>
 Before you answere <i>Warwike</i> or his words,</div>
<div class="dverse">For hee it is hath done vs all these wrongs.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Iniurious <i>Margaret</i>.</div>

<div class="dverse1"><span class="sd-cn">Prince Ed.</span>
 And why not Queene?</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Because thy father <i>Henry</i> did vsurpe,</div>
<div class="dverse"><span class="lnum">35</span>
 And thou no more art Prince then shee is Queene.</div>

<div class="dverse1"><span class="sd-cn">Ox.</span>
 Then <i>Warwike</i> disanuls great <i>Iohn</i> of <i>Gaunt</i>,</div>
<div class="dverse">That did subdue the greatest part of <i>Spaine</i>,</div>
<div class="dverse">And after <i>Iohn</i> of <i>Gaunt</i> wise <i>Henry</i> the fourth,</div>
<div class="dverse">Whose wisedome was a mirrour to the world.</div>
<div class="dverse"><span class="lnum">40</span>
 And after this wise prince <i>Henry</i> the fift,</div>
<div class="dverse">Who with his prowesse conquered all <i>France</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eak042" id="lnum-eak042">♦</a>
 From these our <i>Henries</i> lineallie discent.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 <i>Oxford</i>, how haps that in this smooth discourse</div>
<div class="dverse">You told not how <i>Henry</i> the sixt had lost</div>
<div class="dverse"><span class="lnum">45</span>
 All that <i>Henry</i> the fift had gotten.</div>
<div class="dverse">Me thinkes these peeres of <i>France</i> should smile at that,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eak047" id="lnum-eak047">♦</a>
 But for the rest you tell a pettigree</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eak048" id="lnum-eak048">♦</a>
 Of threescore and two yeares a sillie time,</div>
<div class="dverse">To make prescription for a kingdomes worth.</div>

<div class="dverse1"><span class="lnum">50</span>
 <span class="sd-cn">Oxf.</span>
 Why <i>Warwike</i>, canst thou denie thy king,</div>
<div class="dverse">Whom thou obeyedst thirtie and eight yeeres,</div>
<div class="dverse">And bewray thy treasons with a blush?</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Can <i>Oxford</i> that did euer fence the right,</div>
<div class="dverse">Now buckler falshood with a pettigree?</div>
<div class="dverse"><span class="lnum">55</span>
 For shame leaue <i>Henry</i> and call <i>Edward</i> king.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eak056" id="lnum-eak056">♦</a>
 <span class="sd-cn">Oxf.</span>
  Call him my king by whom mine elder</div>
<div class="dverse">Brother the Lord <i>Awbray Vere</i> was done to death,</div>
<div class="dverse">And more then so, my father euen in the</div>
<div class="dverse">Downefall of his mellowed yeares,</div>
<div class="dverse"><span class="lnum">60</span>
 When age did call him to the dore of death?</div>
<div class="dverse">No <i>Warwike</i> no, whilst life vpholds this arme</div>
<div class="dverse">This arme vpholds the house of <i>Lancaster</i>.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 And I the house of <i>Yorke</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eak064" id="lnum-eak064">♦</a>
 <span class="sd-cn">K Lewes.</span>
 Queene <i>Margaret</i>, prince <i>Edward</i> and</div>
<div class="dverse"><span class="lnum">65</span>
 <i>Oxford</i>, vouchsafe to forbeare a while,</div>
<div class="dverse">Till I doe talke a word with <i>Warwike</i>.</div>
<div class="dverse">Now Warwike euen vpon thy honor tell me true;</div>
<div class="dverse">Is <i>Edward</i> lawfull king or no?</div>
<div class="dverse">For I were loath to linke with him, that is not lawful heir.</div>

<div class="dverse1"><span class="lnum">70</span>
 <span class="sd-cn">War.</span>
 Thereon <i>I</i> pawne mine honour and my credit.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eak071" id="lnum-eak071">♦</a>
 <span class="sd-cn">Lew.</span>
  What is he gratious in the peoples eies?</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 The more, that <i>Henry</i> is vnfortunate.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eak074" id="lnum-eak074">♦</a>
 <span class="sd-cn">Lew.</span>
 What is his loue to our sister <i>Bona</i>?</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Such it seemes</div>
<div class="dverse"><span class="lnum">75</span>
 As maie beseeme a monarke like himselfe.</div>
<div class="dverse">My selfe haue often heard him saie and sweare,</div>
<div class="dverse">That this his loue was an eternall plant,</div>
<div class="dverse">The root whereof was fixt in vertues ground,</div>
<div class="dverse">The leaues and fruite maintainde with beauties sun,</div>
<div class="dverse"><span class="lnum">80</span>
 Exempt from enuie, but not from disdaine,</div>
<div class="dverse">Vnlesse the ladie <i>Bona</i> quite his paine.</div>

<div class="dverse1"><span class="sd-cn">Lew.</span>
 Then sister let vs heare your firme resolue.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eak083" id="lnum-eak083">♦</a>
 <span class="sd-cn">Bona.</span>
  Your grant or your denial shall be mine,</div>
<div class="dverse">But ere this daie <i>I</i> must confesse, when I</div>
<div class="dverse"><span class="lnum">85</span>
 Haue heard your kings deserts recounted,</div>
<div class="dverse">Mine eares haue tempted iudgement to desire.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eak087" id="lnum-eak087">♦</a>
 <span class="sd-cn">Lew.</span>
 Then draw neere Queene <i>Margaret</i> and be a</div>
<div class="dverse">Witnesse, that <i>Bona</i> shall be wife to the English king.</div>

<div class="dverse1"><span class="sd-cn">Prince Edw.</span>
 To <i>Edward</i>, but not the English king.</div>

<div class="dverse1"><span class="lnum">90</span>
 <span class="sd-cn">War.</span>
 <i>Henry</i> now liues in <i>Scotland</i> at his ease,</div>
<div class="dverse">Where hauing nothing, nothing can he lose,</div>
<div class="dverse">And as for you your selfe our <i>quondam</i> Queene,</div>
<div class="dverse">You haue a father able to mainetaine your state,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eak094" id="lnum-eak094">♦</a>
 And better twere to trouble him then <i>France</i>.</div>

<div class="sd-entry">Sound for a post within.</div>

<div class="dverse1"><span class="lnum">95</span>
 <span class="sd-cn">Lew.</span>
 Here comes some post <i>Warwike</i> to thee or vs.</div>

<div class="dverse1"><span class="sd-cn">Post.</span>
 My Lord ambassador this letter is for you,</div>
<div class="dverse">Sent from your brother Marquis <i>Montague</i>.</div>
<div class="dverse">This from our king vnto your Maiestie.</div>
<div class="dverse">And these to you Madam, from whom I know not.</div>

<div class="dverse1"><span class="lnum">100</span>
 <span class="sd-cn">Oxf.</span>
  I like it well that our faire Queene and mistresse,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eak101" id="lnum-eak101">♦</a>
 Smiles at her newes when <i>Warwike</i> frets as his.</div>

<div class="dverse1"><span class="sd-cn">P. Ed.</span>
 And marke how <i>Lewes</i> stamps as he were nettled.</div>

<div class="dverse1"><span class="sd-cn">Lew.</span>
 Now <i>Margaret</i> &amp; <i>Warwike</i>, what are your news?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eak104" id="lnum-eak104">♦</a>
 <span class="sd-cn">Queen.</span>
  Mine such as fils my hart full of ioie.</div>

<div class="dverse1"><span class="lnum">105</span>
 <span class="sd-cn">War.</span>
  Mine full of sorrow and harts discontent.</div>

<div class="dverse1"><span class="sd-cn">Lew.</span>
 What hath your king married the Ladie <i>Gray</i>,</div>
<div class="dverse">And now to excuse himselfe sends vs a post of papers?</div>
<div class="dverse">How dares he presume to vse vs thus?</div>

<div class="dverse1"><span class="sd-cn">Quee.</span>
 This proueth <i>Edwards</i> loue, &amp; <i>Warwiks</i> honesty.</div>

<div class="dverse1"><span class="lnum">110</span>
 <span class="sd-cn">War.</span>
 King <i>Lewis,</i> I here protest in sight of heauen,</div>
<div class="dverse">And by the hope <i>I</i> haue of heauenlie blisse,</div>
<div class="dverse">That I am cleare from this misdeed of <i>Edwards</i>.</div>
<div class="dverse">No more my king, for he dishonours me,</div>
<div class="dverse">And most himselfe, if he could see his shame.</div>
<div class="dverse"><span class="lnum">115</span>
 Did I forget that by the house of <i>Yorke</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eak116" id="lnum-eak116">♦</a>
 My father came vntimelie to his death?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eak117" id="lnum-eak117">♦</a>
 Did <i>I</i> let passe the abuse done to my neece?</div>
<div class="dverse">Did I impale him with the regall Crowne,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eak119" id="lnum-eak119">♦</a>
 And thrust king <i>Henry</i> from his natiue home,</div>
<div class="dverse"><span class="lnum">120</span>
 And most vngratefull doth he vse me thus?</div>
<div class="dverse">My gratious <i>Queene</i> pardon what is past,</div>
<div class="dverse">And henceforth I am thy true seruitour,</div>
<div class="dverse">I will reuenge the wrongs done to ladie <i>Bona</i>,</div>
<div class="dverse">And replant <i>Henry</i> in his former state.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eak125" id="lnum-eak125">125</a>
 <span class="sd-cn">Queen.</span>
 Yes <i>Warwike</i> I doe quite forget thy former</div>
<div class="dverse">Faults, if now thou wilt become king <i>Henries</i> friend.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 So much his friend, I his vnfained friend,</div>
<div class="dverse">That if king <i>Lewes</i> vouchsafe to furnish vs</div>
<div class="dverse">With some few bands of chosen souldiers,</div>
<div class="dverse"><span class="lnum">130</span>
 Ile vndertake to land them on our coast,</div>
<div class="dverse">And force the Tyrant from his seate by warre,</div>
<div class="dverse">Tis not his new made bride shall succour him.</div>

<div class="dverse1"><span class="sd-cn">Lew.</span>
 Then at the last I firmelie am resolu’d,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eak134" id="lnum-eak134">♦</a>
 You shall haue aide: and English messenger returne</div>
<div class="dverse">In post, and tell false <i>Edward</i> thy supposed king,</div>
<div class="dverse">That <i>Lewis</i> of France is sending ouer Maskers</div>
<div class="dverse">To reuell it with him and his new bride.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eak138" id="lnum-eak138">♦</a>
 <span class="sd-cn">Bona.</span>
  Tell him in hope heele be a Widower shortlie,</div>
<div class="dverse">Ile weare the willow garland for his sake.</div>

<div class="dverse1"><span class="lnum">140</span>
 <span class="sd-cn">Queen.</span>
  Tell him my mourning weedes be laide aside,</div>
<div class="dverse">
 And I am readie to put armour on.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Tell him from me, that he hath done me wrong,</div>
<div class="dverse">And therefore Ile vncrowne him er’t be long.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eak144" id="lnum-eak144">♦</a>
 Thears thy reward, begone.</div>

<div class="dverse1"><span class="lnum">145</span>
 <span class="sd-cn">Lew.</span>
 But now tell me <i>Warwike</i>, what assurance</div>
<div class="dverse"><i>I</i> shall haue of thy true loyaltie?</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 This shall assure my constant loyaltie,</div>
<div class="dverse">If that our Queene and this young prince agree,</div>
<div class="dverse">Ile ioine mine eldest daughter and my ioie</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eak150" id="lnum-eak150">150</a>
 To him forthwith in holie wedlockes bandes.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eak151" id="lnum-eak151">♦</a>
 <span class="sd-cn">Queen.</span>
 Withall my hart, that match <i>I</i> like full wel,</div>
<div class="dverse">Loue her sonne <i>Edward</i>, shee is faire and yong,</div>
<div class="dverse">And giue thy hand to <i>Warwike</i> for thy loue.</div>

<div class="dverse1"><span class="sd-cn">Lew.</span>
 <i>I</i>t is enough, and now we will prepare,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eak155" id="lnum-eak155">155</a>
 To lcuie souldiers for to go with you.</div>
<div class="dverse">And you Lord <i>Bourbon</i> our high Admirall,</div>
<div class="dverse">Shall waft them safelie to the English coast,</div>
<div class="dverse">And chase proud <i>Edward</i> from his slumbring trance,</div>
<div class="dverse">For mocking marriage with the name of <i>France</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eak160" id="lnum-eak160">160</a>
 <span class="sd-cn">War.</span>
 <i>I</i> came from <i>Edward</i> as Imbassadour</div>
<div class="dverse">But I returne his sworne and mortall foe:</div>
<div class="dverse">Matter of marriage was the charge he gaue me,</div>
<div class="dverse">But dreadfull warre shall answere his demand.</div>
<div class="dverse">Had he none else to make a stale but me?</div>
<div class="dverse"><span class="lnum">165</span>
 Then none but I shall turne his iest to sorrow.</div>
<div class="dverse"><i>I</i> was the chiefe that raisde him to the crowne,</div>
<div class="dverse">And <i>I</i>le be chiefe to bring him downe againe,</div>
<div class="dverse">Not that I pittie <i>Henries</i> miserie,</div>
<div class="dverse">But seeke reuenge on <i>Edwards</i> mockerie. <span class="sd-verseend"><i>Exit.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> XII.
<span class="dnavigatenf">eal</span></h3>

Enter king <i>Edward</i>, the <i>Queene</i> and <i>Clarence</i>, and <i>Gloster</i>, and <i>Montague</i>, and <i>Hastings</i>, and <i>Penbrooke</i> with souldiers.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eal001" id="lnum-eal001">♦</a>
 <span class="sd-cn">Edw.</span>
 Brothers of <i>Clarence</i>, and of <i>Glocester</i>,</div>
<div class="dverse">What thinke you of our marriage with the ladie <i>Gray</i>?</div>

<div class="dverse1"><span class="sd-cn">Cla.</span>
 My Lord, we thinke as <i>Warwike</i> and <i>Lewes</i></div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eal004" id="lnum-eal004">♦</a>
 That are so slacke in iudgement, that theile take</div>
<div class="dverse"><span class="lnum">5</span>
 No offence at this suddaine marriage.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eal006" id="lnum-eal006">♦</a>
 <span class="sd-cn">Edw.</span>
 Suppose they doe, they are but <i>Lewes</i> and</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eal007" id="lnum-eal007">♦</a>
 <i>Warwike</i>, and I am your king and <i>Warwikes</i>,</div>
<div class="dverse">And will be obaied.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eal009" id="lnum-eal009">♦</a>
 <span class="sd-cn">Glo.</span>
  And shall, because our king, but yet such</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eal010" id="lnum-eal010">10</a>
 Sudden marriages seldome proueth well.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Yea brother <i>Richard</i> are you against vs too?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eal012" id="lnum-eal012">♦</a>
 <span class="sd-cn">Glo.</span>
 Not <i>I</i> my Lord, no, God forefend that I should</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eal013" id="lnum-eal013">♦</a>
 Once gaine saie your highnesse pleasure,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eal014" id="lnum-eal014">♦</a>
 I, &amp; twere a pittie to sunder them that yoake so wel
 <span class="nowrap">togi- (ther.</span></div>

<div class="dverse1"><span class="lnum">15</span>
 <span class="sd-cn">Edw.</span>
  Setting your skornes and your dislikes aside,</div>
<div class="dverse">Shew me some reasons why the Ladie <i>Gray</i>,</div>
<div class="dverse">Maie not be my loue and Englands <i>Queene</i>?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eal018" id="lnum-eal018">♦</a>
 Speake freelie <i>Clarence</i>, <i>Gloster</i>,</div>
<div class="dverse"><i>Montague</i> and <i>Hastings</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eal020" id="lnum-eal020">20</a>
 <span class="sd-cn">Cla.</span>
  My Lord then this is my opinion,</div>
<div class="dverse">That <i>Warwike</i> beeing dishonored in his embassage,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eal022" id="lnum-eal022">♦</a>
 Doth seeke reuenge to quite his iniuries.</div>

<div class="dverse1"><span class="sd-cn">Glo.</span>
 And <i>Lewes</i> in regard of his sisters wrongs,</div>
<div class="dverse">Doth ioine with <i>Warwike</i> to supplant your state,</div>

<div class="dverse1"><span class="lnum">25</span>
 <span class="sd-cn">Edw.</span>
 Suppose that <i>Lewis</i> and <i>Warwike</i> be appeasd,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eal026" id="lnum-eal026">♦</a>
 By such meanes as I can best deuise.</div>

<div class="dverse1"><span class="sd-cn">Mont.</span>
 But yet to have ioind with France in this</div>
<div class="dverse">Alliance, would more haue strengthened this our</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eal029" id="lnum-eal029">♦</a>
 Common wealth, gainst forraine stormes,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eal030" id="lnum-eal030">30</a>
 Then anie home bred marriage.</div>

<div class="dverse1"><span class="sd-cn">Hast.</span>
 Let England be true within it selfe,</div>
<div class="dverse">We need not France nor any alliance with them.</div>

<div class="dverse1"><span class="sd-cn">Cla.</span>
 For this one speech the Lord <i>Hastings</i> wel deserues,</div>
<div class="dverse">To haue the daughter and heire of the Lord <i>Hungerford</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eal035" id="lnum-eal035">35</a>
 <span class="sd-cn">Edw.</span>
  And what then? It was our will it should be so?</div>

<div class="dverse1"><span class="sd-cn">Cla.</span>
 I, and for such a thing too the Lord <i>Scales</i></div>
<div class="dverse">Did well deserue at your hands, to haue the</div>
<div class="dverse">Daughter of the Lord <i>Bonfield</i>, and left your</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eal039" id="lnum-eal039">♦</a>
 Brothers to go seeke elsewhere, but in</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eal040" id="lnum-eal040">40</a>
 Your madnes, you burie brotherhood.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Alasse poore <i>Clarence</i>, is it for a wife,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eal042" id="lnum-eal042">♦</a>
 That thou art mal-content,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eal043" id="lnum-eal043">♦</a>
 Why man be of good cheere, Ile prouide thee one.</div>

<div class="dverse1"><span class="sd-cn">Cla.</span>
 Naie you plaide the broker so ill for your selfe,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eal045" id="lnum-eal045">45</a>
 That you shall giue me leaue to make my</div>
<div class="dverse">Choise as I thinke good, and to that intent,</div>
<div class="dverse">I shortlie meane to leaue you.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Leaue me or tarrie I am full resolu’d,</div>
<div class="dverse"><i>Edward</i> will not be tied to his brothers wils.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eal050" id="lnum-eal050">50</a>
 <span class="sd-cn">Queen.</span>
  My Lords doe me but right, and you must</div>
<div class="dverse">Confesse, before it pleasd his highnesse to aduance</div>
<div class="dverse">My state to title of a Queene,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eal053" id="lnum-eal053">♦</a>
 That I was not ignoble in my birth.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Forbeare my loue to fawne upon their frownes,</div>
<div class="dverse"><span class="lnum">55</span>
 For thee they must obay, naie shall obaie,</div>
<div class="dverse">And if they looke for fauour at my hands.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eal057" id="lnum-eal057">♦</a>
 <span class="sd-cn">Mont.</span>
  My Lord, heere is the messenger returned from (France.</div>

<div class="sd-entry">Enter a Messenger.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eal058" id="lnum-eal058">♦</a>
 <span class="sd-cn">Ed.</span>
  Now sirra, What letters or what newes?</div>

<div class="dprose1"><span class="sd-cn">Mes.</span>
 No letters my Lord, and such newes, as without <a class="lnum pginternal" href="#lnote-eal060" id="lnum-eal060">60</a>
 your highnesse speciall pardon I dare not relate.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eal061" id="lnum-eal061">♦</a>
 <span class="sd-cn">Edw.</span>
  We pardon thee, and as neere as thou canst</div>
<div class="dverse">Tell me, What said <i>Lewis</i> to our letters?</div>

<div class="dverse1"><span class="sd-cn">Mes.</span>
 At my departure these were his verie words.</div>
<div class="dverse">Go tell false <i>Edward</i> thy supposed king,</div>
<div class="dverse"><span class="lnum">65</span>
 That <i>Lewis</i> of France is sending ouer Maskers,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eal066" id="lnum-eal066">♦</a>
 To reuill it with him and his new bride.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eal067" id="lnum-eal067">♦</a>
 <span class="sd-cn">Edw.</span>
 Is <i>Lewis</i> so braue, belike he thinkes me <i>Henry</i>.</div>
<div class="dverse">But what said Lady <i>Bona</i> to these wrongs?</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-eal069" id="lnum-eal069">♦</a>
 <span class="sd-cn">Mes.</span>
 Tel him quoth she, in hope heele prove a widdower <a class="lnum pginternal" href="#lnote-eal070" id="lnum-eal070">70</a>
 shortly, <i>I</i>le wear the willow garland for his sake.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eal071" id="lnum-eal071">♦</a>
 <span class="sd-cn">Edw.</span>
  She had the wrong, indeed she could saie</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eal072" id="lnum-eal072">♦</a>
 Little lesse. But what saide <i>Henries</i> Queene, for as</div>
<div class="dverse"><i>I</i> heare, she was then in place?</div>

<div class="dverse1"><span class="sd-cn">Mes.</span>
 Tell him quoth shee my mourning weeds be</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eal075" id="lnum-eal075">75</a>
 Doone, and I am readie to put armour on.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Then belike she meanes to plaie the <i>Amazon</i>.</div>
<div class="dverse">But what said <i>Warwike</i> to these iniuries?</div>

<div class="dverse1"><span class="sd-cn">Mes.</span>
 He more incensed then the rest my Lord,</div>
<div class="dverse">Tell him quoth he, that he hath done me wrong,</div>
<div class="dverse"><span class="lnum">80</span>
 And therefore Ile vncrowne him er’t be long.</div>

<div class="dverse1"><span class="sd-cn">Ed.</span>
 Ha, Durst the traytor breath out such proude words?</div>
<div class="dverse">But I will arme me to preuent the worst.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eal083" id="lnum-eal083">♦</a>
 But what is <i>Warwike</i> friendes with <i>Margaret</i>?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eal084" id="lnum-eal084">♦</a>
 <span class="sd-cn">Mes.</span>
  I my good Lord, theare so linkt in friendship,</div>
<div class="dverse"><span class="lnum">85</span>
 That young Prince <i>Edward</i> marries <i>Warwikes</i> daughter.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eal086" id="lnum-eal086">♦</a>
 <span class="sd-cn">Cla.</span>
 The elder, belike <i>Clarence</i> shall haue the</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eal087" id="lnum-eal087">♦</a>
 Yonger. All you that loue me and <i>Warwike</i></div>
<div class="dverse">Follow me.
 <span class="sd-verseend"><i>Exit Clarence</i> and <i>Summerset.</i></span></div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 <i>Clarence</i> and <i>Summerset</i> fled to <i>Warwike</i>,</div>
<div class="dverse"><span class="lnum">90</span>
 What saie you brother <i>Richard</i>, will you stand to vs?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eal091" id="lnum-eal091">♦</a>
 <span class="sd-cn">Glo.</span>
 <i>I</i> my Lord, in despight of all that shall</div>
<div class="dverse">Withstand you  For why hath Nature</div>
<div class="dverse">Made me halt downe right, but that I</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eal094" id="lnum-eal094">♦</a>
 Should be valiant and stand to it, for if</div>
<div class="dverse"><span class="lnum">95</span>
 I would, <i>I</i> cannot runne awaie.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 <i>Penbrooke</i>, go raise an armie presentlie,</div>
<div class="dverse">Pitch vp my tent, for in the field this night</div>
<div class="dverse">I meane to rest, and on the morrow morne,</div>
<div class="dverse">Ile march to meet proud <i>Warwike</i> ere he land</div>
<div class="dverse"><span class="lnum">100</span>
 Those stragling troopes which he hath got in France.</div>
<div class="dverse">But ere I goe <i>Montague</i> and <i>Hastings</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eal102" id="lnum-eal102">♦</a>
 You of all the rest are neerest allied</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eal103" id="lnum-eal103">♦</a>
 In bloud to <i>Warwike</i>, therefore tell me, if</div>
<div class="dverse">You fauour him more then me or not:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eal105" id="lnum-eal105">105</a>
 Speake truelie, for I had rather haue you open</div>
<div class="dverse">Enemies, then hollow friends.</div>

<div class="dverse1"><span class="sd-cn">Monta.</span>
 So God helpe <i>Montague</i> as he proues true.</div>

<div class="dverse1"><span class="sd-cn">Hast.</span>
 And <i>Hastings</i> as hee fauours <i>Edwards</i> cause.</div>

<div class="dverse"><a class="lnum pginternal" href="#lnote-eal109" id="lnum-eal109">♦</a>
 Edw. It shall suffice, come then lets march awaie.
 <span class="sd-verseend"><i>Exeunt Omnes.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> XIII.
<span class="dnavigatenf">eam</span></h3>

Enter <i>Warwike</i> and <i>Oxford</i>, with souldiers.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Trust me my Lords all hitherto goes well,</div>
<div class="dverse">The common people by numbers swarme to vs,</div>
<div class="dverse">But see where <i>Sommerset</i> and <i>Clarence</i> comes,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eam004" id="lnum-eam004">♦</a>
 Speake suddenlie my Lords, are we all friends?</div>

<div class="dverse1"><span class="lnum">5</span>
 <span class="sd-cn">Cla.</span>
  Feare not that my Lord.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Then gentle <i>Clarence</i> welcome vnto <i>Warwike</i>.</div>
<div class="dverse">And welcome <i>Summerset</i>, I hold it cowardise,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eam008" id="lnum-eam008">♦</a>
 To rest mistrustfull where a noble hart,</div>
<div class="dverse">Hath pawnde an open hand in signe of loue,</div>
<div class="dverse"><span class="lnum">10</span>
 Else might I thinke that <i>Clarence</i>, <i>Edwards</i> brother,</div>
<div class="dverse">Were but a fained friend to our proceedings,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eam012" id="lnum-eam012">♦</a>
 But welcome sweet <i>Clarence</i> my daughter shal be thine.</div>
<div class="dverse">And now what rests but in nights couerture,</div>
<div class="dverse">Thy brother being careleslie encampt,</div>
<div class="dverse"><span class="lnum">15</span>
 His souldiers lurking in the towne about,</div>
<div class="dverse">And but attended by a simple guarde,</div>
<div class="dverse">We maie surprise and take him at our pleasure,</div>
<div class="dverse">Our skouts have found the aduenture very easie,</div>
<div class="dverse">Then crie king <i>Henry</i> with resolued mindes,</div>
<div class="dverse"><span class="lnum">20</span>
 And breake we presentlie into his tent.</div>

<div class="dverse1"><span class="sd-cn">Cla.</span>
 Why then lets on our waie in silent sort,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eam022" id="lnum-eam022">♦</a>
 For <i>Warwike</i> and his friends God and saint <i>George</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eam023" id="lnum-eam023">♦</a>
 <span class="sd-cn">War.</span>
  This is his tent, and see where his guard doth</div>
<div class="dverse">Stand, Courage my souldiers, now or neuer,</div>
<div class="dverse"><span class="lnum">25</span>
 But follow me now, and <i>Edward</i> shall be ours.</div>

<div class="dverse1"><span class="sd-cn">All.</span>
 A <i>Warwike</i>, a <i>Warwike</i>. <span class="sd-verseend">Alarmes, and <i>Gloster</i> and <i>Hastings</i> flies.</span></div>

<div class="dverse1"><span class="sd-cn">Oxf.</span>
 Who goes there?</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 <i>Richard</i> and <i>Hastings</i> let them go, heere is the (Duke</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eam029" id="lnum-eam029">♦</a>
 <span class="sd-cn">Edw.</span>
 The Duke, why <i>Warwike</i> when we parted</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eam030" id="lnum-eam030">30</a>
 Last, thou caldst me king?</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 I, but the case is altred now.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eam032" id="lnum-eam032">♦</a>
 When you disgraste me in my embassage,</div>
<div class="dverse">Then <i>I</i> disgraste you from being king,</div>
<div class="dverse">And now am come to create you Duke of <i>Yorke</i>,</div>
<div class="dverse"><span class="lnum">35</span>
 Alasse how should you gouerne anie kingdome,</div>
<div class="dverse">That knowes not how to vse embassadors,</div>
<div class="dverse">Nor how to vse your brothers brotherlie,</div>
<div class="dverse">Nor how to shrowd your selfe from enimies.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Well <i>Warwike</i>, let fortune doe her worst,</div>
<div class="dverse"><span class="lnum">40</span>
 <i>Edward</i> in minde will beare himselfe a king.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Then for his minde be <i>Edward</i> Englands king.</div>
<div class="dverse">But <i>Henry</i> now shall weare the English crowne.</div>
<div class="dverse">Go conuaie him to our brother archbishop of <i>Yorke</i>,</div>
<div class="dverse">And when I haue fought with <i>Penbrooke</i> &amp; his followers,</div>
<div class="dverse"><span class="lnum">45</span>
 Ile come and tell thee what the ladie <i>Bona</i> saies,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eam046" id="lnum-eam046">♦</a>
 And so for a while farewell good Duke of <i>Yorke</i>.
 <span class="sd-verseend"><i>Exeunt</i> some with <i>Edward</i>.</span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eam047" id="lnum-eam047">♦</a>
 <span class="sd-cn">Cla.</span>
  What followes now, all hithertoo goes well,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eam048" id="lnum-eam048">♦</a>
 But we must dispatch some letters to <i>France</i>,</div>
<div class="dverse">To tell the <i>Queene</i> of our happy fortune,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eam050" id="lnum-eam050">50</a>
 And bid hir come with speed to ioine with vs.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eam051" id="lnum-eam051">♦</a>
 <span class="sd-cn">War.</span>
 <i>I</i> thats the first thing that we have to doe,</div>
<div class="dverse">And free king <i>Henry</i> from imprisonment,</div>
<div class="dverse">And see him seated in his regall throne,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eam054" id="lnum-eam054">♦</a>
 Come let vs haste awaie, and hauing past these cares,</div>
<div class="dverse"><span class="lnum">55</span>
 <i>I</i>le post to <i>Yorke</i>, and see how <i>Edward</i> fares.
 <span class="sd-verseend"><i>Exeunt Omnes.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> XIV.
<span class="dnavigatenf">ean</span></h3>

Enter <i>Gloster</i>, <i>Hastings</i>, and sir <i>William Stanly</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ean001" id="lnum-ean001">♦</a>
 <span class="sd-cn">Glo.</span>
  Lord Hastings, and sir William Stanly,</div>
<div class="dverse">Know that the cause <i>I</i> sent for you is this.</div>
<div class="dverse"><i>I</i> looke my brother with a slender traine,</div>
<div class="dverse">Should come a hunting in this forrest heere.</div>
<div class="dverse"><span class="lnum">5</span>
 The Bishop of <i>Yorke</i> befriends him much,</div>
<div class="dverse">And lets him vse his pleasure in the chase,</div>
<div class="dverse">Now I haue priuilie sent him word,</div>
<div class="dverse">How <i>I</i> am come with you to rescue him,</div>
<div class="dverse">And see where the huntsman and he doth come.</div>

<div class="sd-entry">Enter <i>Edward</i> and a Huntsman.</div>

<div class="dverse1"><span class="lnum">10</span>
 <span class="sd-cn">Hunts</span>
  This waie my Lord the deere is gone.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ean011" id="lnum-ean011">♦</a>
 <span class="sd-cn">Edw.</span>
  No this waie huntsman, see where the</div>
<div class="dverse">Keepers stand. Now brother and the rest,</div>
<div class="dverse">What, are you prouided to depart?</div>

<div class="dverse1"><span class="sd-cn">Glo.</span>
 <i>I</i>, <i>I</i>, the horse stands at the parke corner,</div>
<div class="dverse"><span class="lnum">15</span>
 Come, to Linne, and so take shipping into <i>Flanders</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ean016" id="lnum-ean016">♦</a>
 <span class="sd-cn">Edw.</span>
 Come then: <i>Hastings</i>, and <i>Stanlie</i>, <i>I</i> will</div>
<div class="dverse">Requite your loues. Bishop farewell,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ean018" id="lnum-ean018">♦</a>
 Sheeld thee from <i>Warwikes</i> frowne,</div>
<div class="dverse">And praie that I maie repossesse the crowne.</div>
<div class="dverse"><span class="lnum">20</span>
 Now huntsman what will you doe?</div>

<div class="dverse1"><span class="sd-cn">Hunts</span>
 Marrie my Lord, I thinke <i>I</i> had as good</div>
<div class="dverse">Goe with you, as tarrie heere to be hangde.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Come then lets awaie with speed. <span class="sd-verseend"><i>Exeunt Omnes.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> XV.
<span class="dnavigatenf">eao</span></h3>

Enter the <i>Queene</i> and the Lord <i>Riuers</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eao001" id="lnum-eao001">♦</a>
 <span class="sd-cn">Riuers.</span>
  Tel me good maddam, why is your grace</div>
<div class="dverse">So passionate of late?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eao003" id="lnum-eao003">♦</a>
 <span class="sd-cn">Queen.</span>
 Why brother <i>Riuers</i>, heare you not the newes,</div>
<div class="dverse">Of that successe king <i>Edward</i> had of late?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eao005" id="lnum-eao005">5</a>
 <span class="sd-cn">Riu.</span>
 What? losse of some pitcht battaile against <i>Warwike</i>,</div>
<div class="dverse">Tush, feare not faire <i>Queen</i>, but cast those cares aside.</div>
<div class="dverse">King <i>Edwards</i> noble mind his honours doth display:</div>
<div class="dverse">And <i>Warwike</i> maie loose, though then he got the day.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 If that were all, my griefes were at an end:</div>
<div class="dverse"><span class="lnum">10</span>
 But greater troubles will I feare befall.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eao011" id="lnum-eao011">♦</a>
 <span class="sd-cn">Riu.</span>
  What, is he taken prisoner by the foe,</div>
<div class="dverse">To the danger of his royall person then?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eao013" id="lnum-eao013">♦</a>
 <span class="sd-cn">Queen.</span>
 I, thears my griefe, king <i>Edward</i> is surprisde,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eao014" id="lnum-eao014">♦</a>
 And led awaie, as prisoner vnto <i>Yorke</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eao015" id="lnum-eao015">15</a>
 <span class="sd-cn">Riu.</span>
  The newes is passing strange, I must confesse:</div>
<div class="dverse">Yet comfort your selfe, for <i>Edward</i> hath more friends,</div>
<div class="dverse">Then <i>Lancaster</i> at this time must perceiue,</div>
<div class="dverse">That some will set him in his throne againe.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 God grant they maie, but gentle brother come,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eao020" id="lnum-eao020">20</a>
 And let me leane vpon thine arme a while,</div>
<div class="dverse">Vntill I come vnto the sanctuarie,</div>
<div class="dverse">There to preserue the fruit within my wombe,</div>
<div class="dverse">K. <i>Edwards</i> seed true heire to <i>Englands</i> crowne. <span class="sd-verseend"><i>Exit.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> XVI.
<span class="dnavigatenf">eap</span></h3>

Enter <i>Edward</i> and <i>Richard</i>, and <i>Hastings</i> with a troope of Hollanders.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Thus far from <i>Belgia</i> haue we past the seas,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eap002" id="lnum-eap002">♦</a>
 And marcht from <i>Raunspur</i> hauen vnto <i>Yorke</i>:</div>
<div class="dverse">But soft the gates are shut, <i>I</i> like not this.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eap004" id="lnum-eap004">♦</a>
 <span class="sd-cn">Rich.</span>
  Sound vp the drum and call them to the wals.</div>

<div class="sd-entry">Enter the Lord Maire of <i>Yorke</i> vpon the wals.</div>

<div class="dverse1"><span class="lnum">5</span>
 <span class="sd-cn">Mair.</span>
  My Lords we had notice of your comming,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eap006" id="lnum-eap006">♦</a>
 And thats the cause we stand vpon our garde,</div>
<div class="dverse">And shut the gates for to preserue the towne.</div>
<div class="dverse"><i>Henry</i> now is king, and we are sworne to him.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eap009" id="lnum-eap009">♦</a>
 <span class="sd-cn">Edw.</span>
 Why my Lord Maire, if <i>Henry</i> be your king,</div>
<div class="dverse"><span class="lnum">10</span>
 <i>Edward</i> I am sure at least, is Duke of <i>Yorke</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eap011" id="lnum-eap011">♦</a>
 <span class="sd-cn">Mair.</span>
  Truth my Lord, we know you for no lesse.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 I craue nothing but my Dukedome.</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 But when the Fox hath gotten in his head,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eap014" id="lnum-eap014">♦</a>
 Heele quicklie make the bodie follow after.</div>

<div class="dverse1"><span class="lnum">15</span>
 <span class="sd-cn">Hast.</span>
  Why my Lord Maire, what stand you vpon points?</div>
<div class="dverse">Open the gates, we are king <i>Henries</i> friends.</div>

<div class="dverse1"><span class="sd-cn">Mair.</span>
 Saie you so, then <i>I</i>le open them presentlie. <span class="sd-verseend"><i>Exit</i> Maire.</span></div>

<div class="dverse1"><span class="sd-cn">Ri.</span>
 By my faith, a wise stout captain &amp; soone perswaded. <span class="sd-verseend">The Maire opens the dore, and brings the keies in his hand.</span></div>

<div class="dverse1"><span class="lnum">20</span>
 <span class="sd-cn">Edw.</span>
  So my Lord Maire, these gates must not be shut,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eap021" id="lnum-eap021">♦</a>
 But in the time of warre, giue me the keies:</div>
<div class="dverse">What, feare not man for <i>Edward</i> will defend</div>
<div class="dverse">the towne and you, despight of all your foes.</div>

<div class="sd-entry">Enter sir <i>Iohn Mountgommery</i> with drumme and souldiers.</div>

<div class="dverse">How now <i>Richard</i>, who is this?</div>

<div class="dverse1"><span class="sd-cn">Rich.</span>
 Brother, this is sir Iohn <i>Mountgommery</i>,</div>
<div class="dverse"><span class="lnum">25</span>
 A trustie friend, vnlesse <i>I</i> be deceiude.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Welcome sir Iohn. Wherfore come you in armes?</div>

<div class="dverse1"><span class="sd-cn">Sir Iohn.</span>
 To helpe king <i>Edward</i> in this time of stormes,</div>
<div class="dverse">As euerie loyall subiect ought to doe.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Thankes braue Mountgommery,</div>
<div class="dverse"><span class="lnum">30</span>
 But I onlie claime my Dukedom.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eap031" id="lnum-eap031">♦</a>
 Vntil it please God to send the rest.</div>

<div class="dverse1"><span class="sd-cn">Sir Iohn.</span>
 Then fare you wel? Drum strike vp and let vs</div>
<div class="dverse">March away, I came to serue a king and not a Duke.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Nay staie sir Iohn, and let vs first debate,</div>
<div class="dverse"><span class="lnum">35</span>
 With what security we maie doe this thing.</div>

<div class="dverse1"><span class="sd-cn">Sir Iohn.</span>
 What stand you on debating, to be briefe,</div>
<div class="dverse">Except you presently proclaime your selfe our king,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eap038" id="lnum-eap038">♦</a>
 Ile hence againe, and keepe them backe that come to</div>
<div class="dverse">Succour you, why should we fight when</div>
<div class="dverse"><span class="lnum">40</span>
 You pretend no title?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eap041" id="lnum-eap041">♦</a>
 <span class="sd-cn">Rich.</span>
  Fie brother, fie, stand you vpon tearmes?</div>
<div class="dverse">Resolue your selfe, and let vs claime the crowne.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 <i>I</i> am resolude once more to claime the crowne,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eap044" id="lnum-eap044">♦</a>
 And win it too, or else to loose my life.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eap045" id="lnum-eap045">45</a>
 <span class="sd-cn">Sir Iohn.</span>
  I now my soueraigne speaketh like himselfe,</div>
<div class="dverse">And now will I be <i>Edwards</i> Champion,</div>
<div class="dverse">Sound Trumpets, for <i>Edward</i> shall be proclaimd.</div>

<div class="dprose1"><a class="lnum pginternal" href="#lnote-eap048" id="lnum-eap048">♦</a>
 <span class="sd-cn">Edward</span>
 the fourth by the grace of God, king of England and France, and Lord of Ireland, and whosoeuer gainsaies <span class="lnum">50</span>
 king <i>Edwards</i> right: by this <i>I</i> challenge him to single fight, long liue <i>Edward</i> the fourth.</div>

<div class="dverse1"><span class="sd-cn">All.</span>
 Long liue <i>Edward</i> the fourth.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 We thanke you all. Lord Maire leade on the waie.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eap054" id="lnum-eap054">♦</a>
 For this night weele harbour here in <i>Yorke</i>,</div>
<div class="dverse"><span class="lnum">55</span>
 And then as earlie as the morning sunne,</div>
<div class="dverse">Liftes vp his beames aboue this horison</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eap057" id="lnum-eap057">♦</a>
 Weele march to London, to meete with <i>Warwike</i>:</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eap058" id="lnum-eap058">♦</a>
 And pull false <i>Henry</i> from the Regall throne.
 <span class="sd-verseend"><i>Exeunt Omnes.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> XVII.
<span class="dnavigatenf">eaq</span></h3>

Enter <i>Warwike</i> and <i>Clarence</i>, with the Crowne, and then king <i>Henry</i>, and <i>Oxford</i>, and <i>Summerset</i>, and the yong Earle of <i>Richmond</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaq001" id="lnum-eaq001">♦</a>
 <span class="sd-cn">King.</span>
  Thus from the prison to this princelie seat,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaq002" id="lnum-eaq002">♦</a>
 By Gods great mercies am <i>I</i> brought</div>
<div class="dverse">Againe, <i>Clarence</i> and <i>Warwike</i> doe you</div>
<div class="dverse">Keepe the crowne, and gouerne and protect</div>
<div class="dverse"><span class="lnum">5</span>
 My realme in peace, and I will spend the</div>
<div class="dverse">Remnant of my daies, to sinnes rebuke</div>
<div class="dverse">And my Creators praise.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 What answeres <i>Clarence</i> to his soueraignes will?</div>

<div class="dverse1"><span class="sd-cn">Cla.</span>
 <i>Clarence</i> agrees to what king <i>Henry</i> likes.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaq010" id="lnum-eaq010">10</a>
 <span class="sd-cn">King.</span>
 My Lord of <i>Summerset</i>, what prettie</div>
<div class="dverse">Boie is that you seeme to be so carefull of?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaq012" id="lnum-eaq012">♦</a>
 <span class="sd-cn">Sum.</span>
 And it please your grace, it is yong <i>Henry</i>,</div>
<div class="dverse">Earle of <i>Richmond</i>.</div>

<div class="dverse1"><span class="sd-cn">King.</span>
 <i>Henry</i> of <i>Richmond</i>, Come hither pretie Ladde.</div>
<div class="dverse"><span class="lnum">15</span>
 If heauenlie powers doe aime aright</div>
<div class="dverse">To my diuining thoughts, thou pretie boy,</div>
<div class="dverse">Shalt proue this Countries blisse,</div>
<div class="dverse">Thy head is made to weare a princelie crowne,</div>
<div class="dverse">Thy lookes are all repleat with Maiestie,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaq020" id="lnum-eaq020">20</a>
 Make much of him my Lords,</div>
<div class="dverse">For this is he shall helpe you more,</div>
<div class="dverse">Then you are hurt by me.</div>

<div class="sd-entry">Enter one with a letter to <i>Warwike</i>.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 What Counsell Lords, <i>Edward</i> from <i>Belgia</i>,</div>
<div class="dverse">With hastie Germaines and blunt <i>Hollanders</i>,</div>
<div class="dverse"><span class="lnum">25</span>
 Is past in safetie through the narrow seas,</div>
<div class="dverse">And with his troopes doe march amaine towardes (London,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaq027" id="lnum-eaq027">♦</a>
 And manie giddie people follow him.</div>

<div class="dverse1"><span class="sd-cn">Oxf.</span>
 Tis best to looke to this betimes,</div>
<div class="dverse">For if this fire doe kindle any further,</div>
<div class="dverse"><span class="lnum">30</span>
 It will be hard for vs to quench it out.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 In <i>Warwike</i>shire <i>I</i> haue true harted friends,</div>
<div class="dverse">Not mutinous in peace, yet bold in warre,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaq033" id="lnum-eaq033">♦</a>
 Them will <i>I</i> muster vp, and thou sonne <i>Clarence</i> shalt</div>
<div class="dverse">In <i>Essex</i>, <i>Suffolke</i>, <i>Norfolke</i>, and in <i>Kent</i>,</div>
<div class="dverse"><span class="lnum">35</span>
 Stir vp the knights and gentlemen to come with thee.</div>
<div class="dverse">And thou brother <i>Montague</i>, in <i>Leister</i>shire,</div>
<div class="dverse"><i>Buckingham</i> and <i>Northampton</i>shire shalt finde,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaq038" id="lnum-eaq038">♦</a>
 Men well inclinde to doe what thou commands,</div>
<div class="dverse">And thou braue <i>Oxford</i> wondrous well belou’d,</div>
<div class="dverse"><span class="lnum">40</span>
 Shalt in thy countries muster vp thy friends.</div>
<div class="dverse">My soueraigne with his louing Citizens,</div>
<div class="dverse">Shall rest in London till we come to him.</div>
<div class="dverse">Faire Lords take leaue and stand not to replie,</div>
<div class="dverse">Farewell my soueraigne.</div>

<div class="dverse1"><span class="lnum">45</span>
 <span class="sd-cn">King.</span>
 Farewel my <i>Hector</i>, my <i>Troyes</i> true hope.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Farewell sweet Lords, lets meet at Couentrie.</div>

<div class="dverse1"><span class="sd-cn">All.</span>
 Agreed. <span class="sd-verseend"><i>Exeunt Omnes.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> XVIII.
<span class="dnavigatenf">ear</span></h3>

Enter <i>Edward</i> and his traine.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-ear001" id="lnum-ear001">♦</a>
 <span class="sd-cn">Edw.</span>
 Sease on the shamefast <i>Henry</i>,</div>
<div class="dverse">And once againe conuaie him to the Tower,</div>
<div class="dverse">Awaie with him, I will not heare him speake.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-ear004" id="lnum-ear004">♦</a>
 And now towards Couentrie let vs bend our course</div>
<div class="dverse"><span class="lnum">5</span>
 To meet with <i>Warwike</i> and his confederates.
 <span class="sd-verseend"><i>Exeunt Omnes.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> XIX.
<span class="dnavigatenf">eas</span></h3>

Enter <i>Warwike</i> on the walles.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Where is the post that came from valiant <i>Oxford</i>?</div>
<div class="dverse">How farre hence is thy Lord my honest fellow?</div>

<div class="dverse1"><span class="sd-cn">Oxf post.</span>
 By this at <i>Daintrie</i> marching hitherward.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Where is our brother <i>Montague</i>?</div>
<div class="dverse"><span class="lnum">5</span>
 Where is the post that came from <i>Montague</i>?</div>

<div class="dverse1"><span class="sd-cn">Post.</span>
 I left him at <i>Donsmore</i> with his troopes.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Say <i>Summerfield</i> where is my louing son?</div>
<div class="dverse">And by thy gesse, how farre is <i>Clarence</i> hence?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eas009" id="lnum-eas009">♦</a>
 <span class="sd-cn">Sommer.</span>
 At <i>Southam</i> my Lord I left him with</div>
<div class="dverse"><span class="lnum">10</span>
 His force, and doe expect him two houres hence.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Then Oxford is at hand, I heare his drum.</div>

<div class="sd-entry">Enter <i>Edward</i> and his power.</div>

<div class="dverse1"><span class="sd-cn">Glo.</span>
 See brother, where the surly <i>Warwike</i> mans the wal.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eas013" id="lnum-eas013">♦</a>
 <span class="sd-cn">War.</span>
 O vnbid spight, is spotfull <i>Edward</i> come!</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eas014" id="lnum-eas014">♦</a>
 Where slept our scouts, or how are they seduste,</div>
<div class="dverse"><span class="lnum">15</span>
 That we could haue no newes of their repaire?</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Now <i>Warwike</i> wilt thou be sorrie for thy faults,</div>
<div class="dverse">And call <i>Edward</i> king and he will pardon thee.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Naie rather wilt thou draw thy forces backe?</div>
<div class="dverse">Confesse who set thee vp and puld thee downe?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eas020" id="lnum-eas020">20</a>
 Call <i>Warwike</i> patron and be penitent,</div>
<div class="dverse">And thou shall still remaine the Duke of <i>Yorke</i>.</div>

<div class="dverse1"><span class="sd-cn">Glo.</span>
 I had thought at least he would haue said the king.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eas023" id="lnum-eas023">♦</a>
 Or did he make the iest against his will.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eas024" id="lnum-eas024">♦</a>
 <span class="sd-cn">War.</span>
 Twas <i>Warwike</i> gaue the kingdome to thy brother.</div>

<div class="dverse1"><span class="lnum">25</span>
 <span class="sd-cn">Edw.</span>
 Why then tis mine, if but by <i>Warwikes</i> gift.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 I but thou art no <i>Atlas</i> for so great a waight,</div>
<div class="dverse">And weakling, <i>Warwike</i> takes his gift againe,</div>
<div class="dverse"><i>Henry</i> is my king, <i>Warwike</i> his subiect.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 I prethe gallant <i>Warwike</i> tell me this,</div>
<div class="dverse"><span class="lnum">30</span>
 What is the bodie when the head is off?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eas031" id="lnum-eas031">♦</a>
 <span class="sd-cn">Glo.</span>
 Alasse that <i>Warwike</i> had no more foresight,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eas032" id="lnum-eas032">♦</a>
 But whilst he sought to steale the single ten,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eas033" id="lnum-eas033">♦</a>
 The king was finelie fingerd from the decke?</div>
<div class="dverse">You left poore <i>Henry</i> in the Bishops pallace,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eas035" id="lnum-eas035">35</a>
 And ten to one you’le meet him in the Tower.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Tis euen so, and yet you are olde <i>Warwike</i> still.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eas037" id="lnum-eas037">♦</a>
 <span class="sd-cn">War.</span>
  O cheerefull colours, see where Oxford comes.</div>

<div class="sd-entry">Enter <i>Oxford</i> with drum and souldiers &amp; al crie,</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eas038" id="lnum-eas038">♦</a>
 <span class="sd-cn">Oxf.</span>
 Oxford, Oxford, for <i>Lancaster</i>. <span class="sd-verseend"><i>Exit.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eas039" id="lnum-eas039">♦</a>
 <span class="sd-cn">Edw.</span>
  The Gates are open, see they enter in,</div>
<div class="dverse"><span class="lnum">40</span>
 Lets follow them and bid them battaile in the streetes.</div>

<div class="dverse1"><span class="sd-cn">Glo.</span>
 No, so some other might set vpon our backes,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eas042" id="lnum-eas042">♦</a>
 Weele staie till all be entered, and then follow them.</div>

<div class="sd-entry">Enter <i>Summerset</i> with drum and souldiers.</div>

<div class="dverse1"><span class="sd-cn">Sum.</span>
 <i>Summerset</i>, <i>Summerset</i>, for <i>Lancaster</i>. <span class="sd-verseend"><i>Exit.</i></span></div>

<div class="dverse1"><span class="sd-cn">Glo.</span>
 Two of thy name both Dukes of Summerset,</div>
<div class="dverse"><span class="lnum">45</span>
 Haue solde their liues vnto the house of <i>Yorke</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eas046" id="lnum-eas046">♦</a>
 And thou shalt be the third and my sword hold.</div>

<div class="sd-entry">Enter <i>Montague</i> with drum and souldiers.</div>

<div class="dverse1"><span class="sd-cn">Mont.</span>
 <i>Montague</i>, <i>Montague</i>, for <i>Lancaster</i>. <span class="sd-verseend"><i>Exit.</i></span></div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Traitorous <i>Montague</i>, thou and thy brother</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eas049" id="lnum-eas049">♦</a>
 Shall deerelie abie this rebellious act.</div>

<div class="sd-entry">Enter <i>Clarence</i> with drum and souldiers.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eas050" id="lnum-eas050">50</a>
 <span class="sd-cn">War.</span>
  And loe where George of Clarence sweepes</div>
<div class="dverse" id="lnumeas051">
 Along, of power enough to bid his brother battell..</div>

<div class="dverse1"><span class="sd-cn">Cla.</span>
 Clarence, Clarence, for <i>Lancaster</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eas052" id="lnum-eas052">♦</a>
 <span class="sd-cn">Edw.</span>
 Et tu Brute, wilt thou stab <i>Cæsar</i> too?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eas053" id="lnum-eas053">♦</a>
 A parlie sirra to <i>George</i> of Clarence.</div>

<div class="sd-entry">Sound a Parlie, and <i>Richard</i> and <i>Clarence</i>
whispers togither, and then <i>Clarence</i> takes his red Rose out of his hat, and throwes it at <i>Warwike</i>.</div>

<div class="dverse1"><span class="lnum">55</span>
 <span class="sd-cn">War.</span>
 Com Clarence come, thou wilt if <i>Warwike</i> call.</div>

<div class="dverse1"><span class="sd-cn">Cla.</span>
 Father of <i>Warwike</i>, know you what this meanes?</div>
<div class="dverse">I throw mine infamie at thee,</div>
<div class="dverse">I will not ruinate my fathers house,</div>
<div class="dverse">Who gaue his bloud to lime the stones togither,</div>
<div class="dverse"><span class="lnum">60</span>
 And set vp <i>Lancaster</i>. Thinkest thou</div>
<div class="dverse">That <i>Clarence</i> is so harsh vnnaturall,</div>
<div class="dverse">To lift his sword against his brothers life,</div>
<div class="dverse">And so proud harted <i>Warwike</i> I defie thee,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eas064" id="lnum-eas064">♦</a>
 And to my brothers turne my blushing cheekes?</div>
<div class="dverse"><span class="lnum">65</span>
 Pardon me <i>Edward</i>, for <i>I</i> haue done amisse,</div>
<div class="dverse">And <i>Richard</i> doe not frowne vpon me,</div>
<div class="dverse">For henceforth I will proue no more vnconstant.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Welcome <i>Clarence</i>, and ten times more welcome,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eas069" id="lnum-eas069">♦</a>
 Then if thou neuer hadst deserud our hate.</div>

<div class="dverse1"><span class="lnum">70</span>
 <span class="sd-cn">Glo.</span>
 Welcome good <i>Clarence</i>, this is brotherlie.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Oh passing traytor, periurd and vniust.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eas072" id="lnum-eas072">♦</a>
 <span class="sd-cn">Edw.</span>
 Now <i>Warwike</i>, wilt thou leaue</div>
<div class="dverse">The towne and fight? or shall we beate the</div>
<div class="dverse">Stones about thine eares?</div>

<div class="dverse1"><span class="lnum">75</span>
 <span class="sd-cn">War.</span>
 Why <i>I</i> am not coopt vppe heere for defence,</div>

<div class="dverse1"><span class="sd-cn">I</span>
 will awaie to Barnet presently,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eas077" id="lnum-eas077">♦</a>
 And bid thee battaile Edward if thou darest.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Yes <i>Warwike</i> he dares, and leades the waie,</div>
<div class="dverse">Lords to the field, saint <i>George</i> and victorie. <span class="sd-verseend"><i>Exeunt Omnes.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> XX.
<span class="dnavigatenf">eat</span></h3>

Alarmes, and then enter <i>Warwike</i> wounded.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Ah, who is nie? Come to me friend or foe,</div>
<div class="dverse">And tell me who is victor <i>Yorke</i> or <i>Warwike</i>?</div>
<div class="dverse">Why aske I that? my mangled bodie shewes,</div>
<div class="dverse">That I must yeeld my bodie to the earth.</div>
<div class="dverse"><span class="lnum">5</span>
 And by my fall the conquest to my foes,</div>
<div class="dverse">Thus yeelds the Cedar to the axes edge,</div>
<div class="dverse">Whose armes gaue shelter to the princelie Eagle,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eat008" id="lnum-eat008">♦</a>
 Vnder whose shade the ramping Lion slept,</div>
<div class="dverse">Whose top branch ouerpeerd Ioues spreading tree.</div>
<div class="dverse"><span class="lnum">10</span>
 The wrinkles in my browes now fild with bloud,</div>
<div class="dverse">Were likened oft to kinglie sepulchers.</div>
<div class="dverse">For who liu’d king, but <i>I</i> could dig his graue?</div>
<div class="dverse">And who durst smile, when <i>Warwike</i> bent his brow?</div>
<div class="dverse">Lo now my glorie smeerd in dust and bloud,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eat015" id="lnum-eat015">15</a>
 My parkes, my walkes, my mannors that <i>I</i> had,</div>
<div class="dverse">Euen now forsake me, and of all my lands,</div>
<div class="dverse">Is nothing left me but my bodies length.</div>

<div class="sd-entry">Enter <i>Oxford</i> and <i>Summerset.</i></div>

<div class="dverse1"><span class="sd-cn">Oxf.</span>
 Ah <i>Warwike</i>, <i>Warwike</i>, cheere vp thy selfe and liue,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eat019" id="lnum-eat019">♦</a>
 For yet thears hope enough to win the daie.</div>
<div class="dverse"><span class="lnum">20</span>
 Our warlike <i>Queene</i> with troopes is come from <i>France</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eat021" id="lnum-eat021">♦</a>
 And at <i>South-hampton</i> landed all hir traine,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eat022" id="lnum-eat022">♦</a>
 And mightst thou liue, then would we neuer flie.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 Whie then I would not flie, nor haue I now,</div>
<div class="dverse">But <i>Hercules</i> himselfe must yeeld to ods,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eat025" id="lnum-eat025">25</a>
 For manie wounds receiu’d, and manie moe repaid,</div>
<div class="dverse">Hath robd my strong knit sinews of their strength,</div>
<div class="dverse">And spite of spites needes must I yeeld to death.</div>

<div class="dverse1"><span class="sd-cn">Som.</span>
 Thy brother <i>Montague</i> hath breathd his last,</div>
<div class="dverse">And at the pangs of death I heard him crie</div>
<div class="dverse"><span class="lnum">30</span>
 And saie, commend me to my valiant brother,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eat031" id="lnum-eat031">♦</a>
 And more he would haue spoke and more he said,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eat032" id="lnum-eat032">♦</a>
 Which sounded like a clamor in a vault,</div>
<div class="dverse">That could not be distinguisht for the sound,</div>
<div class="dverse">And so the valiant <i>Montague</i> gave vp the ghost.</div>

<div class="dverse1"><span class="sd-cn">War.</span>
 What is pompe, rule, raigne, but earth and dust?</div>
<div class="dverse">And liue we how we can, yet die we must.</div>
<div class="dverse">Sweet rest his soule, flie Lords and saue your selues,</div>
<div class="dverse">For <i>Warwike</i> bids you all farewell to meet in Heauen. <span class="sd-verseend">He dies.</span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eat039" id="lnum-eat039">♦</a>
 <span class="sd-cn">Oxf</span>
 Come noble <i>Summerset</i>, lets take our horse,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eat040" id="lnum-eat040">40</a>
 And cause retrait be sounded through the campe,</div>
<div class="dverse">That all our friends that yet remaine aliue,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eat042" id="lnum-eat042">♦</a>
 Maie be awarn’d and saue themselues by flight.</div>
<div class="dverse">That done, with them weele post vnto the <i>Queene</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eat044" id="lnum-eat044">♦</a>
 And once more trie our fortune in the field. <span class="sd-verseend"><i>Ex. ambo.</i></span></div>

<div class="sd-entry">Enter <i>Edward</i>, <i>Clarence</i>, <i>Gloster</i>, with soul­diers.</div>

<div class="dverse1"><span class="lnum">45</span>
 <span class="sd-cn">Edw.</span>
  Thus still our fortune giues vs victorie,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eat046" id="lnum-eat046">♦</a>
 And girts our temples with triumphant ioies,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eat047" id="lnum-eat047">♦</a>
 The bigboond traytor <i>Warwike</i> hath breathde his last,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eat048" id="lnum-eat048">♦</a>
 And heauen this daie hath smilde vpon vs all,</div>
<div class="dverse">But in this cleere and brightsome daie,</div>
<div class="dverse"><span class="lnum">50</span>
 <i>I</i> see a blacke suspitious cloud appeare</div>
<div class="dverse">That will encounter with our glorious sunne</div>
<div class="dverse">Before he gaine his easefull westerne beames,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eat053" id="lnum-eat053">♦</a>
 I mean those powers which the <i>Queen</i> hath got in <i>Frāce</i></div>
<div class="dverse">Are landed, and meane once more to menace vs.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eat055" id="lnum-eat055">55</a>
 <span class="sd-cn">Glo.</span>
 <i>Oxford</i> and <i>Summerset</i> are fled to hir,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eat056" id="lnum-eat056">♦</a>
 And tis likelie if she haue time to breath,</div>
<div class="dverse">Her faction will be full as strong as ours.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 We are aduertisde by our louing friends,</div>
<div class="dverse">That they doe hold their course towards <i>Tewxburie</i>.</div>
<div class="dverse"><span class="lnum">60</span>
 Thither will we, for willingnes rids waie,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eat061" id="lnum-eat061">♦</a>
 And in euerie countie as we passe along,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eat062" id="lnum-eat062">♦</a>
 Our strengthes shall be augmented.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eat063" id="lnum-eat063">♦</a>
 Come lets goe, for if we slacke this faire</div>
<div class="dverse">Bright Summers daie, sharpe winters</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eat065" id="lnum-eat065">65</a>
 Showers will marre our hope for haie. <span class="sd-verseend"><i>Ex. Omnes.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> XXI.
<span class="dnavigatenf">eau</span></h3>

Enter the <i>Queene</i>, <i>Prince Edward</i>, <i>Oxford</i>, and <i>Summerset</i>, with drum and souldiers.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eau001" id="lnum-eau001">♦</a>
 <span class="sd-cn">Quee.</span>
 Welcome to <i>England</i>, my louing friends of <i>Frāce</i>,</div>
<div class="dverse">And welcome <i>Summerset</i>, and <i>Oxford</i> too.</div>
<div class="dverse">Once more haue we spread our sailes abroad,</div>
<div class="dverse">And though our tackling be almost consumde,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eau005" id="lnum-eau005">5</a>
 And <i>Warwike</i> as our maine mast ouerthrowne,</div>
<div class="dverse">Yet warlike Lords raise you that sturdie post,</div>
<div class="dverse">That beares the sailes to bring vs vnto rest,</div>
<div class="dverse">And <i>Ned</i> and <i>I</i> as willing Pilots should</div>
<div class="dverse">For once with carefull mindes guide on the sterne,</div>
<div class="dverse"><span class="lnum">10</span>
 To beare vs through that dangerous gulfe</div>
<div class="dverse">That heretofore hath swallowed vp our friends.</div>

<div class="dverse1"><span class="sd-cn">Prince.</span>
 And if there be, as God forbid there should,</div>
<div class="dverse">Amongst vs a timorous or fearefull man,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eau014" id="lnum-eau014">♦</a>
 Let him depart before the battels ioine,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eau015" id="lnum-eau015">15</a>
 Least he in time of need intise another,</div>
<div class="dverse">And so withdraw the souldiers harts from vs.</div>
<div class="dverse"><i>I</i> will not stand aloofe and bid you fight,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eau018" id="lnum-eau018">♦</a>
 But with my sword presse in the thickest thronges,</div>
<div class="dverse">And single <i>Edward</i> from his strongest guard,</div>
<div class="dverse"><span class="lnum">20</span>
 And hand to hand enforce him for to yeeld,</div>
<div class="dverse">Or leaue my bodie as witnesse of my thoughts.</div>

<div class="dverse1"><span class="sd-cn">Oxf.</span>
 Women and children of so high resolue,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eau023" id="lnum-eau023">♦</a>
 And Warriors faint, why twere perpetuall</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eau024" id="lnum-eau024">♦</a>
 Shame? Oh braue yong Prince, thy</div>
<div class="dverse"><span class="lnum">25</span>
 Noble grandfather doth liue againe in thee,</div>
<div class="dverse">Long maiest thou liue to beare his image,</div>
<div class="dverse">And to renew his glories.</div>

<div class="dverse1"><span class="sd-cn">Sum.</span>
 And he that turnes and flies when such do fight,</div>
<div class="dverse">Let him to bed, and like the Owle by daie</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eau030" id="lnum-eau030">30</a>
 Be hist, and wondered at if he arise.</div>

<div class="sd-entry">Enter a Messenger.</div>

<div class="dverse1"><span class="sd-cn">Mes.</span>
 My Lords, Duke <i>Edward</i> with a mighty power,</div>
<div class="dverse">Is marching hitherwards to fight with you.</div>

<div class="dverse1"><span class="sd-cn">Oxf.</span>
 I thought it was his pollicie, to take vs vnprouided,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eau034" id="lnum-eau034">♦</a>
 But here will we stand and fight it to the death.</div>

<div class="sd-entry">Enter king <i>Edward</i>, <i>Cla.</i>
<i>Glo.</i> <i>Hast.</i> and Soul­diers.</div>

<div class="dverse1"><span class="lnum">35</span>
 <span class="sd-cn">Edw.</span>
  See brothers, yonder stands the thornie wood,</div>
<div class="dverse">Which by Gods assistance and your prowesse,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eau037" id="lnum-eau037">♦</a>
 Shall with our swords yer night be cleane cut downe.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 Lords, Knights &amp; gentlemen, what <i>I</i> should say,</div>
<div class="dverse">My teares gainesaie, for as you see, <i>I</i> drinke</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eau040" id="lnum-eau040">40</a>
 The water of mine eies. Then no more</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eau041" id="lnum-eau041">♦</a>
 But this. <i>Henry</i> your king is prisoner</div>
<div class="dverse">In the tower, his land and all our friends</div>
<div class="dverse">Are quite distrest, and yonder standes</div>
<div class="dverse">The Wolfe that makes all this,</div>
<div class="dverse"><span class="lnum">45</span>
 Then on Gods name Lords togither cry saint <i>George</i>.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eau046" id="lnum-eau046">♦</a>
 <span class="sd-cn">All.</span>
 Saint <i>George</i> for <i>Lancaster</i>.</div>

<div class="sd-entry">Alarmes to the battell, <i>Yorke</i> flies, then the chambers be discharged. Then enter the king, <i>Cla.</i> &amp; <i>Glo.</i> and the rest, &amp; make a great shout, and crie, for <i>Yorke</i>, for <i>Yorke</i>, and then the <i>Queene</i> is taken, &amp; the prince, &amp; <i>Oxf.</i> &amp; <i>Sum.</i> and then sound and enter all againe.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Lo here a period of tumultuous broiles,</div>
<div class="dverse">Awaie with Oxford to <i>Hames</i> castell straight,</div>
<div class="dverse">For <i>Summerset</i> off with his guiltie head.</div>
<div class="dverse"><span class="lnum">50</span>
 Awaie I will not heare them speake.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eau051" id="lnum-eau051">♦</a>
 <span class="sd-cn">Oxf.</span>
 For my part Ile not trouble thee with words.
 <span class="sd-verseend"><i>Exit</i> Oxford.</span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eau052" id="lnum-eau052">♦</a>
 <span class="sd-cn">Sum.</span>
 Nor <i>I</i>, but stoope with patience to my death.
 <span class="sd-verseend"><i>Exit Sum.</i></span></div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Now <i>Edward</i> what satisfaction canst thou make,</div>
<div class="dverse">For stirring vp my subiects to rebellion?</div>

<div class="dverse1"><span class="lnum">55</span>
 <span class="sd-cn">Prin.</span>
  Speake like a subiect proud ambitious Yorke,</div>
<div class="dverse">Suppose that I am now my fathers mouth,</div>
<div class="dverse">Resigne thy chaire, and where <i>I</i> stand kneele thou,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eau058" id="lnum-eau058">♦</a>
 Whilst <i>I</i> propose the selfesame words to thee,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eau059" id="lnum-eau059">♦</a>
 Which traytor thou woudst haue me answere to.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eau060" id="lnum-eau060">60</a>
 <span class="sd-cn">Queen.</span>
  Oh that thy father had bin so resolu’d:</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eau061" id="lnum-eau061">♦</a>
 <span class="sd-cn">Glo.</span>
  That you might still haue kept your</div>
<div class="dverse">Peticote, and nere haue stolne the</div>
<div class="dverse">Breech from <i>Lancaster</i>.</div>

<div class="dverse1"><span class="sd-cn">Prince.</span>
 Let <i>Aesop</i> fable in a winters night,</div>
<div class="dverse"><span class="lnum">65</span>
 His currish Riddles sorts not with this place.</div>

<div class="dverse1"><span class="sd-cn">Glo.</span>
 By heauen brat <i>I</i>le plague you for that word.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 I, thou wast borne to be a plague to men.</div>

<div class="dverse1"><span class="sd-cn">Glo.</span>
 For Gods sake take awaie this captiue scold.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eau069" id="lnum-eau069">♦</a>
 <span class="sd-cn">Prin</span>
  Nay take away this skolding Crooktbacke rather.</div>

<div class="dverse1"><span class="lnum">70</span>
 <span class="sd-cn">Edw.</span>
 Peace wilfull boy, or <i>I</i> will tame your tongue.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eau071" id="lnum-eau071">♦</a>
 <span class="sd-cn">Cla.</span>
  Vntuterd lad thou art too malepert.</div>

<div class="dverse1"><span class="sd-cn">Prin.</span>
 <i>I</i> know my dutie, you are all vndutifull.</div>
<div class="dverse">Lasciuious <i>Edward</i>, and thou periurd <i>George</i>,</div>
<div class="dverse">And thou mishapen Dicke, I tell you all,</div>
<div class="dverse"><span class="lnum">75</span>
 I am your better, traytors as you be.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eau076" id="lnum-eau076">♦</a>
 <span class="sd-cn">Edw.</span>
  Take that, the litnes of this railer heere.</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 Oh kill me too.</div>

<div class="dverse1"><span class="sd-cn">Glo.</span>
 Marrie and shall.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eau079" id="lnum-eau079">♦</a>
 <span class="sd-cn">Edw.</span>
 Hold <i>Richard</i> hold, for we haue doone too (much alreadie.</div>

<div class="dverse1"><span class="lnum">80</span>
 <span class="sd-cn">Glo.</span>
  Why should she liue to fill the world with words?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eau081" id="lnum-eau081">♦</a>
 <span class="sd-cn">Ed.</span>
  What doth she swound? make meanes for Her recouerie?</div>

<div class="dverse1"><span class="sd-cn">Glo.</span>
 <i>Clarence,</i> excuse me to the king my brother,</div>
<div class="dverse"><i>I</i> must to London on a serious matter,</div>
<div class="dverse">Ere you come there, you shall heare more newes.</div>

<div class="dverse1"><span class="lnum">85</span>
 <span class="sd-cn">Cla.</span>
  About what, prethe tell me?</div>

<div class="dverse1"><span class="sd-cn">Glo.</span>
 The Tower man, the Tower, Ile root them out. <span class="sd-verseend"><i>Exit Gloster.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eau087" id="lnum-eau087">♦</a>
 <span class="sd-cn">Queen.</span>
 Ah <i>Ned</i>, speake to thy mother boy? ah</div>
<div class="dverse">Thou canst not speake.</div>
<div class="dverse">Traytors, Tyrants, bloudie Homicides,</div>
<div class="dverse"><span class="lnum">90</span>
 They that stabd <i>Cæsar</i> shed no bloud at all,</div>
<div class="dverse">For he was a man, this in respect a childe,</div>
<div class="dverse">And men nere spend their furie on a child,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eau093" id="lnum-eau093">♦</a>
 Whats worse then tyrant that <i>I</i> maie name,</div>
<div class="dverse">You haue no children Deuils, if you had,</div>
<div class="dverse"><span class="lnum">95</span>
 <i>T</i>he thought of them would then haue stopt your rage,</div>
<div class="dverse">But if you euer hope to haue a sonne,</div>
<div class="dverse">Looke in his youth to haue him so cut off,</div>
<div class="dverse">As Traitors you haue doone this sweet young prince.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Awaie, and beare her hence.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eau100" id="lnum-eau100">100</a>
 <span class="sd-cn">Queen.</span>
  Naie nere beare me hence, dispatch</div>
<div class="dverse">Me heere, heere sheath thy sword,</div>
<div class="dverse"><i>I</i>le pardon thee my death. Wilt thou not?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eau103" id="lnum-eau103">♦</a>
 Then <i>Clarence</i>, doe thou doe it?</div>

<div class="dverse1"><span class="sd-cn">Cla.</span>
 By Heauen I would not doe thee so much ease.</div>

<div class="dverse1"><span class="lnum">105</span>
 <span class="sd-cn">Queen.</span>
 Good <i>Clarence</i> doe, sweet Clarence kill me too.</div>

<div class="dverse1"><span class="sd-cn">Cla.</span>
 Didst thou not heare me sweare <i>I</i> would not do it?</div>

<div class="dverse1"><span class="sd-cn">Queen.</span>
 I, but thou vsest to forsweare thy selfe,</div>
<div class="dverse">Twas sinne before, but now tis charitie.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eau109" id="lnum-eau109">♦</a>
 Whears the Diuels butcher, hardfauored <i>Richard</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eau110" id="lnum-eau110">110</a>
 Richard where art thou? He is not heere,</div>
<div class="dverse">Murder is his almes deed, petitioners</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eau112" id="lnum-eau112">♦</a>
 For bloud he nere put backe.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Awaie I saie, and take her hence perforce.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eau114" id="lnum-eau114">♦</a>
 <span class="sd-cn">Queen.</span>
 So come to you and yours, as to this prince.
 <span class="sd-verseend"><i>Ex.</i></span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eau115" id="lnum-eau115">115</a>
 <span class="sd-cn">Edw.</span>
 <i>Clarence</i>, whithers <i>Gloster</i> gone?</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eau116" id="lnum-eau116">♦</a>
 <span class="sd-cn">Cla</span>
  Marrie my Lord to London, and as I gesse, to</div>
<div class="dverse">Make a bloudie supper in the Tower.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 He is sudden if a thing come in his head.</div>
<div class="dverse">Well, discharge the common souldiers with paie</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eau120" id="lnum-eau120">120</a>
 And thankes, and now let vs towards London,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eau121" id="lnum-eau121">♦</a>
 To see our gentle Queene how shee doth fare,</div>
<div class="dverse">For by this I hope shee hath a sonne for vs. <span class="sd-verseend"><i>Exeunt Omnes.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> XXII.
<span class="dnavigatenf">eav</span></h3>

Enter <i>Gloster</i> to king <i>Henry</i> in the Tower.</div>

<div class="dverse1"><span class="sd-cn">Glo.</span>
 Good day my Lord. What at your booke so hard?</div>

<div class="dverse1"><span class="sd-cn">Hen.</span>
 I my good Lord. Lord <i>I</i> should saie rather,</div>
<div class="dverse">Tis sinne to flatter, good was little better,</div>
<div class="dverse">Good <i>Gloster</i>, and good Diuell, were all alike,</div>
<div class="dverse"><span class="lnum">5</span>
 What scene of Death hath <i>Rosius</i> now to act?</div>

<div class="dverse1"><span class="sd-cn">Glo.</span>
 Suspition alwaies haunts a guiltie mind.</div>

<div class="dverse1"><span class="sd-cn">Hen.</span>
 The birde once limde doth feare the fatall bush,</div>
<div class="dverse">And I the haplesse maile to one poore bird,</div>
<div class="dverse">Haue now the fatall obiect in mine eie,</div>
<div class="dverse"><span class="lnum">10</span>
 Where my poore young was limde, was caught &amp; kild.</div>

<div class="dverse1"><span class="sd-cn">Glo.</span>
 Why, what a foole was that of Creete?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eav012" id="lnum-eav012">♦</a>
 That taught his sonne the office</div>
<div class="dverse">Of a birde, and yet for all that the poore</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eav014" id="lnum-eav014">♦</a>
 Fowle was drownde.</div>

<div class="dverse1"><span class="lnum">15</span>
 <span class="sd-cn">Hen.</span>
 <i>I Dedalus</i>, my poore sonne <i>Icarus</i>,</div>
<div class="dverse">Thy father <i>Minos</i> that denide our course,</div>
<div class="dverse">Thy brother <i>Edward</i>, the sunne that searde his wings,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eav018" id="lnum-eav018">♦</a>
 And thou the enuious gulfe that swallowed him.</div>
<div class="dverse">Oh better can my brest abide thy daggers point,</div>
<div class="dverse"><span class="lnum">20</span>
 Then can mine eares that tragike historie.</div>

<div class="dverse1"><span class="sd-cn">Glo.</span>
 Why dost thou thinke <i>I</i> am an executioner?</div>

<div class="dverse1"><span class="sd-cn">Hen.</span>
 A persecutor <i>I</i> am sure thou art,</div>
<div class="dverse">And if murdering innocents be executions,</div>
<div class="dverse">Then I know thou art an executioner.</div>

<div class="dverse1"><span class="lnum">25</span>
 <span class="sd-cn">Glo.</span>
  Thy sonne I kild for his presumption.</div>

<div class="dverse1"><span class="sd-cn">Hen.</span>
 Hadst thou bin kild when first thou didst presume,</div>
<div class="dverse">Thou hadst not liude to kill a sonne of mine,</div>
<div class="dverse">And thus <i>I</i> prophesie of thee.</div>
<div class="dverse">That manie a Widdow for her husbands death,</div>
<div class="dverse"><span class="lnum">30</span>
 And many an infants water standing eie,</div>
<div class="dverse">Widowes for their husbandes, children for their fathers,</div>
<div class="dverse">Shall curse the time that euer thou wert borne.</div>
<div class="dverse">The owle shrikt at thy birth, an euill signe,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eav034" id="lnum-eav034">♦</a>
 The night Crow cride, aboding lucklesse tune,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eav035" id="lnum-eav035">35</a>
 Dogs howld and hideous tempests shooke down trees,</div>
<div class="dverse">The Rauen rookt her on the Chimnies top,</div>
<div class="dverse">And chattering Pies in dismall discord sung,</div>
<div class="dverse">Thy mother felt more then a mothers paine,</div>
<div class="dverse">And yet brought forth lesse then a mothers hope,</div>
<div class="dverse"><span class="lnum">40</span>
 To wit: an vndigest created lumpe,</div>
<div class="dverse">Not like the fruit of such a goodly tree,</div>
<div class="dverse">Teeth hadst thou in thy head when thou wast borne,</div>
<div class="dverse">To signifie thou camst to bite the world,</div>
<div class="dverse">And if the rest be true that I haue heard,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eav045" id="lnum-eav045">45</a>
 Thou camst into the world <span class="sd-verseend">He stabs him.</span></div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eav046" id="lnum-eav046">♦</a>
 <span class="sd-cn">Glo.</span>
 Die prophet in thy speech, <i>I</i>le heare</div>
<div class="dverse">No more, for this amongst the rest, was I ordainde.</div>

<div class="dverse1"><span class="sd-cn">Hen.</span>
 <i>I</i> and for much more slaughter after this.</div>
<div class="dverse">O God forgiue my sinnes, and pardon thee. <span class="sd-verseend">He dies.</span></div>

<div class="dverse1"><span class="lnum">50</span>
 <span class="sd-cn">Glo.</span>
 What? will the aspiring bloud of <i>Lancaster</i></div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eav051" id="lnum-eav051">♦</a>
 Sinke into the ground, <i>I</i> had thought it would haue mounted,</div>
<div class="dverse">See how my sword weepes for the poore kings death.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eav053" id="lnum-eav053">♦</a>
 Now maie such purple teares be alwaies shed,</div>
<div class="dverse">For such as seeke the downefall of our house.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eav055" id="lnum-eav055">55</a>
 If anie sparke of life remaine in thee, <span class="sd-verseend">Stab him againe.</span></div>
<div class="dverse">Downe, downe to hell, and saie I sent thee thither.</div>
<div class="dverse">I that haue neither pittie, loue nor feare.</div>
<div class="dverse">Indeed twas true that <i>Henry</i> told me of,</div>
<div class="dverse">For <i>I</i> haue often heard my mother saie,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eav060" id="lnum-eav060">60</a>
 That I came into the world with my legs forward,</div>
<div class="dverse">And had I not reason thinke you to make hast,</div>
<div class="dverse">And seeke their ruines that vsurpt our rights?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eav063" id="lnum-eav063">♦</a>
 The women wept and the midwife cride,</div>
<div class="dverse">O Iesus blesse vs, he is borne with teeth.</div>
<div class="dverse"><span class="lnum">65</span>
 And so I was indeed, which plainelie signifide,</div>
<div class="dverse">That <i>I</i> should snarle and bite, and plaie the dogge.</div>
<div class="dverse">Then since Heauen hath made by bodie so,</div>
<div class="dverse">Let hell make crookt my mind to answere it.</div>
<div class="dverse">I had no father, <i>I</i> am like no father,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eav070" id="lnum-eav070">70</a>
 I haue no brothers, <i>I</i> am like no brothers,</div>
<div class="dverse">And this word <i>Loue</i> which graybeards tearme diuine,</div>
<div class="dverse">Be resident in men like one another,</div>
<div class="dverse">And not in me, I am my selfe alone.</div>
<div class="dverse"><i>Clarence</i> beware, thou keptst me from the light,</div>
<div class="dverse"><span class="lnum">75</span>
 But I will sort a pitchie daie for thee.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eav076" id="lnum-eav076">♦</a>
 For I will buz abroad such prophesies,</div>
<div class="dverse">As <i>Edward</i> shall be fearefull of his life,</div>
<div class="dverse">And then to purge his feare, Ile be thy death.</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eav079" id="lnum-eav079">♦</a>
 Henry and his sonne are gone, thou Clarence next,</div>
<div class="dverse"><span class="lnum">80</span>
 And by one and one I will dispatch the rest,</div>
<div class="dverse">Counting my selfe but bad, till I be best.</div>
<div class="dverse">Ile drag thy bodie in another roome,</div>
<div class="dverse">And triumph <i>Henry</i> in thy daie of doome. <span class="sd-verseend"><i>Exit.</i></span></div>

<div class="sd-schg section">
<h3 class="doldtime"><span class="smcaps">S<span>C.</span></span> XXIII.
<span class="dnavigatenf">eaw</span></h3>

Enter king <i>Edward</i>, <i>Queene Elizabeth</i>, and a Nurse with the young
prince, and <i>Clarence</i>, and <i>Hastings</i>, and others.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaw001" id="lnum-eaw001">♦</a>
 <span class="sd-cn">Edw.</span>
  Once more we sit in England’s royall throne,</div>
<div class="dverse">Repurchasde with the bloud of enemies,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaw003" id="lnum-eaw003">♦</a>
 What valiant foemen like to <i>Autumnes</i> corne,</div>
<div class="dverse">Haue we mow’d downe in tops of all their pride?</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaw005" id="lnum-eaw005">5</a>
 Three Dukes of <i>Summerset</i>, threefold renowmd</div>
<div class="dverse">For hardie and vndoubted champions.</div>
<div class="dverse">Two <i>Cliffords</i>, as the father and the sonne,</div>
<div class="dverse">And two <i>Northumberlands</i>, two brauer men</div>
<div class="dverse">Nere spurd their coursers at the trumpets sound.</div>
<div class="dverse"><span class="lnum">10</span>
 With them the two rough Beares, <i>Warwike</i> and <i>Montague</i>,</div>
<div class="dverse">That in their chaines fettered the kinglie Lion,</div>
<div class="dverse">And made the Forrest tremble when they roard,</div>
<div class="dverse">Thus haue we swept suspition from our seat,</div>
<div class="dverse">And made our footstoole of securitie.</div>
<div class="dverse"><span class="lnum">15</span>
 Come hither <i>Besse</i>, and let me kisse my boie,</div>
<div class="dverse">Young <i>Ned</i>, for thee, thine Vncles and my selfe,</div>
<div class="dverse">Haue in our armors watcht the Winters night,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaw018" id="lnum-eaw018">♦</a>
 Marcht all a foote in summers skalding heat,</div>
<div class="dverse">That thou mightst repossesse the crowne in peace,</div>
<div class="dverse"><span class="lnum">20</span>
 And of our labours thou shalt reape the gaine.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaw021" id="lnum-eaw021">♦</a>
 <span class="sd-cn">Glo.</span>
 <i>I</i>le blast his haruest and your head were laid,</div>
<div class="dverse">For yet I am not lookt on in the world.</div>
<div class="dverse">This shoulder was ordained so thicke to heaue,</div>
<div class="dverse">And heaue it shall some waight or breake my backe,</div>
<div class="dverse"><span class="lnum">25</span>
 Worke thou the waie, and thou shalt execute.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaw026" id="lnum-eaw026">♦</a>
 <span class="sd-cn">Edward.</span>
 <i>Clarence</i> and <i>Gloster</i>, loue my louelie Queene,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaw027" id="lnum-eaw027">♦</a>
 And kisse your princelie nephew brothers both.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaw028" id="lnum-eaw028">♦</a>
 <span class="sd-cn">Cla.</span>
 The dutie that <i>I</i> owe vnto your, Maiestie,</div>
<div class="dverse">I seale vpon the rosiate lips of this sweet babe.</div>

<div class="dverse1"><span class="lnum">30</span>
 <span class="sd-cn">Queen.</span>
  Thankes noble Clarence worthie brother thankes.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaw031" id="lnum-eaw031">♦</a>
 <span class="sd-cn">Gloster.</span>
  And that I loue the fruit from whence thou</div>
<div class="dverse">Sprangst, witnesse the louing kisse I giue the child.</div>
<div class="dverse">To saie the truth so <i>Iudas</i> kist his maister,</div>
<div class="dverse">And so he cride all haile, and meant all harme.</div>

<div class="dverse1"><span class="lnum">35</span>
 <span class="sd-cn">Edward.</span>
 Nowe am <i>I</i> seated as my soule delights,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaw036" id="lnum-eaw036">♦</a>
 Hauing my countries peace, and brothers loues.</div>

<div class="dverse1"><a class="lnum pginternal" href="#lnote-eaw037" id="lnum-eaw037">♦</a>
 <span class="sd-cn">Cla.</span>
 What will your grace haue done with <i>Margaret</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaw038" id="lnum-eaw038">♦</a>
 <i>Ranard</i> her father to the king of <i>France</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaw039" id="lnum-eaw039">♦</a>
 Hath pawnd the <i>Cyssels</i> and <i>Ierusalem</i>,</div>
<div class="dverse"><a class="lnum pginternal" href="#lnote-eaw040" id="lnum-eaw040">40</a>
 And hither haue they sent it for her ransome.</div>

<div class="dverse1"><span class="sd-cn">Edw.</span>
 Awaie with her, and wafte hir hence to <i>France</i>,</div>
<div class="dverse">And now what rests but that we spend the time,</div>
<div class="dverse">With stately Triumphs and mirthfull comicke shewes,</div>
<div class="dverse">Such as befits the pleasures of the Court.</div>
<div class="dverse"><span class="lnum">45</span>
 Sound drums and Trumpets, farewell to sower annoy,</div>
<div class="dverse">For heere <i>I</i> hope begins our lasting ioie.
 <span class="sd-verseend"><i>Exeunt Omnes.</i></span></div>

<div class="toppadb">FINIS.</div>

<div class="right toppada">
<a href="#idtoc" class="pginternal">toc</a></div>

<ul>
<li><h3 class="h3main" title="LINENOTES to The True Tragedie of Richard Duke of Yorke." id="ideln"> LINENOTES TO THE TRUE TRAGEDIE OF RICHARD DUKE
OF YORKE.</h3></li>

<li><a class="fnlabel pginternal" href="#lnum-eaa001" id="lnote-eaa001">eaa001</a>
Crookeback] <span class="nowrap">Q<sub>1</sub></span> <span class="nowrap">Q<sub>2</sub>.</span> then Crooke backe <span class="nowrap">Q<sub>3</sub>.</span></li>

<li><a class="fnlabel pginternal" href="#lnum-eaa006" id="lnote-eaa006">eaa006</a>
<i>therewith</i>] <span class="nowrap">Q<sub>1</sub></span> <span class="nowrap">Q<sub>2</sub>.</span> <i>there with</i> <span class="nowrap">Q<sub>3</sub>.</span></li>

<li><a class="fnlabel pginternal" href="#lnum-eaa008" id="lnote-eaa008">eaa008</a>
<i>the hands</i>] <span class="nowrap">Q<sub>1</sub></span> <span class="nowrap">Q<sub>2</sub>.</span> <i>th’ hands</i> <span class="nowrap">Q<sub>3</sub>.</span></li>

<li><a class="fnlabel pginternal" href="#lnum-eaa010" id="lnote-eaa010">eaa010</a>
<i>dangerouslie</i>] <span class="nowrap">Q<sub>1</sub>.</span> <i>danderously</i> <span class="nowrap">Q<sub>2</sub>.</span> <i>dangerously</i> <span class="nowrap">Q<sub>3</sub>.</span></li>

<li><a class="fnlabel pginternal" href="#lnum-eaa014" id="lnote-eaa014">eaa014</a>
<i>Bloud, whom</i>] <span class="nowrap">Q<sub>1</sub>.</span> <i>blood, Whom</i> <span class="nowrap">Q<sub>2</sub></span> <span class="nowrap">Q<sub>3</sub>.</span></li>

<li><a class="fnlabel pginternal" href="#lnum-eaa016" id="lnote-eaa016">eaa016</a>
<i>L.</i>] <span class="nowrap">Q<sub>1</sub></span> <span class="nowrap">Q<sub>2</sub>.</span> <i>Lord</i> <span class="nowrap">Q<sub>3</sub>.</span></li>

<li><a class="fnlabel pginternal" href="#lnum-eaa022" id="lnote-eaa022">eaa022</a>
<i>heauens</i>] <span class="nowrap">Q<sub>1</sub></span> <span class="nowrap">Q<sub>2</sub>.</span> <i>heauen</i> <span class="nowrap">Q<sub>3</sub>.</span></li>

<li><a class="fnlabel pginternal" href="#lnum-eaa024" id="lnote-eaa024">eaa024</a>
<i>chaire?</i>] <span class="nowrap">Q<sub>1</sub>.</span> <i>chaire;</i> <span class="nowrap">Q<sub>2</sub>.</span> <i>chaire:</i> <span class="nowrap">Q<sub>3</sub>.</span></li>

<li><a class="fnlabel pginternal" href="#lnum-eaa032" id="lnote-eaa032">eaa032</a>
<i>Violence, vnlesse</i>] <span class="nowrap">Q<sub>1</sub>.</span> <i>violenre, Vnlesse</i> <span class="nowrap">Q<sub>2</sub>.</span> <i>violence,
Vnlesse</i> <span class="nowrap">Q<sub>3</sub>.</span></li>

<li><a class="fnlabel pginternal" href="#lnum-eaa033" id="lnote-eaa033">eaa033</a>
<i>lets</i>] <span class="nowrap">Q<sub>1</sub></span> <span class="nowrap">Q<sub>2</sub>.</span> <i>let’s</i> <span class="nowrap">Q<sub>3</sub>.</span></li>

<li><a class="fnlabel pginternal" href="#lnum-eaa041" id="lnote-eaa041">eaa041</a>
<i>burd</i>] <span class="nowrap">Q<sub>1</sub>.</span> <i>bird</i> <span class="nowrap">Q<sub>2</sub></span> <span class="nowrap">Q<sub>3</sub>.</span></li>

<li><a class="fnlabel pginternal" href="#lnum-eaa042" id="lnote-eaa042">eaa042</a>
<i>Dares</i>] <span class="nowrap">Q<sub>1</sub></span> <span class="nowrap">Q<sub>2</sub>.</span> <i>Dare</i> <span class="nowrap">Q<sub>3</sub>.</span></li>

<li><a class="fnlabel pginternal" href="#lnum-eaa054" id="lnote-eaa054">eaa054</a>
<i>this,</i>] <span class="nowrap">Q<sub>1</sub>.</span> <i>this?</i> <span class="nowrap">Q<sub>2</sub></span> <span class="nowrap">Q<sub>3</sub>.</span> ¶ <i>lets</i>] <span class="nowrap">Q<sub>1</sub></span> <span class="nowrap">Q<sub>2</sub>.</span> <i>Let’s</i> <span class="nowrap">Q<sub>3</sub>.</span></li>

<li><a class="fnlabel pginternal" href="#lnum-eaa063" id="lnote-eaa063">eaa063</a>
<i>becke?</i>] <span class="nowrap">Q<sub>1</sub></span> <span class="nowrap">Q<sub>2</sub>.</span> <i>becke.</i> <span class="nowrap">Q<sub>3</sub>.</span></li>

<li><a class="fnlabel pginternal" href="#lnum-eaa064" id="lnote-eaa064">eaa064</a>,
eaa072: <i>D.</i>] <span class="nowrap">Q<sub>1</sub></span> <span class="nowrap">Q<sub>2</sub>.</span> <i>Duke</i> <span class="nowrap">Q<sub>3</sub>.</span></li>

<li><a class="fnlabel pginternal" href="#lnum-eaa073" id="lnote-eaa073">eaa073</a>
<i>mine</i>] <span class="nowrap">Q<sub>1</sub></span> <span class="nowrap">Q<sub>2</sub>.</span> <i>my</i> <span class="nowrap">Q<sub>3</sub>.</span></li>

<li><a class="fnlabel pginternal" href="#lnum-eaa078" id="lnote-eaa078">eaa078</a>
<i>that is</i>] <span class="nowrap">Q<sub>1</sub></span> <span class="nowrap">Q<sub>2</sub>.</span> <i>thats</i> <span class="nowrap">Q<sub>3</sub>.</span></li>

<li><a class="fnlabel pginternal" href="#lnum-eaa079" id="lnote-eaa079">eaa079</a>
<i>sittest</i>] <span class="nowrap">Q<sub>1</sub>.</span> <i>sitst</i> <span class="nowrap">Q<sub>2</sub></span> <span class="nowrap">Q<sub>3</sub>.</span></li>

<li><a class="fnlabel pginternal" href="#lnum-eaa082" id="lnote-eaa082">eaa082</a>
<i>Duke</i>] <span class="nowrap">Q<sub>1</sub></span> <span class="nowrap">Q<sub>3</sub>.</span> <i>D.</i> <span class="nowrap">Q<sub>2</sub>.</span></li>

<li><a class="fnlabel pginternal" href="#lnum-eaa089" id="lnote-eaa089">eaa089</a>
<i>remember it</i>] <span class="nowrap">Q<sub>1</sub></span> <span class="nowrap">Q<sub>2</sub>.</span> <i>remember ’t</i> <span class="nowrap">Q<sub>3</sub>.</span></li>

<li><a class="fnlabel pginternal" href="#lnum-eaa103" id="lnote-eaa103">eaa103</a>,
